window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_038"]={"n":"释今无","dyn":"明","poems":[{"t":"马潜庵宪副以折柬讯予参禅下手工夫及天堂地狱所以生起之因欲得二诗应命赋之 其一 参禅诗","f":"五言古诗","c":["日夕群动中，念虑自来往。","其始体空寂，奔腾自成党。","趋喧既失寂，逐暗已背朗。","有本因于无，繁亦从约长。","安得旷达人，了然发遐想。","慧刃割凡情，朱弦奏新响。","会理融百途，鞭过敌成两。","铁牛阑稻花，玉童严金杖。","此处稍偏颇，实际便卤莽。","损之复损之，神明渐空广。","垢尽铜自明，厥功乃不赏。","心境忌烦理，微乐不可享。","一涶足涴蝇，曷为羁大象。","有即吃茶条，无亦与一掌。","靡滞气便雄，非今亦非曩。","华嵩倒垂看，青天平地上。","正如夹脊间，伸手搔着痒。","家藏不龟药，勿事缏繴纺。","不须从外借，悠然满书幌。"]},{"t":"马潜庵宪副以折柬讯予参禅下手工夫及天堂地狱所以生起之因欲得二诗应命赋之 其二 天堂地狱诗","f":"五言古诗","c":["神明自圆固，犀利无与比。","皎洁自摇动，突然有念起。","起则号为妄，相继不可止。","如眼着手捏，大地如浮水。","空花落缤纷，红紫扫桃李。","谓无已见之，呼实岂正理。","其咎在伊何，不过此手耳。","手去眼自宁，乱境亦戢弭。","拙者但罪境，此境难除矣。","夜台与玉霄，空花堪比拟。","吾人一念放，不觉为物使。","才放便囿物，精华成糠秕。","弊絮逐棘途，百怒无一喜。","即此一放心，好眼忽加指。","本体既云变，境即生恶美。","金阙丽天门，琉璃浮凤尾。","洛神罗袜轻，五铢双鬟子。","玉虬驾仙飙，琼浆饮达士。","刘向列仙书，不独为我始。","重壤铸铁城，赤烧遍遐迩。","紫瞳蓝面翁，炉韛攻心肺。","陈平冠玉人，忽然成犬豕。","身既公刘虔，舌亦遭耘耔。","二境反掌间，酸甜不相似。","以为不实有，眼岂无红紫。","以为不实无，除指乃能已。","此中除指方，有虑即罪己。","内抱明白翁，步步皆能视。","如我曹溪言，知识从内扯。","正念名佛生，邪念名佛死。","一座安乐窝，年来皆颓圮。","为报高明人，相助以为理。"]},{"t":"刘两大入学宫作此勖之","f":"五言古诗","c":["汝读圣贤书，当学圣贤理。","理虽深无极，散在日用耳。","醒心体高堂，束意遇近事。","苟有欲为者，慎莫顺自己。","今既入泮宫，居然青衿矣。","功名岂有涯，所贵不在此。","既喜居人前，不足便可耻。","从今当勤学，奋志期兴起。","逆意勿为苦，他日乐无比。","黉门拜圣人，决定是君子。","严父可趋庭，良师可奉侍。","金声与玉振，于汝原可跂。","我虽老比丘，亦羡天伦喜。","父慈子则孝，此乐岂可拟。","学成见于用，有光于国史。","勿谓瀛洲远，便从今日始。"]},{"t":"陈闵孝入泮宫作此勖之","f":"五言古诗","c":["久蓄冠军才，利器尤凛烈。","岂知斗牛光，即是丰城铁。","应久跃天衢，沉郁气乃结。","滴水起长鲸，修途飞广辙。","一翼破洪濛，六月去乃歇。","碧空散笔花，文坛飞玉屑。","所少原非才，努力立名节。","圣贤亦有书，云何号明哲。","莫厌陋巷凉，独爱科名热。","非澹志不明，是欲神易灭。","古今名世人，视己犹未切。","淫书过五车，落纸成两截。","闾里岂不荣，身世已灭裂。","爱子奋其雄，俊骨标奇嵲。","进可开天阍，退亦堪立雪。","世宝何足珍，聪明天所泄。","岂容轻弃之，日削成封垤。","而父具世资，秋香不足折。","起视斯道难，每每向予说。","不倦学倒行，以智询于拙。","挟卷好趋庭，不独诗书诀。","玉虹横十丈，急以一口啜。","始知二酉山，曷可老豪杰。"]},{"t":"寿晓湘李大司寇八十一一百韵","f":"五言古诗","c":["稽古流星园，光曜至人起。","紫气函谷浮，五千论乃嚭。","浑灏仰淳风，轩黄圣化美。","夔龙际陶唐，熙载宅百揆。","道大王章正，文武通经纬。","秋官定邦典，饮羊停沈氏。","宝水耸龙门，玉节弼纲纪。","择仁古爽鸠，异绩照青史。","四百灵气钟，千波竞清泚。","介寿冈陵峻，纯禧台象炜。","外珥汉庭貂，内秘金仙理。","神凝物不疵，性彻道如矢。","玉既挺蓝田，珠复润隋水。","畴昔登俊选，沉静称素履。","经学实渊溥，燕翔赋曾梓。","螭头立豸冠，霜落封事纸。","謇謇喉舌官，大僚亦遭拟。","三辅借汲黯，鞭强如策豕。","合柱匿野王，束薪炙颜斐。","别造玉麟符，铜兽安足似。","瞿昙有遗宫，瓴甓方阙里。","玄默迈百王，恭敬及虎兕。","肥硗委荒草，一疏归僧寺。","判磨有后人，流辉无近祉。","肃肃伯囧任，盈盈耀绿珥。","和鸾驾时龙，精灼陈大议。","综辖南北谯，明镜无瑕滓。","宽明不纵察，岂独欧阳仕。","盗贼西北来，烽烟绕城埤。","力拒智何勇，潜攻寇更迤。","㼾砖日飞㩧，羽檄分迤逦。","战垒阵云深，雕戈杀气否。","清啸有馀閒，笳声发清徵。","不用五浮桥，神臂足可恃。","涡口会占风，顺昌见刘锜。","陈汤计乌孙，五日解围矣。","万灵活全城，功德布遐迩。","复坐醒心亭，酿泉酌清沚。","风回明月溪，嗒然足隐几。","守固道乃通，精专达神鬼。","轩冕悟倘来，临事自有以。","汉桓党论繁，大狱雠良士。","滂不祭皋陶，直亮见心肺。","大贤实忧国，满车驱薏苡。","平署赖陈蕃，秉笔竟如此。","致远不书黄，赵鼎忤严旨。","言切见批鳞，策免解金紫。","嗟哉千古同，事难道足比。","浮云澹河汉，春花欺卷苢。","扶策归故庐，江皋步兰芷。","耳热薄击缶，身閒气不痞。","门径敞罗浮，枕席喧海市。","言寻葛令踪，古坛见仙趾。","宝炉烧马牙，草庵生凤尾。","红树鸣夏蝉，碧池跃金鲤。","辋川乐未阑，神州见颓圮。","瞻彼玉京云，心抽无停晷。","衣白不出衡，灵武竟蒙耻。","浊水泻黄河，汀渚溷漫瀰。","厓门海气深，洪波沉二玺。","早为当局忧，声吞徒悱悱。","失手碎金瓯，禾黍日成秕。","卖卜无好桥，采薇今焉是。","噩梦静来醒，常论自可鄙。","九五蝉翼轻，轩师广成子。","东南擅竹箭，玙璠满江汜。","弓旌德泽初，文海走新使。","赵孟固不来，刘因疾未已。","古有不召臣，斯人今姓李。","不强见至德，悠悠恣步履。","社树月频圆，钓舫逢岸舣。","丹井铁桥东，青松白云里。","园种安期瓜，秋深蔓藟藟。","一食肺腑清，须髯黑如秠。","清言会有得，顿折登山齿。","春畴啭流莺，壶浆助耘耔。","手植十围松，朝夕供凭倚。","白首文潞公，法交华严喜。","不入香山会，但乘篁溪樏。","诗思急涌泉，陆离似抽芑。","烧香话君臣，一喝洞骨髓。","小义不足陈，经术皆奴婢。","餐莲千劫留，人间岁月驶。","明霞彻六窗，笑竖天龙指。","一室乐有馀，棋枰见披靡。","今春一揖翁，语笑从此始。","活火煮山茶，旧事填两耳。","招我荔枝期，添钵不能俟。","寄我自警诗，望之如浮蚁。","小字过蝇头，恰如春韡韡。","星辉南极壮，典型实丰伟。","梦叶熊罴人，一岁超于彼。","称觞集槐堂，宰割俱停止。","仁爱至今存，学解捐鄙俚。","圣教岂二衢，俗子轻訾毁。","声教簉八儒，遵勖继芳轨。","考祥此其时，如春聚百卉。","淮水吕虔刀，千阶创一戺。","我睇宝安云，满天散霞绮。","亦效开笼翁，祝声声讄讄。"]},{"t":"寿江若海","f":"五言古诗","c":["我仰江文通，起家南徐州。","笔管五色缠，谈笑取公侯。","诞此廊庙器，芳声垂千秋。","燕赵地脉雄，家世压中流。","如君风格整，洒落锦云浮。","重贤敦宿尚，利物吐嘉谋。","绿发华裾丽，银河玉浪稠。","名誉高缙绅，品德洁清修。","意气自有合，心胸不可酬。","古有崔元度，结社凝双眸。","君尤惬草野，破寺来轻舟。","弄水嚣尘歇，看花道眼留。","髣髴元紫芝，长歌陆浑游。","贯月查星上，仙风吹斗牛。","我持菖蒲节，祝君对浮丘。"]},{"t":"南池篇寿徐仲远","f":"五言古诗","c":["我住珠海旁，浪与仙城隔。","海中有遗珠，清幽变烦杂。","六月游宝水，夏云当眼白。","天上石麒麟，招寻兴不窄。","高树有凉风，清言无俗客。","捧荔擘珊瑚，停杯摈琥珀。","堂前软琉璃，微波连广陌。","小舟一荡漾，心胸开万尺。","碧树密相欹，锦鳞高自踯。","时育乐鸡豚，后凋见松柏。","眇小桃花源，荒唐鹿门宅。","明敏道自通，爱广德乃怿。","停停五色云，化为金凤翮。","我非宝上人，看君尤逸格。","花龛大品经，微言期探赜。","赋此南池篇，霞觞添玉液。"]},{"t":"寿周伯昌","f":"五言古诗","c":["昔现将军身，今为维摩诘。","维摩与将军，威慈无等匹。","霜甲耀冰河，红云涌初日。","角响万弦齐，气壮长鲸失。","转此雄猛姿，斋头亲绣佛。","参禅须铁汉，髻珠自可得。","海赤珊瑚红，山寒碧玉出。","一手挥慧剑，剿彻群魔窟。","水竭爱河源，果结菩提实。","才种白莲池，喜君入我室。","雅志迈圣贤，高谊坚胶漆。","佛法有干城，皇家多柱石。","与君玉海游，万劫从今日。","琥珀夜光珠，不如松柏质。","持此不变操，中流生六翮。","大雪满嵩山，寒风自披拂。","神椿岂计年，天浆浇茂德。"]},{"t":"寿刘焕之总戎","f":"五言古诗","c":["敦友本以仁，道合竟得天。","因思十年里，其乐如登仙。","天下有至理，散在日用前。","应其当然者，不后亦不先。","秦台善鉴物，无语列媸妍。","君子会心际，融洽亦如然。","天多气象正，静至道妙全。","颖南产奇士，志气自刚坚。","少小偶失途，髫龀长烽烟。","突马解战斗，看剑摇山川。","因探河洛数，便窥孔孟传。","怀秘寡徒侣，抗调难和篇。","与余一定交，万古破拘挛。","两宗聚讼久，真义竟未宣。","有离亦有合，有全亦有偏。","共坐广居堂，挑灯常不眠。","剔微语俱涩，默对如蜕蝉。","忽而憬然起，大笑泻飞泉。","语默动静间，殆无有遗璇。","既能明曩哲，又复资玩研。","金张何足问，管鲍亦非贤。","情好醇已笃，骨肉相牵连。","髣髴同所遇，髣髴情堪怜。","只愁非麋鹿，会上别离船。","癸丑秋才深，余果游幽燕。","乾坤随震荡，戎马踏春田。","五岭亦多事，分镇日催迁。","锁钥寄连阳，所事在两肩。","早曾学军旅，气可吞九埏。","如珠只走盘，如珠不在毡。","以其所蕴者，施于牙纛边。","予既归五羊，不得相周旋。","时时发清梦，同诵锦云笺。","仲冬乃君诞，昂首祝斗躔。","人生建令名，学术不弃捐。","可知澄清辔，即是祖生鞭。","愿为台与莱，芘物长芊芊。","慰我非一途，无用真枯禅。"]},{"t":"送姚嗣昭太守复任雄州","f":"五言古诗","c":["居心本纯和，所用唯天真。","福德天自与，其权不在人。","风雨有时晦，星月无比伦。","嗟哉凌江守，一岁受艰辛。","赋诗养端默，纵奕运精神。","忽睹纶綍光，锁钥仍北宸。","揽云驱熊轼，隼旟动行尘。","父老识旧官，抚摩识吾民。","上下相孚洽，二邑流深春。","始知天道近，励节为贤臣。","龚黄有足称，所贵勉于仁。","静坐梅花署，幽香可独亲。"]},{"t":"平黎曲","f":"五言古诗","c":["大块微生事，声教良最仁。","椎髻习枭性，剿脔无完身。","异类斥不育，雨露匪不均。","珠崖拟弃捐，鳞介难具陈。","德泽更千载，文物冠京津。","四水环十邑，五指削天垠。","巢居负深险，豕突雅难驯。","画臂肖沉木，弯弓即鬻獯。","鸠集乃叫呼，敢为猬与蚊。","虎竹怫分阃，桓桓策六军。","六军信神武，所事在征讨。","月竁昔来宾，日际曾奉土。","况兹未重译，蠢尔轻明主。","大国德良亏，瑶阶缺千羽。","防风杀二龙，不死见夏禹。","大火方西流，日色草木枯。","马蝗煽青燐，金牛暗毒雨。","卸甲陟崇阿，免胄散行伍。","料敌何必深，超距欲如虎。","溪谷多嶙峋，所事在两股。","树杪出金钲，阴岩潜玉弩。","不怨从军难，所虑空村堵。","一鸡响毗耶，驱蜂走神姥。","所冀良牧仁，恻然动安抚。","革心归所天，文教被终古。","请移铜柱标，相看忘黠虏。"]},{"t":"琼山诸秀才秋闱不第诗送之归","f":"五言古诗","c":["男儿负所学，挟笔干时贤。","所求贵得志，展翼青云巅。","家住扶桑下，门临铜柱边。","海水一万里，崎岖路几千。","只身涉溟渤，行李滋蛮烟。","富贵如可求，艰难甘弃捐。","讵意竹箭流，还教点额旋。","孙阳实未来，绝尘徒自怜。","且归玩沧海，五车恣幽研。","他年一昂首，自然摩高天。","石房垂椰叶，芸室烧龙涎。","药苗穿篱秀，秋韭割来鲜。","烹鸡下美酒，茉莉薰昼眠。","人生有如此，圭组何必先。","我本谈空士，旧游曾留连。","道义既云合，交情良亦坚。","相订或重来，开池种白莲。","今转送君去，殷勤一赠言。","客路日易短，寒螀啼君前。","悲欢岂有定，倚仗久难诠。","五尺何多力，万事如钩连。","秉心皈绣佛，胜着祖生鞭。"]},{"t":"古渡渔翁","f":"五言古诗","c":["归舟古渡头，水急沙力薄。","参差水竹中，石头何磊落。","高浪见渔翁，肤黑发益白。","尽日守缯缴，交谈见素朴。","称彼读书人，云是游仙客。","家住河上村，近亦走风鹤。","天不眷微生，难以事耕凿。","膝边两小儿，食鱼弃鱼骼。","岂知翁力竭，十缯九不获。","世路多艰虞，人生苦缠縳。","万事可镜心，兹游信行乐。"]},{"t":"寄诃衍","f":"五言古诗","c":["萧索大漠风，解割不解吹。","六月大夏日，解热不解凉。","惭愧道人心，解露不解藏。","的立万矢聚，水渍石易伤。","人生不如石，况复重忙忙。","悲欢皆损性，静躁同一狂。","丈夫当有志，悲道不悲世。","只此悲道心，靡然见罢敝。","丈夫当有识，欣道不欣食。","只此欣道心，悠然被驱役。","智者路多穷，愚人幸不识。","去年芜湖月，今年起相忆。","忆君一寄君，君癖我更癖。","何当共黾勉，挽以千牛力。","蒿枝三寸曲，松根百尺直。","秋风才一吹，各自理颜色。"]},{"t":"唁知即","f":"五言古诗","c":["搆屋须良材，楚僧领此役。","不畏北风寒，不避豺虎食。","披蓁陟崇阿，两足罗荆棘。","得木放中流，倏忽天宇黑。","陈桥既易王，各郡未捧檄。","盗贼变路人，草木皆锋镝。","一衲百结馀，竟与貂裘敌。","四逢狄梁公，褫夺遭辟易。","蚊虻咋肌肤，风涛啮指骨。","辛苦两月来，生死换得失。","依稀尾生信，髣髴盲龟值。","将军略地来，川陆皆罗织。","不必问珠玑，粗岂遗木殖。","嗟哉竟徒劳，抱病空叹惜。"]},{"t":"清明","f":"五言古诗","c":["西南天一方，风沙惨日色。","欲陟彼高处，支离自不力。","满道飞纸钱，我且将安适。","塞上小儿女，哭声一何极。","哭声不可闻，哭辞人不识。","抱书上床眠，眠去省太息。"]},{"t":"鸟","f":"五言古诗","c":["一鸟投深林，千群竞相逐。","始知鸟雀心，亦不事孤独。","朝引出郊原，暮引归空谷。","秋叫秋霜寒，春鸣春草绿。","谁云乞野人，一块果天福。","谁嗟白额鱼，却为豫且辱。","荣辱宁几何，一身苦不足。","但食沙边鱼，莫啄田中粟。","粟本人所争，争心起倾覆。","一旦布网罗，却同鱼与肉。"]},{"t":"送王伯子还宁晋","f":"七言古诗","c":["我昔张帆游琼海，天荒地老愁心改。","木客红唇啸益悲，鲛人泪眼珠难采。","连石日沉天地昏，妖氛瘴雾如飞尘。","此身已作仲文树，无复生意当青春。","斯时得交王大令，飘飘仙气更氤氲。","琴声不特吏难欺，还将大略息疮痍。","不种河阳满县花，笔端富丽自豪华。","赠予墨滓过一斗，身虽圭组志烟霞。","如今北归朝绛阙，留连惜别珠江月。","珠江月色清尤寒，征帆关切到征鞍。","太行秋声井陉里，昔时惯入乞人耳。","送君不怨道路长，至今能梦滹沱水。"]},{"t":"寿姚六康明府","f":"七言古诗","c":["昆山斲结不斲离，碫锋淬锷有所为。","芳春兰蕊老秋发，浓香蕴蓄终无时。","大贤况复秉宿志，解断悬缚肌疮痍。","惠阳姚君蕴藉深，豪杰气谊贤圣心。","才华赫誉渐过耳，老却竹箭淹南金。","宽和髯颊如春温，昔因不类人间人。","国之桢干法门柱，东阿白凤西山麟。","属吾师翁早投契，白衣弟子缁幅巾。","四百名峰遗刹地，护之若护睛中尘。","赤髭白足频来往，山阴道上欲分身。","秋深结束趋朝右，组带曳腰符系肘。","仁心义术希所济，肯厌蹄轮竞趋走。","畴昔逢君燕蓟遥，银缸雪盌凌晨宵。","道心尘事两融彻，磈礧廓落沙尘销。","眼空三辅豪华燄，气夺五陵裘马骄。","古来贤达各有重，富张杨李皆高僚。","庆君揽揆服官年，沆瀣辉流丽日边。","祝君固比金刚体，东南流峙尽浮烟。"]},{"t":"榴花歌赠王九如","f":"楚辞体","c":["君不见竹林之下高韵长，高阳徒侣当年亦复气锵锵。","更有庐山谷，醉石之上陶元亮。","偃蹇肮脏并閒雅，胸中笔底汪汪乎不可一世而跌宕。","岭南鼻饮有古风榴花香，况乃产乎王生之故乡。","醁酃虽美不足尝，不足尝乡中之物浇中肠。","锦心绣口成文章，眼底青云看可上。","手中綵笔人莫当，吾将欲与王生招隐泉，三生石上恣商量。","使汝一杯兮，乃知乎向者八人之膏肓。"]},{"t":"寿陈蕉源","f":"七言古诗","c":["我闻金色妙智身，坚密过于金刚宝。","倒易三世如飞腾，寰中日月那能数。","桧柏苍松薄劣根，南山东海成轻尘。","有大长者陈居士，妙得此智凌青春。","修长须髯梅花白，舌底风流妙入神。","大智文殊七佛师，福成利行号童子。","我今已老君方少，坐饮山茶勿序齿。","更睡华山八百年，制成竹马呼君起。"]},{"t":"题王伯子四雅亭","f":"七言古诗","c":["偶亭主人清且贤，弹琴问政何翩翩。","黎童蛮女歌来暮，渡海孤僧逢偏早。","文章词赋日相投，一别三年长秋草。","去秋又搆四雅亭，衣冠满座百壶倾。","习家池馆日相求，竹林之下风飕飕。","棋声诗思皆劲敌，即此可以凌王侯。","中少一幅乞人笔，续貂岂堪容此物。","濡毫树底为君挥，胜事留传在翠微。"]},{"t":"别张子修","f":"七言古诗","c":["张子肮脏绝不羁，襟期独与山人知。","弯弓跨马聊尔尔，种竹栽麻乃其宜。","吁嗟张子奇不奇，世人皮相何足悲。","大宋有僧交子修，崎岖同到琼之涯。","我今事迹复类此，别去情深长相思。"]},{"t":"别陈人白","f":"楚辞体","c":["我来海外交陈君，陈君明爽绝不群。","煮茗夜谈日继之，眼昏喉尰犹未离。","激昂大道无馀蕴，探颐至理尽精微。","人生聚会如大梦，车尘之下不可知。","陈君有文我能削，陈君有过我敢摘。","陈君爱我非在此，我爱陈君亦如彼。","有文有行世不少，功高名大看愈小。","一身众患岂能当，予与陈君后话长。","苦莫苦兮疹饥骨，余犹视之如饴蜜。","乐莫乐兮拥舞女，余正视之如刀锯。","我语陈君受不失，此情十分未去一。","君不见海门之水深且宽，君不见五指之山高且嵂。","山高河广会自稀，忠告之言莫置之。","我今别君挥手去，相思常在月明时。"]},{"t":"丘太史曙戒过访海幢将归风雨大作留同王震生程周量梁兰友梁芝五澹归夜话分赋","f":"七言古诗","c":["峣嶷岗埠精庐隐，百雉斜临高幡引。","入树蝉声尽日长，流涎衲子香炉冷。","幰盖华轩藻寺门，鸟窠倒履迎旟隼。","白傅裴休俊玉容，烟霞洒落生心腔。","青云自合腾圭璧，禅机旋转光玲珑。","柱杖芭蕉非我与，金山玉带解诸公。","琢成楮叶杂春芽，绝肖何必青莲花。","老僧瞺瞪不得语，自然白石成丹砂。","五马催呼归兴失，三门移睇浮云黑。","零陵山石自纷飞，金波昨夜先离毕。","咫尺烟涛上下翻，鼋鼍吐电蛟龙泣。","憍尸迦主献瞿昙，阿修罗殿满剑戟。","隐几更坐成欢笑，本来面目一时得。","血红鲤眼寒光闪，海飙几阵连天捲。","不劳石汁铸琉璃，平地贝阙生光辉。","缩脚抠衣不及语，双门乍启真珠飞。","秉烛高谈幽思动，含毫扫纸抒冰姿。","冰姿自带漭泱色，万顷沧溟归一滴。","芥子空穴驻须弥，笔端三昧通禅力。","痴憨犹不许旁观，木枕才醒东既白。","津吏频呼渡头船，芳尘杂沓凌朝烟。","心赏窈蔼不可期，廊庙山林齐置之。","分襟熊轼拥前驱，始知贵贱忘多时。"]},{"t":"题伍铁山牡丹转赠李言兑","f":"七言古诗","c":["鸠艾山人蓄奇思，泼墨时画牡丹树。","浓淡轻盈比赵昌，葳蕤枝叶精神藏。","富贵自然天上落，烟云眼底相翱翔。","去年寄我此一幅，古道春风常在目。","有时挂壁对枯禅，恰如陆亘遇南泉。","同根万物异非异，明珠一粒走冰盘。","吁嗟山人得志时，綵笔战胜万人知。","澄清壮志今已矣，考槃歌彻山之嵋。","金支瑶草恣幽采，颜如渥丹色不改。","人生出处固有定，适意何必皆高车。","吾友李君琼之秀，精鍊一经今白首。","文情跌宕自激昂，丰城之气终干斗。","今年见弃未称意，牢骚别我还分手。","分手索我此画图，赠君胜赠金错刀。","琼海之波千尺涛，关情送远秋云高。","归去烧香静披对，静定方知动者劳。"]},{"t":"赠高文斗","f":"古风","c":["华山渭水秀灵钟，半千嘉运诞英雄。","弯弓射杀霸陵虎，用兵髣髴孙吴公。","高郎洒落为元子，天容道骨轩仙风。","虎帐趋庭寒剑气，天边结友敦高风。","下帷默与圣贤对，钩深索隐皆旁通。","肝肠盘屈叠丽锦，心胸洞彻光玲珑。","文章气力长万丈，那应笔梦生春虹。","山僧素有孝基眼，观人虽众无如公。","抵掌快谈恨已晚，区区作别订重逢。","君不见浮粟之水清且幽，斩荆拨草君所谋。","我行当作陆沉士，华轩鹤盖期一至。","一夜清灯数茗杯，寒山世事两徘徊。","秋风触处无高下，行人畏上越王台。"]},{"t":"壬寅春三月石鉴覞弟奉师命入阊门为先师翁乞塔铭于钱牧斋先生赋此为赠","f":"七言古诗","c":["吾翁早具金刚眼，照耀大千无间歇。","去秋忽唱还乡行，谁识双林未入灭。","四百罗浮山君长，守护无缝威凛烈。","譬如皓月被云掩，是月光明岂曾歇。","眼光所照亦复然，妄情瞥起即区别。","还将佛子区别智，消尽妄情光不二。","江南姑熟有虞山，山中长者名远被。","如椽大笔干云汉，电抹风摇生妙义。","点笔此光出笔端，恰与长者同巴鼻。","石弟克绍吾家种，代师远走五千里。","褦襶久藏妙喜机，笑揖张君等儿戏。","出门一句为余言，始信脚根方点地。"]},{"t":"寿程万閒","f":"七言古诗","c":["我闻七宝功德山，金盘流出耀人寰。","光明威德咸炽盛，双融真俗如冰环。","此光岂特世间珍，诸佛护念非等閒。","琉璃玻瓈红玛瑙，帝青摩尼及众宝。","杂此宝燄光明云，现此金刚坚密身。","大地山川多藻丽，此光照处皆成文。","菩提座隐烟雾中，廓清能使人皆见。","法螺吹动海波寒，扶桑映彻须弥面。","万閒道兄法之幢，百福庄严众所羡。","灵峰亲受付嘱来，此身却向宰官现。","才生气便可凌霜，梅花万片相翱翔。","大离垢缯为冠弁，妙得真智何昂藏。","戴笠吾输出入机，恰如百灵遇老庞。","愿汝住劫自绵长，我作此偈为赞扬，万象森罗齐合掌。"]},{"t":"题赵裕子绘卫天山寿山图","f":"七言古诗","c":["燕然之山雄九边，盘拱玉京如环连。","层冰叠雪气蒸郁，千松万柏寒参天。","裕子赵君臂有神，点染纸笔描逼真。","命意初不在此山，微得其气已惊人。","裕子八十已过五，骨形如鹤神踽踽。","双鬓不减燕然雪，才华跌宕秋江月。","银筒丹井不须窥，笑持荷叶胜刀圭。","天山礧砢殆其俦，村头独坐疑沧洲。","万事若能随手歇，置身此幅堪夷犹。"]},{"t":"楼阁篇为彭明府退庵寿","f":"七言古诗","c":["有大丈夫古之哲，丰姿明敏神欢悦。","声价人天号大慈，百福归之如聚月。","现为楼阁高七层，窗牖栏楯悬奇缯。","赤珠璎珞宝网垂，金铎迎风声泠泠。","此阁凡庸不能见，实相求之如掣电。","白凤至今不可巢，沉香结束何足羡。","我观智海软琉璃，无有远迩及崇卑。","上下千年一瞬间，寒云自走孤月閒。","妙得此意凌万物，坐令仁寿当自还。","阎浮界内无此阁，即令有之亦糟粕。","道力业力等齐观，檐风吼月恣行乐。","番禺邑侯彭大士，醇粹天资白玉美。","光芒焜耀四边驰，一粒摩尼旋众水。","峨嵋峰上钟灵秀，巍巍慧业善财后。","不参烟水亦南来，斗大铜符深系肘。","平生学术见驱鸡，百里宣风今卓茂。","治中有山名雷峰，长松大竹颇灵透。","拟为此阁架虬蜺，烟走星飞生渗漏。","问政时临阁上行，绣栌朱柱何曾有。","伫立逦迤绿水溅，还如弹指未开前。","大士忽然一弹指，重重楹槛敞高轩。","阁门开处莲花白，服之能住百千劫。","我作此篇以寿君，文殊狮子翻身踯。"]},{"t":"寄送郑季生赴都补选","f":"古风","c":["黄金台畔七年前，野僧添钵擎朝烟。","雪瘦?毵归绝域，相逢郑谷偏留连。","郑君气格五色锦，翠云裘着斑玉笋。","文体风流亚大苏，轻世重道世所无。","捉麈天花虽未雨，霜飘雪荡心魂孤。","长安贵客如玉丛，不谈此道空悤悤。","芦沟之水有针投，千古万古开心胸。","我返仙羊君亦归，去年相见更玲珑。","鹤岭松风西湖月，行座摩娑无巧拙。","道质化为火里莲，宝剑当空恣予夺。","学术取为干国材，逸足终当一超绝。","今冬结束复出关，袖中富贵气本閒。","毗卢印佩黎元喜，世出世间无远迩。","送君翘首隔罗浮，飞烟簇簇乘风起。"]},{"t":"与胡潜夫乞药戏赠","f":"古风","c":["借问胡潜老，如何药似神。","一杯才仰饮，五内觉津津。","须臾谷气次第出，博山沉麝那能敌。","胸中积滞得轻松，虽留微痛意已适。","夜来齿腭发澹味，舌根却似寒泉洗。","澹极依稀翻胃来，寒热之气想分开。","今日更乞下一帖，午后便欲得煎煨。","除痛除澹最要紧，二竖若去即安枕。","药赋烦君念一遍，轻重加减见本领。","医王之手见高处，医王兼更有佳句。","昨闻和得岑字诗，悤悤未问君已去。","诗学离骚让楚中，楚歌一起皆天风。","离奇崒嵂兼光怪，使人读之声浑雄。","豫章未必胜楚材，此事还须自问公。","费君之药亦此事，病根无日得轻利。","一捧楚诗开口笑，邪风尽入病难料。","药囊更蓄五色线，肠若断时君不见。","但闻推折擘缯声，须君下手如飞箭。"]},{"t":"王观察斋头有石寿星伴鹿而坐作此长歌","f":"七言古诗","c":["鸡窝老人古仙客，长髭大额不盈尺。","好与圯上先辈游，入海化作丝文石。","河伯之宫虬与龙，鞭水行雨多阴风。","老人总不任智力，妙与太极归洪濛。","当时鹿亦解人意，呼之俱化形无异。","蟠桃称寿事有无，或前或后那能记。","娲皇炼石石上天，以其馀者沉深渊。","老人视之如儿戏，不与此石相周旋。","一从立极人民著，危微变幻归何处。","制成文字记升沈，几度江山换云树。","尧天十日光先徂，金人十二今有无。","已将身世悬大象，看穷造化笑玄都。","观察斋头频过我，老人亦向斋头坐。","濠梁小景饶仙风，何必蓬莱深处卧。"]},{"t":"诵祝唵哒公","f":"七言古诗","c":["缙云缭绕蔚巃嵷，瑞气腾光结綵虹。","非烟熠熠耀寰宇，千寻宝色临青松。","昆崙顶上须弥巅，虹光蟠覆万斯年。","璇瑰瑶碧为其质，金风吹彻愈贞坚。","麟麟炳炳自巍峨，郁为霖雨汇沧波。","佛子俱登仁寿域，古椿大柏庆天和。","威德智力等十方，芳声千古流无极。","宝髻护念自非常，威光又过百千亿。","慈惠普洽诸群生，福愿更深功德海。","琼池玉壑恣晏游，丹书白马金縢在。","筵开玳瑁拍洪崖，盌赋琉璃浮沆瀣。","桂山兰板日归仁，西园几见曾飞盖。","种种杂为如意珠，智境庄严了无碍。","山僧祝此光明云，磬声奕奕动苍旻，百粤长此扇氤氲。"]},{"t":"寿固山永言尚将军","f":"七言古诗","c":["百粤惠风吹瑞草，星光耿耿长庚老。","寰海之区光浸中，仁寿同歌兼社舞。","银花火树太平年，山川带砺入幽妍。","白昴之精跃申甫，一柱擎天见神武。","六师总辔雄且贤，金章紫绶何翩翩。","万里霜威誇逸足，三生灵慧长青莲。","青莲千叶照碧波，我观佛种亦维摩。","现身暂佩水苍玉，手调阴阳分太和。","文焕夺将颔下彩，威光还过髻中螺。","几回顾我生颜色，贵贱相忘笑语历。","王臣曾受付嘱来，山僧敢献三多祝。"]},{"t":"重九前三日彭退庵诠部汪汉翀水部招同王象先朱监师张雏隐梁芝五游蒲涧寺分赋得士字","f":"七言古诗","c":["扶胥空濛赤日起，白云山影秋声里。","天风不吹平陆人，羊肠独挂寒泉水。","山涛水部拉高朋，兼我閒閒一个僧。","平生未到白云游，兹游兴发如飞腾。","初行放眼无可放，草草松篁空怅望。","拍肩意有洪厓公，片石亦令心神荡。","菖蒲涧底登顿来，安期岩畔吾先丧。","钩连石路空嵯峨，荒冈大脊拖明河。","玉山易醉围金客，丹嶂难寻跨鹤窝。","当时退之走华岳，玉箸双啼下不得。","今日虽然涕未横，要使腰肢光辟易。","帘泉滴水差解意，摩空一石尤苍翠。","静窅悠然虚谷中，回风斜入寒光坠。","来往摩娑不欲行，霏霏散雪时侵地。","乍可烟霞一念深，等閒事业堪抛弃。","一酌山泉酒十卮，人间至乐得斯时。","恰似生还班定远，高眠水部即安期。","嗟吁匡岳称名山，礧砢奇削出云间。","横斜百里深黛色，仙姝媚妩盘双鬟。","石磴丹梯鬼斧雄，龙蛇光怪有无中。","湖风乍捲亦明灭，雪后苍厓玉不同。","问予何事轻离此，却作珠江寒乞士。"]},{"t":"贺高总戎移镇高州","f":"七言古诗","c":["十年琼海建旌旄，奠安黎庶赖良图。","专征岂特腾茂伐，甘棠之树已先高。","南极威声驱溟渤，关西巨望称贤劳。","风云吐气有馀奇，胸中兵甲谁可窥。","圯上曾闻有法传，匡时异绩看巍巍。","绣靴画鼓拥康庄，福星今又借高凉。","歌颂万家安寿域，控弦千里凛风霜。","念我曾蒙颇牧知，情深载笔即吹篪。","玉帐帡幪气自温，柳阴借荫心怡怡。","三年别去长相思，又来弹铗诵新诗，首图麟阁效心碑。"]},{"t":"寿赵太守雨三","f":"七言古诗","c":["缑山山上鹤发翁，丹颜玉指握芙蓉。","霞光掩映五色珠，八方分照无遗踪。","至人出入三世境，冰环圆转看无穷。","夏口松间和璞瓮，永禅师德清光共。","不识银河蛰一龙，但看碧树翔双凤。","文藻飞扬蜀大苏，谪仙天上事非诬。","宝公自识麒麟种，孝穆当年智力孤。","韶阳郡守赵使君，中州正气摩青云。","琼浆润泽冰雪操，治绩不特敷清芬。","前身便是吉祥士，连联百岁隔纱纹。","修成仁爱笔花发，千尺松根恣茂达。","濯锦池边月影圆，黄河岸里波声阔。","华藏门开帝网正，琉璃塔上悬明镜。","弦歌既彻九成台，霜威先起蟠桃岭。","龟章力大佛印小，应身大士如飞鸟。","神明披朗器高浚，秘用其权通窈窅。","初揖使若花树旁，恰如按指河岳光。","喻法青莲当昼静，驱风白石声琅琅。","品花觅草时相过，不须清磬烦嚣堕。","陆亘石头用一呼，长庆蒲团经七破。","琴鹤俨然清献公，作诗我与华严同。","祝君一语为君寿，自然坚固昆吾铜。"]},{"t":"寿陆太守孝山","f":"七言古诗","c":["安期岩下丹砂井，清波静涵牂牁影。","牂牁万派自奔腾，群趋尽绕梅花岭。","百粤之山此岭雄，乔松千本常菁葱。","服灵琥珀出千载，夜光紫气参洪濛。","琅玕不羡朱明竹，玉骨那数浮丘公。","当湖互见清波起，敷渥此岭沾穹窿。","穗岐乐诵张君淑，神雀高飞黄次翁。","洁白之姿过冰雪，譬如梅花开腊月。","又如帝网悬天门，重重摄入皆欢悦。","冬日煦人成物我，春风拂地滋薇蕨。","布政十年心自閒，绀宫几处垂高樾。","我捧玉函金字经，每寻妙理恣玄说。","欢喜园中下璎珞，华严位里施钳钺。","使君一为应现身，两边运护如车轮。","霜刀鼎起荆山玉，巨照晃耀灵川神。","温然弘裕成虚引，美哉道重高缙绅。","挹君已饱灵和气，自然枯槁皆青春。","木樨香散岭头来，碧波深处无纤尘。","一句可能踰十劫，祝君此句高嶙峋。"]},{"t":"荔枝行送彭进士骏孙归海盐","f":"七言古诗","c":["岭南四月荔枝红，岭南五月荔枝熟。","村头镇日鸣高蝉，紫云片片出深绿。","此果众美难具陈，譬如上妙生天福。","苏陀长吸色如虹，夏日不愿游天中。","双环天女五铢纱，葳蕤璎珞逗红霞。","曾疑葛令骨飞去，窃之并上七金槎。","琉璃青碧拥月宫，扶疏不与桂枝同。","圆生香气三百里，不及冰团浮玉指。","维摩老大神力疲，白饭不取今来此。","东坡信亦谪仙人，忘情惟有鍊家紫。","羡门彭子骨如仙，姓字久已人间传。","初来即入罗浮下，宝水诗篇恣潇洒。","一见未揖笑语投，摩尼明透走金瓯。","清风百道衡门起，伫见文鸾参凤尾。","荔枝不食买归船，胸中只说莼羹美。","荔枝能益道心强，留君不住意偏长。"]},{"t":"合浦歌为强佑人寿","f":"七言古诗","c":["青婴池水清而丽，大珰老蚌潜千岁。","天涯亭畔岸不枯，珊瑚树上巢翡翠。","数百年间事亦奇，珠玉无知亦有知。","长官意大此珠少，月照珠池波渺渺。","淮夷之蠙独擅名，蓬苇参天铜柱小。","钦州竹马迎偏早，要芟还珠亭上草。","孟尝陶弼几时来，一探深渊誇至宝。","关西将军颇少年，分竹策马珠池边。","明透之性掩珠光，叱咤左右河海忙。","朝餐晚餐萱草根，辕门日静甑生尘。","池里珠还千万斛，将军碎之其如粥。","地小材大用不尽，閒时把笔娱心目。","笔端一落绝惊人，不是颜骨决柳筋。","立功归来绣佛前，綵衣五色斑襕鲜。","至性夙敦过颜闵，几回感我呼高天。","人生重节乃豪雄，看君坚固昆吾铜。","览揆为君说此篇，春风恰好吹华筵。","烧残银烛渡江来，月高与尔谈深禅。"]},{"t":"寿凌司李髭放","f":"七言古诗","c":["昆吾山铜风轮持，宝光灼烁来无时。","晦昧奔腾碧虚阔，沧溟渺小连天池。","澄渟念想须弥起，大劫小劫分远迩。","佛子灵根岂受薰，威光百道翔身云。","琉璃椀合金刚眼，一回朴破看高旻。","韶阳长者淩髭放，海内名声皆普闻。","昔年谒帝明光殿，毗卢印佩如轰电。","语言文字三昧门，天花洒落填笔砚。","暂持行愿游八极，还捧智珠归净域。","又见遗民山下来，已看硕果终难食。","丹霞山头路颇滑，独往叩关无杖策。","玉蕤乍吸骨如风，低视人閒万象同。","百灵庞蕴酣法战，至今电击声雄雄。","金针乍路该全隐，长者须防瞌睡翁。","松根一拂超千劫，所有微言背剩说。","海幢输却老婆禅，老猿啸起天边月。"]},{"t":"白莲华颂三十三韵寿朱明府","f":"七言古诗","c":["莲花如雪映雪衢，千年一抽世所无。","芰茎蔤叶七宝须，天风掣击如飞凫。","众香骈附若奔趋，采而食之留身躯。","紫红立变儿童肤，譬如玛瑙籍红氍。","慧性光透如明珠，上下千岁事难诬。","此花自与异花殊，草木之卉非根株。","至人取譬晓大儒，心性皎洁即此乎。","事物纷纭心力孤，譬如此花不出湖。","此花一出事物徂，兀然隐几或据梧。","当年葛令乞分符，金丹辛苦烧红炉。","身轻鹤骨玉龙驱，不见此花终踌躇。","南海朱侯得机枢，政成事暇日执觚。","德泽润人若醍醐，掀髯对我如藐姑。","几度烧香诵良谟，竹窗蓬窦锦云铺。","王臣外护深庇吾，长至之后逢悬弧。","为君说此如辘轳，视履考祥终不渝，此花千载生冰壶。"]},{"t":"书生入戎马之场歌赠夏继先兼送还镇海安","f":"古风","c":["君不见当年班生投笔起，骞腾宝剑驱千里。","风云气节相激昂，富贵功名堪自取。","伏生九十诵陈经，烈士敲碎玉壶冰。","壮心不使暮年惜，绿发成名入青冥。","我观夏生骨节奇，青衫弃却扬清徽。","龙骧凛凛誇逸足，双瞳闪闪长庚微。","经学丹青精以练，杜公武库何须羡。","赞匡果毅取临时，金刚玉润如轰电。","横海楼船见大旌，修成战具东瓯平。","铜柱界边宽眼力，吟成好句彻沧溟。","两年驻纛五羊东，扁舟萧寺时相逢。","笑语但看鸥鸟下，此心不向时人通。","牛头道者智威师，重岩学道悬雕弓。","今日送君归旧镇，疮痍息后期芳踪。"]},{"t":"寿李慧庵","f":"七言古诗","c":["方山长者奇而秀，枣柏延年驱麦豆。","神管重岩侍玉龙，齿颊光明烂如昼。","智慧花生华藏门，十兆九万皆灵透。","金台佛种诞偏长，慧庵李子乃其后。","吉祥之草两手持，梵刹随地建无时。","珊瑚玛瑙夜光珠，螺丝宝髻严金躯。","三千座广一室小，须臾取供如飞鸟。","童子惯闻上品经，家人亦礼莲花表。","膝边光彩看凤毛，阶前作舞拖青袍。","慧业不须江淹笔，功名可得吕虔刀。","大地春归一日长，天花缭绕天人想。","我说此偈祝永年，磬声清韵泻高泉。"]},{"t":"寿邝檗庵","f":"七言古诗","c":["寺门千顷碧琉璃，烧香独对閒支颐。","大牛道者禅山来，为我朗说禅山事。","禅山万市六衢通，珠林宝树如排丛。","毗耶阒寂无人到，今移此室在其中。","室中居士雪霜姿，大千搏取终无时。","金刚轮际香积土，六方震动如吹篪。","雪白摩尼生慧眼，春花天女执军持。","建安文气五綵笔，龙眠山庄尤描得。","脚底胸中无远迩，明霞举举秋空出。","昔年我走大关东，千山古佛凝双瞳。","金陵几度忆分手，挑灯坐念无如公。","思智妙密心境宽，金刀镌玉光玲珑。","今年五十又过一，大牛有口寿不得。","我作此篇当紫芝，千年之日如今日。"]},{"t":"寿王瑞图","f":"七言古诗","c":["辞却青门归白社，辋川春日悠悠者。","愚公谷内百念寒，漱泉枕石恣幽写。","作诗命绘鬼神惊，拱手长谢世间名。","立朝束带非吾愿，只使秋林满磬声。","此老芳踪久不歇，如今复见有云礽。","瑞图王子非凡质，玉山雪映高崚嶒。","从余学得太傅斋，一念清彻如潭澄。","譬如春树先着雨，自然秋实凌霜冰。","又如云气侵碧玉，陆离光怪照千乘。","长生自有无生曲，东风四座绕春灯。"]},{"t":"寿樊月藏","f":"七言古诗","c":["五綵能收战胜名，文坛今日见星精。","廿年之前河肯清，手摩帝座腾青冥。","廿年之前河便浊，徒令雪鬓甘雌伏。","万张玉弩射潮头，百里青山界寒瀑。","世波既下日星溷，多君一寸存幽独。","譬如大地发寒风，手持玉管吹深谷。","载酒不及王丹劳，读书每效阮生哭。","此念消归太傅斋，大千世界如牙排。","观河尚可探灵贶，镌石犹堪蹈月街。","今年六十从头起，一年一度春风美。","玉角麟行万点金，为君印向深云里。"]},{"t":"寿刘敬吾","f":"七言古诗","c":["五岳之峰嵩岳高，乔松千树奏云涛。","月明少室清光满，风吹浑陆翠华劳。","刘君钟此奇伟气，诞生其下何雄豪。","少年走马气喷薄，手弯硬弩侵星角。","材敏自能筹国计，谊高到处恣行乐。","神鲲之背恒负风，灵苗种自楚王宫。","去年访我海边寺，笑声万古破洪濛。","护持此地兼护我，思惟方寸凌神工。","琉璃灯下金刚眼，心开字字皆能通。","已见莲花堪比玉，谁言宝地复生蓬。","从前祝者皆可量，此回通透无遮障。","玉海千年与子游，龙华树看金轮上。"]},{"t":"寿汪子厚","f":"七言古诗","c":["汪君初度无可说，山僧两手掬明月。","赠君明月有光辉，吉祥如意皆欢悦。","我有福田君乐耕，一收再收积崚嶒。","玉钵自能酬石髓，金风偏解老霜筠。","交友每于穷处见，譬如岁底匀新春。","厌看云雨反覆手，喜见金兰意气人。","意气如君自激昂，古松大柏皆芬芳。","但愿慇勤保此心，岁月还看寿者长。"]},{"t":"欢喜歌","f":"楚辞体","c":["初秋日既望，度腊得欢喜。","年年此日欢喜同，今年欢喜那堪比。","喜事看来信逾奇，喜声直透昆崙嵋。","长虬啸海海水震，天吴失势冯夷痴。","君不见匡庐之巅金轮峰，万山玉绕紫芙蓉。","玻璃瓶耀金刚粒，五色烂绚光玲珑。","当年双树日轮入，四天飞铁狞龙泣。","宝山之赩有遗骸，遂令季叶声光及。","西竺异人敦遗化，抱瓶煮铁翔云立。","大宋咸平分者谁，一瓶移镇山之北。","石梁疑是鬼神琢，两山巀嵲如玉削。","礧岢之气看本雄，矫龙欲去还能约。","代深圮灭神物藏，百灵呵护何可当。","丰城之剑昔在地，牛斗之上冲精光。","何况至尊无喻比，黄河见底圣人起。","壮穆墙边昱昱光，南归百粤祥云紫。","报我欢声唐孝廉，凤笙龙笛那能似。","君不见武陵飘水桃叶流，挂瓢洗耳徒咿咻。","此辈安能有至乐，不达斯理真浮沤。","又不见人间万事自凋残，堪嗟勒石燕然山。","楼高偏可坠玉女，秦皇走杀无金丹。","邓通铸山倏忽耳，金张赫奕何等閒。","我欲人间效兴福，八宝庄严光夺目。","譬如冥晦烧绛灯，衣珠三薰又三沐。","献沙昔日金轮王，四天分塔黄金光。","隋文置掌不能数，三十六州皆播扬。","芳尘在眼声在耳，手沾圣泽心茫茫。","安得昆吾铜蓝田玉，八棱架空驱鬼斸。","檐楹星月绕还低，远近烟霞生亦俗。","十六周尺十尺围，盘狮走豸麒麟嘶。","中间至人如宝月，黄金炜炜流光辉。","十三层级表至德，四边力士相持维。","宝阶六道雪山来，镂冰镌月丝文开。","绣栌朱柱迎风铎，交罗宝网悬高台。","菰芦弟子有宿根，正当欢喜来相亲。","金针乍落水纹合，马牙未爇先氤氲。","点头微笑为办此，恰如食器出千群。","入怀之鸠化异宝，卜式输边计不早。","慧远莲台十八贤，旷达如君何处讨。","维摩手疾香饭煖，马驹脚硬神州软。","旋开慧剑割浮云，大地嶙峋成琰琬。","三禅之乐风可吹，苏门振响声悲悽，我所喜兮凌紫霓。"]},{"t":"瑞光歌为谷电非作","f":"古风","c":["君不见梧台燕石笑周人，黄金错买凤凰群。","世间局蹐那可道，悬黎绿结谁相亲。","太颠宝贝隋侯珠，十车鱼目混有馀。","六龙驭日日西入，海风吹沙天地黑。","湛卢出匣光不割，至今抱璞楚人泣。","却秦蹈海宁非痴，击晋守阍更谁识。","金谷可怜几斛珠，当时又错换颜色。","丈夫意气在四海，黑头不遂白头改。","手中有米难排山，云里无梯凤不还。","猛虎乍甘卑作鼠，鲋鱼意在升斗间。","抽来双铗老龙声，万里随风破渺溟。","楼船将军空重士，玉帐但闻啜紫琼。","龙蛇自古出大泽，一长不吐羞为客。","琅玕作饭不能餐，典却鹔鹴竟何益。","舳舻去岁浮鳄渚，星光耿耿长天碧。","南飞乌鹊飞栖时，星光却向长襟落。","抖之铿然在趾间，神姝缥缈竟难攀。","回头失手愕交甫，此珠光怪非等閒。","我闻神宝遍天地，当时刳腹开昭关。","又闻汲水饮异人，双璧竟产蓝田山。","为智为福各有时，飞鸠变铁终无移。","去年珠海十万灯，绣幡宝网拖长霓。","金钟喧彻寒潮白，阴幽似见鬼神驰。","河伯却衔此夜光，疾走韩江照君衣。","君今牢骚欲归去，黄金虽瘦功德肥。","我作此歌名瑞光，梵音轧轧动南箕。"]},{"t":"赠郑元白","f":"古风","c":["乾坤跳双九，倏忽二十载。","浮云蔽大陆，阴霾色全改。","鬓丝已如雪，暗泪滴成海。","廿年之前固已穷，阁窗还对孝陵松。","廿年之后今如此，胸中有翮无长风。","岭头三寄故人书，关山洪乔沈邮筒。","燕然阻乱复相见，周旋一载情尤丰。","丈夫不作女儿态，干戈满地犹飘蓬。","仳离抗手无多语，珍重此躯为云龙。","一声南雁当北回，荜门雀跃无如公。","我思骖鸾或驭鲤，譬如水上抽芙蓉。","袖里毛锥莫轻写，看君新铭景阳钟。"]},{"t":"寿陈照江篇","f":"古风","c":["我与二哥交，交臂二十年。","世间材气相抛掷，出世妙义相探研。","虹霓十丈吐燕然，雪空万里天山连。","指顾苍茫极虚烟，或吟或啸帝座边。","岂与世人漫周旋，今来白下成枯禅。","乞食不得悲林泉，二哥已作人中仙。","玉堂深闭道则全，舞鸡或向明月前。","骏骑未老枥中眠，云衢只在脚跟前。","三哥绿发亦自贤，通透敏慧双璧联。","昨饮寿酒开芳筵，知我却与酒无缘。","不使我知作寿篇，罚在人间住百年。","为我乞经走暑天，譬彼大陆抽金莲。","金函律论三藏全，汝收功德自绵绵。"]},{"t":"赠张羽皇","f":"古风","c":["君不见莫耶之气光瞩天，精光冲向斗牛躔。","究其本根在何处，位置何必台衡边。","非金非玉浑非宝，祇有铁骨相钩连。","狱底沉沉围黑土，偏生奇物恣翩跹。","丈夫自有英雄姿，若个英雄解合时。","卑能自高小能大，道得其要方能施。","譬如神龙知变化，忽在重霄忽在坭。","又不见天竺驭世金轮王，脱其珍服衣伽黎。","慈惠有心难自遏，流离无地不相依。","中州奇士数张君，慈惠为心众所知。","黄金挥手如黄土，激昂气节侵长霓。","推食解衣真小事，救苦寻声似导师。","为官却司广州狱，精神只是矜三木。","不谈王道却谈心，火里春芽皆抽育。","虚说大刑用甲兵，薄刑几个生鞭朴。","张君一来气便申，缘纯菲履皆生肉。","停箸谋生思饮食，典衣为死成棺椁。","蹠者之流原不逊，铁围虽密性难悛。","张君原情尽矜哀，革心无数轻泉台。","不耻身为烧剔变，却耻心难合死灰。","圜扉开处香烟簇，夜月明时磬韵来。","嗟哉德感有如此，未必人心皆尽死。","子产刑书尚有无，文王仪式何远迩。","张君张君有材能善用，却胜肘悬斗印空臃肿。","牛喘空知宰相贤，切肤谁问南冠痛。","珍重神螭护狱垣，莫向龙津学飞动。","救人功满过恒沙，与汝莲台看雪涌。"]},{"t":"禅山歌","f":"七言古诗","c":["珊瑚洲接沉香浦，乘潮直溯禅山坞。","禅山六市日繁华，户排文锦家玛瑙。","桑麻万井散鸡豚，竹苞箭茂相参伍。","文犀翡翠杂明珰，连衢列肆何辉煌。","击毂摩肩竞奔逐，憧憧杂沓尘纷芳。","回环曲水映清泚，朱楼对峙如翱翔。","西樵山抱芙蓉密，千红万绿争秋霜。","黄木湾头梅欲白，寒香迢递连阡陌。","夜市鲛人鬻绡归，朝烟估客乘槎泊。","鳀海岚波十万重，虞泉日月双环黑。","一从郊外事戎马，巢风穴雨愁家室。","坐数鹏溟百二乡，缘仆其人皆裙虱。","南海风光自太平，竹弦丝管争相鸣。","雄籓柱壮欃枪远，朝阙台高碧汉清。","今岁秋闱典特新，凤书馆阁来文臣。","远甸文风愈兴起，隽拔髦士皆麒麟。","太史春秋亦正富，翔龙威凤殊惊人。","当年陆贾亦说客，宣布帝德犹未真。","太史读书明国体，一觞一咏皆精神。","越王城下嗟陈迹，粤女花田坐锦茵。","手持金玉双笔管，随其道合能屈伸。","牙樯閒作禅山游，禅山观者如山丘。","未觉羽书生战垒，喜看天泽来龙洲。","务使闾阎生景色，能令海国见风流。","太史更能閒物外，禅机与我相唱詶。","一路梅花密相送，磬声敲彻海门秋。"]},{"t":"寿叶公旦","f":"七言古诗","c":["我从万里游玉京，无心兴发如浮萍。","忽然淹滞在山左，是梦非梦不能醒。","以此得交萧侍读，叶生座上尤聪明。","口头三昧殊滑稽，曼倩无乃成虚名。","艺苑旧坛标赤帜，绘家新意开青冥。","春气更浓冰欲坼，愁心万丈生南陌。","此意许我两人知，相看共作南中客。","心切倚门成孝友，我苦空瓢则固陋。","优劣虽然道不同，以此相知真可久。","为君起借主人杯，岂是区区斟寿酒。"]},{"t":"黎子以英州山见贻作供石歌","f":"古风","c":["峨嵋居士有逸想，声名如山，才华万丈。","星芒月角恣幽赏，到处卿云随迭宕。","观山画水悟流波，胜因惯用无生奖。","手撚玉麈探禅窟，金山老宿毫光密。","半偈难消玛瑙杯，一言易变琉璃质。","补天五色鍊之馀，女娲失手苍龙得。","珊瑚树底浸逾红，老蚌腹中光篆刻。","丝文腻理天孙织，波声消歇太湖黑。","五千年后出人间，光印森罗皆辟易。","居士得之献老禅，金盘擎出烛人天。","珠池玉岭工力拙，八珍安可笑金仙。","已矣哉，旧事风流祇自传，亲眼不见亦徒然。","丈夫志气超千古，华嵩岱霍如浮烟。","黄河水源跨万里，一笑直倒昆崙巅。","不欲干情岳，岂肯滞心田。","何况眇小如丘壑，厌立云头看星落。","襄阳伏地未必痴，放诞安知无所托。","但令此志慕山林，一寸轻埃足寥廓。","君不见当年金谷围虚空，千株玉树金芙蓉。","凤啼深碧梧桐老，莺啭初红二月中。","月色无光九华燄，冰喉翠管五云乱。","黄金有炭不铸人，东门无路遭轻贱。","黎子志趣自非常，卓识曾经几回鍊。","入怀雀见霜钩白，观空意笑夷门浅。","贻我云根溢一船，胸中洒落如飞箭。","洪濛自此夜钟深，又移往事到如今。"]},{"t":"李鍊师伏妖歌","f":"古风","c":["鍊师来自南岳山，秘携符术潜人间。","罗浮亦住冲虚观，腹饥分食葛洪丹。","妖狐白昼敢欺人，娥眉十八娇青春。","金线压成双凤袄，寸弓凌绝波心尘。","云鬟五六随侍奉，浓情皓腕芳魂动。","年少邀欢乐事饶，巨罗金错勤相送。","延得鍊师归宝阁，将到未到狐氛落。","狐愁漫倚天师符，欢情恍惚难如昨。","鍊师既到只寻常，无剑无印无旌幢。","井渫寒分一茗具，博山閒插半条香。","案头拾得包药纸，随拨尘埃随动指。","香烟爇纸吹巽风，须臾力士几惊死。","力士身长下九天，十分壮勇驱云烟。","手提玉女宫妆乱，摧抑掷向鍊师前。","翻身跃冶似无事，旁观十目皆洞然。","鍊师呼狐狐起立，漫言用慰如饮泣。","年少还贪旧日欢，横波送语声尤急。","又问云鬟已何之，答言动止皆相随。","来时不肯轻抛弃，腹中与处如囊锥。","鍊师摇手语皆止，狐向鍊师脱生死。","鍊师微笑垂衣袖，敏捷一入如苍鼠。","鍊师捉袖更书符，形声俱灭归虚无。","寒风四壁乍消落，光明依旧照屋庐。","复就宾阶恣语笑，主人欲谢防语粗。","嗟吁安得尽剪雷州葛，裁成衣袖遮天阔。","鍊师为我袖人妖，大地共睹升平乐。"]},{"t":"送西堂石鉴覞弟领众住栖贤","f":"七言古诗","c":["五叶天风吹欲落，银河之泻咽喷薄。","鲸鲵走陆化作鱼，江西驹儿产头角。","鞭风不踏紫陌尘，要使吼声喧五岳。","嗟吁大道时贤卑，至人不作使世疑。","浴雾已看文彩就，当头一喝成鹏飞。","如今分座龙象拥，高横玉麈深天机。","海波月起雁声来，坐念送君心迟迟。","栖贤我昔诛茅者，随师拾栗寒溪湄。","紫藤锦石不入眼，区区心迹今云疲。","吾师买马先买骨，秕糠如絮已粘泥。","衢头钟动市人丛，昙花岂得生其中。","不须呵我心先折，况复飘飘凌高风。","玉渊之水神龙藏，高崖灼烁骊珠光。","霞明雪净尘垢扫，追还九代轩琅琅。","入山却比谢安出，一丝九鼎悬穹苍。","吾生雅负素餐耻，譬如春梦不能起。","今日私心十倍欢，所能言者其粗耳。","寻常离别自有情，流光圣箭蜚英声。","悲欢在手不能用，眼看落叶堆高坪。","此山困厄数百载，杉松桧柏犹未改。","九曲澄渟天上来，五老芙蓉日飞盖。","石梁跨蹑断世心，幽人一入神踽踽。","所期万础绕千人，一丘一壑吾无取。","君但严持宝镜行，呶呶之物安足语。"]},{"t":"送石鉴覞弟领众住怡山","f":"古风","c":["猗欤博峤立纲宗，吁谟严密如游龙。","不特风雷藏舌底，还将剑戟插双瞳。","二叶绳绳开五岭，凤毛龙甲光玲珑。","水犀玑贝腾南海，髦士奋起夺其雄。","君不见蓬莱水浅天步窄，大道与之俱困穷。","四海惛怓日茅拔，荒唐猿鹤悲沙虫。","覞也吾家信迈种，金针暗与先民通。","激昂鹊起南海陲，弘肩斯道吹清风。","昔年分座庐岳北，万朵芙蓉遮座密。","颓风振起神自閒，火齐乍掷天回黑。","东奔众水无还期，遂使一壶成挽力。","繄吾师翁博宗子，宝镜横披标至德。","法澜博洽四百峰，赤幡更向七闽立。","怡山飞凤闽之冠，天龙精魄司轮奂。","宝所煌煌至道存，象径肯使鼪狐乱。","师翁贻厥事芟除，西奔金乌跳蟾蜍。","大匠袖手藏徽缠，成风小智乃其馀。","此座虚悬过一纪，师也命覞正其居。","至人荷道遑恤躬，天不令卷行则舒。","我闻曩哲有棱公，蒲团十丈成邻虚。","今日微尘翳天壤，洞山失却我与渠。","送君不作别离色，击案四顾空踌蹰。","法坛宿将建旄旟，寻常老去当何如。","监院纬公贤且耄，绸缪廿载诚拮据。","谦光蔼蔼为君佐，盥手行当接素书。"]},{"t":"寄澹和尚","f":"七言古诗","c":["五羊仲春廿有一，韶阳又隔十四日。","安危山上知若何，悲凉此处苦已极。","平生几度逢剧乱，烽火每每烧颜色。","传闻六县亦多盗，钩连蛮峒如豺虎。","宛同水寇恣劫杀，不抢仁化抢下富。","梦觉关前虽未来，海螺岩上当先怖。","雷峰殿外筑层城，吹竹鸣金昼夜惊。","高挂蒲团无祖意，空令胸次有刀兵。","四郊城内人民失，月中盘米收不得。","半生精血已消磨，一掌祇园难建立。","我欲还披百结衣，近来公瘦或稍肥。","人行须便寄一纸，不久应同话翠微。"]},{"t":"解虎以洗蜡石失脚几绝作此嘲之","f":"七言古诗","c":["城中苦雨坭活活，花栏苦雨青苔滑。","老僧双展抱石行，蜡色未净先遭跶。","跶时顾石不顾头，天仓地角血并流。","魋鼻倏如龙隼公，方寸可使高岑楼。","夏云入面奇峰起，红紫相间如清秋。","又肖丹青图未成，烘染还藉顾虎头。","行者急行杀猛熊，取胆调酒斟金瓯。","痂除扶杖须郑重，尽将蜡石沉清流。"]},{"t":"寿瑞生禅者","f":"七言古诗","c":["苾刍托钵愁臂酸，重毡褥覆恣昼眠。","古人叹惜至今日，功德林枯上虚烟。","手软不摇普化铎，舌结谁开大沩田。","我作驱乌见一人，月门畚笨能苦辛。","拗折硬弓追石巩，锄开春草类玄真。","峰前两眼看云水，清溪一喝扬沙尘。","绿竹参天摇凤尾，新松遍岭长龙鳞。","一肩两手汗如雨，金牛有饭应斋汝。","又能步步拜街尘，狮吼象踏无违拒。","遂令丈六金色身，螺丝宝髻神踽踽。","自从震旦降旃檀，此相真堪福寰宇。","相成易汝为瑞生，一言道合宾中主。","风高月白六七年，栽花礼佛藕池边。","篆烟夜照琉璃直，閒梦朝看木枕圆。","前年我分海幢席，一椽老汝诸狂息。","不去庐山不北归，芳兰万本当门植。","此地方标吉祥草，朱甍碧瓦凭愿力。","香珠十串绕长廊，声声微令乾心识。","五十以前一瞬间，五十以后亦等閒。","频伽瓶纳太虚空，了无出入与往还。","莲华十劫不肯开，清香扑鼻隐金台。","还将阎浮五十载，销尽习气无尘埃。","此后谁能为汝寿，白毫悦体光如梅。"]},{"t":"寿实行上人","f":"七言古诗","c":["鹫岭峰头悬智镜，金仙宝觉群仪净。","大机显晦一乘归，空有齐彰相掩映。","四谛先从五圣传，一花会见万人盛。","索诃瑞气本来多，银牛金象流双河。","神驹四脚出远谶，一口能吸西江波。","西江法窟古来许，匡庐屼嵲悬云萝。","智士手持匡岳云，南走百粤吹氤氲。","镇海明珠探手得，建立之门著茂勋。","千层佛塔黄金色，万本旃檀皆手植。","烽烟堆里洒杨枝，紫陌衢头布慈力。","又持百福结君王，琉璃殿上皆相识。","长眉两道寿者相，宝掌千岁神州直。","破裙愧我住荒村，一条楖栗冷寒原。","廿年空自知名姓，一日欣君古道存。","法庭既晚俗浇漓，狮虫独肯食狮儿。","如君但具莲花舌，护法深心人岂知。","关西将军有神力，中州长者已无疑。","我作此偈为君寿，却胜罗浮紫玉芝。"]},{"t":"浮沙","f":"七言古诗","c":["余生堪笑笑复嗟，穷谷不走走天涯。","天涯道路阻且赊，巨鲸吸风涌浪花。","寄身一叶不乘槎，琼城作客复闻笳。","万里愁心不可遮，西南有土名浮沙。","好友招游烟景奢，秋力薄不变蒹葭。","朝暮红生上海霞，但宿鸥鹭死桑麻。","万丈之水不可加，不然顽土何足誇。","地脚既短如岩谺，蓬岛鳌擎终倾斜。","渺小难以蟠龙蛇，四水环回深且洼。","十年之前有僧家，缚茆架屋弹琵琶。","嗟吁岂不愧袈裟，我欲乘之作归艖。"]},{"t":"上河采莲行","f":"古风","c":["长干六月莲花开，九衢烁石飞尘埃。","清凉自可消热恼，至今奇异抽莲台。","上河种莲莲千顷，独有一池最清冷。","五花一蒂间红黄，或三或九相牵引。","更有垂头照水莲，花头在水蒂在天。","瓣剪轻罗千叠细，香留湿露半铢妍。","世间物理须平常，一花一蒂自相当。","譬如百工各一艺，流行王泽称安康。","即使一蒂悬二花，并头已足使人誇。","三五钩连至九瓣，真疑玉阙开天葩。","周公多才复多技，若无其德才则累。","对花不觉惜花奇，以理求之或相似。","柳子上河访友归，说花真使心魂飞。","兼言一士能扛鼎，直气不剉与身肥。","青原瀑布开生面，曾驱五虎出山嵋。","鸡鸣半叶即淩风，一见未语知猿公。","相携池畔寻菡萏，四枝照水新芙蓉。","池上主人叉腰立，对花与之施长揖。","最嫌礼数缚人情，怒气横生手以戟。","转盻之间池水沸，莲花出水香流地。","力士早曾脱巾舄，水中那得藏蛟兕。","今春碣石归金陵，风尘困折意难清。","忽闻奇事探奇赏，烦襟荡涤归清溟。","嗟吁中和祥瑞被草木，何不直与万姓消刀兵。"]},{"t":"雨雪","f":"七言古诗","c":["北风吹水水不结，只为寒雨不为雪。","雪上衣裳尚可拂，雨湿衣裳寒切骨。","一驴昨夜复钉蹄，夜行只好打前失。","两膝夹骡痛难忍，一身负水坐难稳。","鞭缰在驭骡则驯，随鞍落镫骡则奋。","死生离地只尺馀，死生在眼心尤紧。","予生多役信未安，利名于我竟何干。","与人共作风尘客，却把风尘别眼看。"]},{"t":"戊申冬舟过英州阻风追忆行役之难因赋北风篇","f":"古风","c":["一年辛苦事，欲暂息舟中。","买船上水撑逆浪，不吹南风吹北风。","北风怒号船头裂，北风怒号牵枝折。","出门便得羁旅愁，人生那可轻离别。","我闻滟滪堆难平，巴字猿声不可听。","少年未肯寻常老，山川虽险心犹横。","又忆当时瀚海归，寒沙万里无征衣。","黑海海水与天阔，心知入水终难活。","不道悲凉雪窖来，却含郁抑无人说。","即使鞭驴走幽蓟，易水流澌风透袂。","冷人莫过五更霜，悬鹑已见三年敝。","北风北风于我亲，八岁流离已苦辛。","至今所历三十载，日夜徬徨驱心神。","人生学道存安逸，吾道萧萧悲白日。","君不见德宗懒瓒呼不起，纵有北风吹何益。"]},{"t":"登通天塔","f":"古风","c":["撑拄通天塔，翱翔砥柱堂。","舣舟一上裂天荒，韶石下关回澜狂。","双丸终古走寒光，此地乃尔高昂昂。","不独河低天亦低，九成台上风琅琅。","带得秋心过晚峡，还将逸眼傲朝霜。","因忆去年登海鳌，扶胥脚底起洪涛。","短鬓萧萧难掩雪，力弱心长首重搔。"]},{"t":"黄犬行","f":"古风","c":["舟中一黄犬，短小身躯皮骨软。","心魂在眼不住转，疑云吠浪声尤远。","掌船老妪抚摩久，朝昏饮食同无有。","船头吹风妪意怒，黄犬低头愁日暮。","船尾吹风妪意喜，黄犬船头跃船尾。","将军独马大塞行，未必可以同生死。","依沙泊船上牵枝，黄犬亦上打狐狸。","岸曲潆洄水间之，黄犬独立心迟迟。","不唯黄犬独立心迟迟，妪手捉舵心亦驰。","挥手令之上高坡，黄犬翻身无一时。","水深苔滑复急流，黄犬横截如轻鸥。","振身洒雨立船头，妪也微笑心悠悠。","当时李斯错牵犬，犬亦错与李斯游。","东门路惯死公侯，狡兽铁爪复何仇，愿与老妪长相守。"]},{"t":"飓风歌","f":"楚辞体","c":["天定喜兮天或怒，蚩蚩那得识其故。","珠江千顷软琉璃，招招利涉人争渡。","阴霾倏忽收日月，天地惨澹失云路。","风师河伯皆颠狂，各驱部类恣奋强。","雨龙带海朝玉皇，汇撮天河添霔霶。","风轮旋转更飙猛，拉折地轴破天纲。","六鳌缩项项肤裂，三山箕碎沉岌嶪。","邓林一夜尽飞空，狖号猿啼声间切。","可怜数里散穷檐，大块噫气一时咽。","兵来贼去多苦辛，亦喜踪迹顿磨灭。","海幢寺向珠水湄，香灯寥落草离离。","贼过仲春如水洗，愁来九夏复风吹。","飓风吹兮捲水入，珠玑百斛侵人湿。","轰雷不救屋宇倾，空园只抱瓜芋泣。","行僧粗莽难守饥，持钵不得心魂疲。","食指三千徒落落，冷黔数座苦漓漓。","豆苗枯瘦禾苗死，欲走咫尺阻乱离。","分同黎庶遭劫运，事事不敢怨疮痍。","更愿还吹十日风，白骨撑拄偿天公。"]},{"t":"登九江锁江楼","f":"五言律诗","c":["客行当绝域，楼望倍伤秋。","地坼三吴势，江分九派流。","故山浮自远，近泪落难收。","惭愧蒹葭色，閒閒映白鸥。"]},{"t":"泊山东界口","f":"五言律诗","c":["多少平生志，天涯一梦穷。","雁声悲处起，鹤影望来空。","樯挂淮阳月，波生海岱风。","忽听乡语转，始忆泊山东。"]},{"t":"中秋泊济宁","f":"五言律诗","c":["世上中秋节，征人万里情。","可怜一夜月，尽向客途明。","樯入山东影，江流辽海声。","篷头深默坐，细碎问平生。"]},{"t":"晓发杨村","f":"五言律诗","c":["晓月到垂地，残星入半江。","涧云当路白，柳叶向人黄。","豫水三千远，关门十日长。","到时鸿过尽，沙气拥斜阳。"]},{"t":"同寓诸夜入蓝田","f":"五言律诗","c":["人当蓝水去，月向蓟门明。","寂寞应吾道，艰难见尔情。","云深茅店路，霜落板桥声。","犹幸临岐夜，山夫伴此行。"]},{"t":"过丰润县","f":"五言律诗","c":["未出卢龙塞，先过丰润城。","日沉千堞黑，月出四山明。","觅寺愁无路，闻砧泪有声。","明朝一百里，晨起又兼程。"]},{"t":"过山海关 其一","f":"五言律诗","c":["及关犹曙色，十日乱边声。","无计轻然诺，临危任死生。","旅魂先马倦，落月与山平。","到此方惆怅，悲笳处处鸣。"]},{"t":"过山海关 其二","f":"五言律诗","c":["汉地今朝尽，高天去日长。","山川送形影，冰雪到膏肓。","败垒封狐窟，平沙古战场。","予生甘灭裂，心迹此时伤。"]},{"t":"过山海关 其三","f":"五言律诗","c":["百簇旌旗出，惊看令尹才。","烟尘空自绕，锁钥几曾开。","鬼箓宣名姓，刀边问去来。","更怜图貌后，尤似暴鱼腮。"]},{"t":"过山海关 其四","f":"五言律诗","c":["重门扼断石，峻壁插寒空。","额是前朝字，城犹秦代功。","吹笳喧杀气，侧目见长虹。","飞将孤坟在，凄凉白露中。"]},{"t":"过山海关 其五","f":"五言律诗","c":["鼓炮三声毕，弓刀十队齐。","黑云驱雁入，骏马杂人嘶。","气到惊心短，头因下泪低。","亦知前更甚，无奈自凄迷。"]},{"t":"本师诞日","f":"五言律诗","c":["师定念游子，遥知父母心。","望云天际远，曝日石门深。","香影浮阶砌，猿声彻野林。","无穷长跪祝，惟有此微忱。"]},{"t":"宿沙岭遣寓诸先入牛庄","f":"五言律诗","c":["五夜余当至，朝霜尔且行。","欲向好师友，先依难弟兄。","去时生是重，归日死为轻。","河上冰还薄，随人切老成。"]},{"t":"宿三岔河","f":"五言律诗","c":["何处堪投宿，连衣枕白沙。","中宵霜似箭，一夜泪如麻。","掷石投山鬼，穿林起乱鸦。","髑髅常伴饮，谁畏盏中蛇。"]},{"t":"到辽阳呈剩师叔","f":"五言律诗","c":["深雪夜行尽，严风昼复吹。","尺书欣已达，稽首竟无辞。","欲话匡山苦，徒令老大悲。","未堪供棒喝，不是汾州儿。"]},{"t":"辽阳怀顿修 其一","f":"五言律诗","c":["忆别姑苏寺，分吟尚暮秋。","所经无限雪，频起故山愁。","白草随人短，寒砧带月流。","西南回首处，疑是武昌楼。"]},{"t":"辽阳怀顿修 其二","f":"五言律诗","c":["我到辽阳日，初参佛眼时。","亦怜穷子意，谈笑共忘机。","问旧挑灯暗，论诗补字奇。","夜寒高兴发，不见浙江儿。"]},{"t":"辽阳怀顿修 其三","f":"五言律诗","c":["连年频苦别，总对朔风寒。","尔多师友性，余少水云欢。","挥泪檐霜白，行吟木叶乾。","人生不可料，况复此时难。"]},{"t":"辽阳怀顿修 其四","f":"五言律诗","c":["万重烟水外，书音未易通。","不堪金井北，话到玉门东。","月照黄榆老，山明寒瀑空。","传余多进益，莫损老人容。"]},{"t":"辽阳怀顿修 其五","f":"五言律诗","c":["愁月偏高照，不与众山齐。","仰面云侵帽，低头泪及泥。","鸟声虚旷野，虎迹印前溪。","细想金山寺，寒钟为尔凄。"]},{"t":"辽阳怀顿修 其六","f":"五言律诗","c":["尔有孤閒句，余时天外吟。","生皆天地意，死亦友朋心。","日入寒松苦，云凝独壑阴。","逢人多强笑，恐忽泪沾襟。"]},{"t":"辽阳怀顿修 其七","f":"五言律诗","c":["八载依师友，犹然儿女情。","一从乍漂泊，不敢任天真。","客久易得罪，余常厌此身。","每看勾漏令，愧作岭南人。"]},{"t":"岁晏","f":"五言律诗","c":["岁去无新绪，寻常只旧愁。","泪堪流塞下，老莫到江州。","梦绕深更后，泉探第六幽。","天山前日雪，犹在树枝头。"]},{"t":"雪 其一","f":"五言律诗","c":["质变三山雨，寒添五岭风。","自怜沟壑白，犹喜树枝空。","乌鹊亦无意，冰霜竟不同。","夜炉柮榾火，留兴与山翁。"]},{"t":"雪 其二","f":"五言律诗","c":["人皆怜洁白，岂敢信严威。","不使惊鸿翼，偏令近马蹄。","石光深处透，草色静中迷。","夜夜山钟起，随风度隔溪。"]},{"t":"雪 其三","f":"五言律诗","c":["与世能无热，持身一味寒。","笑随风入谷，閒对月凭栏。","骏马一鞭过，高僧两眼看。","到春啼杜宇，不觉泪漫漫。"]},{"t":"雪 其四","f":"五言律诗","c":["寒光垂大漠，亦可代秦台。","心胆尔能照，肝肠我自灰。","飘零华表鹤，寂寞岭头梅。","且尽一杯茗，随他草木催。"]},{"t":"雪 其五","f":"古风","c":["高人閒磊落，野衲静?毵。","山浅云千叠，寒深月一庵。","只应同日化，难与玉俱函。","几多天外意，谁为寄江南。"]},{"t":"雪 其六","f":"五言律诗","c":["寂寞掩山斋，萧条见素怀。","入城愁马踏，傍涧爱云霾。","晕出淮南管，寒添懒瓒柴。","年年对搔鬓，吟咏一无涯。"]},{"t":"雪 其七","f":"五言律诗","c":["畏热难伦水，虚明只共天。","自知摇落后，不受一人怜。","白足眠云老，庞眉坐石穿。","未能供寂寞，肠断为残年。"]},{"t":"雪 其八","f":"五言律诗","c":["我行泉壑下，如在梦魂中。","何曾一点白，得傍夜炉红。","故柳衰欲死，溪云澹复空。","平生萧索意，不解逐春风。"]},{"t":"雪 其九","f":"五言律诗","c":["长边不厌厚，千叠马蹄痕。","客路多愁晚，疏林殊未昏。","鸟寒深啄月，猿寂暗啼魂。","何处寻高士，随云过隔村。"]},{"t":"雪 其十","f":"五言律诗","c":["万里乾坤眼，一山住去情。","松枝千点重，月色半帘轻。","内热怜予瘦，高寒念客惊。","何人欹枕卧，遥见暮云平。"]},{"t":"且过庵","f":"五言律诗","c":["多病无閒兴，虽閒不杖藜。","虎过窗外见，鸟宿枕边啼。","道以支离减，心因曲折迷。","平生多意气，徒自笑醯鸡。"]},{"t":"小除 其一","f":"五言律诗","c":["一年馀五日，万虑到三更。","道力消难尽，诗情感又生。","风当窗破入，灯向语残明。","多少天涯客，那堪共此情。"]},{"t":"小除 其二","f":"五言律诗","c":["总是心有事，非关岁序频。","持身方欲死，何处复怀人。","往念骈残腊，新愁属蚤春。","但知吾道在，不必问高旻。"]},{"t":"宿南塔","f":"五言律诗","c":["南城宿野寺，北极望云林。","星月还清夜，风尘奈客心。","春光依树浅，沙气绕门深。","多病穷愁集，萧然无好吟。"]},{"t":"灯下读梁同庵上剩师叔书因伤白庵石师","f":"五言律诗","c":["旧札看残烛，遗文惨晚烟。","能将师友泪，洒向弟兄前。","未遂临关志，空为隔世怜。","同人多殒落，吟罢自潸然。"]},{"t":"赠郝侍御雪海","f":"五言律诗","c":["世事难容直，知君不可任。","好将华岳诀，自慰柏台心。","边月寒偏白，春云静独深。","相逢话肝膈，余亦恋知音。"]},{"t":"塞下逢江东陈十一柱江","f":"五言律诗","c":["士有不可识，因人一见君。","马驱边地月，剑拂蓟门云。","市饮终何事，燕歌已蚤闻。","苍茫逢日暮，握手暂云云。"]},{"t":"丁酉生日宿沈阳南塔寺 其一","f":"五言律诗","c":["傍寺逢生日，趋庭忆往年。","既无酬下地，犹自戴皇天。","断戍荒烟合，孤城乡月悬。","此时珠海上，清切乱啼鹃。"]},{"t":"丁酉生日宿沈阳南塔寺 其二","f":"五言律诗","c":["几日为儿女，十年独苦辛。","春云枯冢树，流水石梁人。","侍烛遥归夜，悲天厌有身。","幸还依塞下，犹自问迷津。"]},{"t":"送陈柱江还长安","f":"五言律诗","c":["一旬谈笑里，万里别离中。","策马春山响，孤城旭日红。","离杯归思满，分手客心同。","珍重千金铗，长歌使我逢。"]},{"t":"宿千山龙泉寺","f":"五言律诗","c":["五更风雨密，孤枕暗钟频。","白日愁为客，青山不定身。","涧响虫声杂，窗虚花气新。","何当一夜梦，两渡白门津。"]},{"t":"夜","f":"五言律诗","c":["主人城郭去，柴门高更閒。","雨过滴未启，月影到方关。","虫小常邻屋，云多夜过山。","经行情脉脉，何处觅跻攀。"]},{"t":"初秋夜怀山中诸兄弟","f":"五言律诗","c":["黑水沙边路，终宵对月明。","我无青嶂梦，谁有向秋情。","塞草不成绿，孤松亦作声。","几多旧朋好，何处话平生。"]},{"t":"无题","f":"五言律诗","c":["每到无言处，频行望九霄。","中郎不可见，残爨自应烧。","短褐欲成癖，萤光似见招。","秋风一夕乱，寒气满山腰。"]},{"t":"丁酉九日南还别剩师叔","f":"五言律诗","c":["雁碛寒沙白，云峰野烧红。","风声皆向北，人意未离东。","锡振边尘落，书缄血泪空。","依依看寸晷，愁听暮天钟。"]},{"t":"将渡辽海先题牛庄寺 其一","f":"五言律诗","c":["平生无可信，辽海任飘蓬。","学少诗情短，愁多客路穷。","星随千里照，岸到九霄空。","亦是酬恩事，毋令泪独浓。"]},{"t":"将渡辽海先题牛庄寺 其二","f":"五言律诗","c":["钟声犹傍寺，海气已惊心。","地是人间尽，云从此路深。","风波供旅思，岛屿忆秋林。","回首天山雪，何由寄一音。"]},{"t":"将渡辽海先题牛庄寺 其三","f":"五言律诗","c":["晨起听鸡声，关心事事生。","独怜浮海意，仍是感恩行。","怒浪迎风白，朝暾半夜明。","一帆天地外，谁念此时情。"]},{"t":"宿海州城闻砧","f":"五言律诗","c":["独立复长吟，孤城急夜砧。","不知闺里意，只讶客途心。","萧瑟江关远，洪濛天地深。","愁来频不已，辜负启期琴。"]},{"t":"晓发牛庄","f":"五言律诗","c":["发棹辞寒碛，扬舲起楫师。","不关行处苦，仍是别时悲。","落月孤星伴，浮生万事危。","明朝出海望，应见黑云低。"]},{"t":"辽海舟中 其一","f":"五言律诗","c":["黑水行无地，黄沙已近天。","一帆风夜正，四望月空悬。","宿雾不归岛，危樯半入烟。","飘飘悽梗泛，木偶倩谁怜。"]},{"t":"辽海舟中 其二","f":"五言律诗","c":["落日孤舟晚，临风四望穷。","鹤飞低近浪，云起远浮空。","水怒人心善，霞明世界红。","去年行碛雪，不与此情同。"]},{"t":"辽海舟中 其三","f":"五言律诗","c":["鹢首喧难定，牙旗涷不飞。","吟残深夜烛，着尽耐寒衣。","浪飐惊风密，星随晓月稀。","辽阳不可望，但逐塞鸿归。"]},{"t":"辽海舟中 其四","f":"五言律诗","c":["不识伤心处，征蓬旅泊时。","一宵频雨雪，千里尽流澌。","石色看天近，云根出海迟。","余生多所慨，自觉愧冯夷。"]},{"t":"辽海舟中 其五","f":"五言律诗","c":["沧溟十万里，日日石尤风。","归梦寒难达，悲心久易穷。","星飞人面白，蜃出海灯红。","惟有无生理，安危自可通。"]},{"t":"辽海舟中 其六","f":"五言律诗","c":["中宵风逾恶，千丈浪难平。","有泪还肝胆，无亲任死生。","星光迷去路，寒气咽金声。","纵有维舟日，何堪此夜情。"]},{"t":"时十月十四日作本师诞日也 其一","f":"五言律诗","c":["石梁不可见，夜梦独迢迢。","山好连三楚，云寒尚六朝。","师年愁里过，客泪海中摇。","浅薄供驰逐，那堪慰寂寥。"]},{"t":"时十月十四日作本师诞日也 其二","f":"五言律诗","c":["旸谷一帆去，天波万里迷。","生如投马颊，死亦忆鸾溪。","气逼星辰大，寒令日月低。","行吟俱惨澹，无事不悽悽。"]},{"t":"时十月十四日作本师诞日也 其三","f":"五言律诗","c":["已见浮沉易，谁怜顾复难。","龙鳞风自急，精卫血无乾。","斜日含云暗，残霞染浪丹。","莫惊蛟兕起，天地不禁寒。"]},{"t":"过菊花岛 其一","f":"五言律诗","c":["绝岛浮前浪，重岩出海滨。","望之深汉月，疑尚有秦人。","石白千层雪，松青万树春。","扶筇欲一问，柔橹去何频。"]},{"t":"过菊花岛 其二","f":"五言律诗","c":["满山飞白鹤，几处傍青霄。","蜃气深盘寺，钟声落应潮。","荒台秦砌古，卧石汉功标。","心恋身难住，临风一望遥。"]},{"t":"达淮上","f":"五言律诗","c":["千翼乱鸣湍，归心睇望欢。","涷轻曲岸涩，云密大波寒。","北极堪回首，南图愧素餐。","三年橘已化，非止学邯郸。"]},{"t":"无终山下作","f":"五言律诗","c":["种玉先贤地，驱云过客情。","霞光隐高木，碛路射寒星。","马出高天阔，鸿归汉塞冥。","何由投绝壑，回望见龙庭。"]},{"t":"晓发露台","f":"五言律诗","c":["星没晓鸡号，夙驾上蓬蒿。","岁月关河晚，风尘形影高。","戍荒迷苦雾，魂冷想绨袍。","人世须行乐，予生自可劳。"]},{"t":"过压凤桥","f":"五言律诗","c":["昨宿盘龙渚，今过压凤桥。","山形随地转，雪色隔江遥。","草死文犹锦，烟空气未消。","当年刁斗夜，曾驻霍嫖姚。"]},{"t":"游盘山","f":"五言律诗","c":["正厌风尘苦，投山一望欢。","才经当路石，已爱古嶒峦。","风度松声阔，霜明晓道乾。","匡庐曾隐处，飞瀑为谁寒。"]},{"t":"游盘山中盘寺寻普化禅师塔","f":"五言律诗","c":["未到中盘寺，钟声先已闻。","松低青覆雪，山阔午凝云。","塔影双峰合，寒流几处分。","驴鸣犹彷佛，垒垒见高坟。"]},{"t":"凿龙池","f":"五言律诗","c":["龙德宜趋下，寒潭万丈深。","莫言云易老，须信石难沉。","势转长空静，光回乱壑阴。","何人观气宇，世外许相寻。"]},{"t":"净业庵","f":"五言律诗","c":["五峰皆暮雪，八石尽朝烟。","路转无人迹，溪寻见鸟眠。","楸梧犹往日，钟磬是何年。","一饭从僧乞，扶筇又渺然。"]},{"t":"宿上方寺","f":"五言律诗","c":["心閒宜落日，雪路认苔痕。","云起鹿鸣树，帘垂僧到门。","人间深壑见，石壁此峰尊。","一夜寒空月，凄清急暮猿。"]},{"t":"云罩寺","f":"五言律诗","c":["渐到中峰顶，斜看众壑低。","乱云攀不住，深雪忽然迷。","涧涷千条合，松青万树齐。","何当极高旷，独占蓟城西。"]},{"t":"戊戌长安元日同陈中翰忝生诸公作","f":"五言律诗","c":["未忘玄徼梦，又度玉京春。","曙色千门动，乡愁万里新。","金钟开紫阙，玉佩点朝臣。","借问桃源里，黄冠几隐沦。"]},{"t":"人日与诸子登观星台 其一","f":"五言律诗","c":["百尺悬梯上，千门映日开。","山标天寿翠，江涌月明来。","古戍流残雾，寒笳落早梅。","璇玑看秘密，因忆古人才。"]},{"t":"人日与诸子登观星台 其二","f":"五言律诗","c":["新岁登临望，亭亭欲近天。","帝城金凤阙，春气碧山烟。","旷野连三晋，黄云出九边。","客心消未得，怀抱只凄然。"]},{"t":"初春送姚巨六邓立人归循州","f":"五言律诗","c":["上国新杨柳，攀来带惠风。","赠君从此去，春色正无穷。","月过邮亭白，花经郡县红。","甘泉知可献，那解叹飘蓬。"]},{"t":"再游燕山","f":"五言律诗","c":["又到佳山水，难为旧隐心。","寻芳投北涧，选石得东林。","地敞中原秀，峰环紫禁深。","欲行情已怯，归路绕飞灊。"]},{"t":"登秘魔崖","f":"五言律诗","c":["秘魔高不极，正接太行踪。","白日寒千树，阴崖护二龙。","水帘风雨聚，云窦鬼神封。","一望知何世，秦关见几重。"]},{"t":"长安逢韩掌邦时韩子拟出辽阳访剩师叔","f":"五言律诗","c":["一从彭蠡别，几岁广陵居。","已得谋身策，毋膏出塞车。","路寒云气黑，霜苦月轮虚。","不重空相见，知君愿有馀。"]},{"t":"燕台秋日 其一","f":"五言律诗","c":["律管笳灰散，檀林夏火移。","气从今日变，人是此时悲。","朝雾涵空迥，斜阳入户迟。","望云情事切，何忍逗归期。"]},{"t":"燕台秋日 其二","f":"五言律诗","c":["时陟层楼望，萧条客思多。","傃风吹大陆，秋色耿长河。","剑气连天远，笳声送雁过。","他乡愁日暮，谁为一扬戈。"]},{"t":"时得本师和尚归粤信 其一","f":"五言律诗","c":["忽闻匡岳信，并起玉关愁。","华表方迷鹤，鄱阳已泛舟。","关山无近梦，江汉有新秋。","一望西山色，萧条映御沟。"]},{"t":"时得本师和尚归粤信 其二","f":"五言律诗","c":["几遇终南客，期餐地胏云。","薜萝心自苦，湖海恨难云。","枯冢别已久，维桑信不闻。","一归乾泪血，即与世相分。"]},{"t":"送韩子入秦","f":"五言律诗","c":["之子当行役，秦关万里秋。","驿云寒古戍，山月照吴钩。","客久心还壮，年深志未酬。","莫将凄别泪，时对汉宫流。"]},{"t":"哭秋山 其一","f":"五言律诗","c":["赭山深友谊，渔海长离忧。","别日悲新客，还家失旧游。","松风开绝巘，塔影暝寒流。","化鹤精灵在，犹应到十洲。"]},{"t":"哭秋山 其二","f":"五言律诗","c":["堪怜披薜客，十载茹芝苓。","未遂洪厓志，先登郭璞经。","山风吹泪断，石色上苔青。","一悟藏舟理，何心鍊鹤形。"]},{"t":"哭台设阇黎","f":"五言律诗","c":["几年歌薤露，一旦掩泉台。","既切芝焚苦，空馀蕙叹哀。","秋阴松路暝，风急石云开。","幽魄原无滞，他生愿不才。"]},{"t":"九日留别吴太仆春坪 其一","f":"五言律诗","c":["自怜重九日，握别素心人。","未饮茱萸露，先聆白雪音。","潘花飞远瀑，卫玉映长林。","自此起相忆，寒云万里深。"]},{"t":"九日留别吴太仆春坪 其二","f":"五言律诗","c":["少小事空寂，难为人世间。","三年携策出，万里逐鸿还。","白雪关门树，黄云塞上山。","征途多感叹，幸一识韩颜。"]},{"t":"留别陈路若","f":"五言律诗","c":["六十诗名旧，天涯始见君。","望残乡井月，卧老帝城云。","草色当轩静，嚣声入夜闻。","市廛犹有此，握别惜相分。"]},{"t":"将出长安作","f":"五言律诗","c":["湖海气苍苍，并州拥大荒。","断云归弱水，乡思望扶桑。","月影官桥白，钟声禁树黄。","年年理征铎，辛苦向羊肠。"]},{"t":"邯郸道中","f":"五言律诗","c":["驱云投日观，带雾揽星光。","槲叶飞无已，寒郊望自长。","风霜燕草木，城郭赵封疆。","敢动兴亡思，笳声起驿墙。"]},{"t":"泊挂剑坟","f":"五言律诗","c":["今夜维舟处，前贤挂剑坟。","树声流暝色，庙貌老徐君。","生死情何洽，豪雄世所闻。","至今村父老，伏腊荐溪芹。"]},{"t":"分水龙王庙","f":"五言律诗","c":["水势盘涡转，河流至此分。","北归趋碣石，南绕逗淮云。","月落无全影，风生有乱文。","辉煌临庙貌，千古镇波臣。"]},{"t":"临峄山湖","f":"五言律诗","c":["大湖千里驻，一气上洪濛。","色变翔麟野，波连辨马峰。","天寒乾草木，云暗蛰蛟龙。","吾道风尘在，仙槎不可从。"]},{"t":"哭无方阇黎","f":"五言律诗","c":["细想总茫然，哭君倍自怜。","佳城迷白日，世上岂青天。","道丧悲龙象，山春恨杜鹃。","年年持鹤梦，无计到花田。"]},{"t":"漂母祠","f":"五言律诗","c":["行人瞻漂母，尽解忆王孙。","昔日不图报，今朝始是恩。","鸟归庭柏动，垣败旧碑存。","读罢英雄事，升沈安可言。"]},{"t":"宿郑元白楼却赠 其一","f":"五言律诗","c":["不是轻相见，知君自玉关。","风尘为道苦，肝胆向人难。","雪到穷檐厚，风摇夜烛寒。","天涯存我辈，犹得共团栾。"]},{"t":"宿郑元白楼却赠 其二","f":"五言律诗","c":["闭门谁可到，风雪满层楼。","知有伤心泪，长为江水流。","高名羞阚月，愿尔掷吴钩。","去去罗浮路，相期在十洲。"]},{"t":"雨花台逢冯大 其一","f":"五言律诗","c":["世有奇男子，飘零可奈何。","风尘一剑苦，涕泪十年多。","榆塞留馀策，梅关发浩歌。","相逢一相揖，忆别自蓬婆。"]},{"t":"雨花台逢冯大 其二","f":"五言律诗","c":["茫茫湖海气，此别又何之。","天道多艰日，英雄失路时。","寒深辽左梦，愁到鬓边丝。","直待封侯罢，云山与子期。"]},{"t":"雨花台逢冯大 其三","f":"五言律诗","c":["家国两难归，天涯一布衣。","空怀名世业，难采越山薇。","掌握分星斗，悲歌动翠微。","当年垂钓叟，八十尚牛矶。"]},{"t":"雨花台逢冯大 其四","f":"五言律诗","c":["归思方寥寂，忽闻乡国音。","君来征战里，我去草莱深。","云水孤僧意，河山国士心。","楼头笳吹动，又在石城阴。"]},{"t":"望五老峰残雪","f":"五言律诗","c":["竟无看雪意，不奈倚楼心。","草木于人贱，烟霞入眼深。","到天寒愈阔，出谷势将沉。","更爱消融尽，苍苍露几岑。"]},{"t":"井陉道中","f":"五言律诗","c":["边风扫北平，行人出井陉。","斜阳悬马首，寒色拥邮亭。","道拙心如水，愁多发欲星。","从今归旧隐，麋鹿与松扃。"]},{"t":"偕露庭松山诸子寻西山精舍","f":"五言律诗","c":["卜室非求隐，扪心事正长。","世人甘扰扰，吾道亦皇皇。","草色连关塞，风声聚太行。","行藏多悔吝，翻对汝曹伤。"]},{"t":"再过乱落星","f":"五言律诗","c":["一去穷塞关，重来乱落星。","云归山脚白，天入石门青。","竦盻驱神远，深幽觉性灵。","香风长不散，兰蕙满阶庭。"]},{"t":"酬徐秀才栖贤韵 其一","f":"五言律诗","c":["一径松杉密，千峰雨雪寒。","有时云气入，逾觉草堂宽。","半菽山中味，香台鸟下餐。","高人来蜡屐，殊愧客盘单。"]},{"t":"酬徐秀才栖贤韵 其二","f":"五言律诗","c":["久住芙蓉侧，前山竟少游。","涧花朝亦采，松子晚方收。","草屦因人出，禽声为客幽。","堪嗟严子濑，徒有黑羊裘。"]},{"t":"寿黄子","f":"五言律诗","c":["玉醴难持赠，禅心君所亲。","但将今日意，长祝百年人。","鹤静能忘影，松寒不计春。","共看斯道胜，却笑枉逃秦。"]},{"t":"寿监寺旋兄","f":"五言律诗","c":["几年匡岳顶，坐月每怀君。","境觉閒中换，心从别后真。","气虚常接物，才富亦因人。","手泽千株茂，遐龄笑大椿。"]},{"t":"南海神祠","f":"五言律诗","c":["隋唐遗一庙，香火历千秋。","地足扶桑雨，山当大海流。","读碑堪吊古，问树识蛮陬。","正欲题诗去，笳吹起暮愁。"]},{"t":"浴日亭","f":"五言律诗","c":["万古祝融殿，千秋浴日亭。","气收南海阔，云到北溟青。","短景寒威弱，波声古木灵。","地舆曾入汉，辛苦使臣星。"]},{"t":"登西台","f":"五言律诗","c":["入望烟波阔，登台气象高。","风声低雁翅，海色上僧袍。","红日当朝见，鲛人闻夜号。","平生有怀抱，行坐总成劳。"]},{"t":"送顿修还栖贤随省亲苕上","f":"五言律诗","c":["何年共归去，岁岁送行舟。","渐老伤频别，长途系远愁。","白云深霅水，红叶满丹丘。","两处劳心膂，风烟日夜流。"]},{"t":"扫先师翁塔大雨赋此","f":"五言律诗","c":["四百峰中雨，倾盘聚此峰。","眉分双涧瀑，雷起隔溪龙。","土嫩难禁水，心悲易怯风。","晴阴付天地，随处见吾翁。"]},{"t":"送祖印游靖安","f":"五言律诗","c":["君去非予意，山川但暂看。","雪深知发白，云静觉江寒。","鞋岂南询着，衣从北路单。","相关切相望，勉矣慰人难。"]},{"t":"题波罗庙达奚司空","f":"五言律诗","c":["绝域无归日，炎州列汉官。","波声乡梦远，海色泪痕乾。","遗泽千秋古，蛮烟百代寒。","如今方羡汝，难得是衣冠。"]},{"t":"送记汝入栖贤","f":"五言律诗","c":["携手投名岳，閒心副薜萝。","诗吟佳景易，病系远人多。","溪咽了无梦，天寒自伐柯。","明年秋雁至，寄我慰如何。"]},{"t":"送陈牧止游篁山","f":"五言律诗","c":["兹行探白岳，不比赴公车。","风景供拈笔，高情在策驴。","山长欺雪过，岁晏藉诗除。","自得冥心理，门生可执书。"]},{"t":"闻见一病愈戏成","f":"五言律诗","c":["忽闻君病剧，凄断不堪陈。","旋得瞑眩药，犹惊矍铄神。","树盆嘱后事，花罐取藏身。","自此不须用，都应赠与人。"]},{"t":"顿修省觐苕上痛堪家难事后返栖贤久未入岭诗以速之","f":"五言律诗","c":["伤心看已过，几作覆巢馀。","大难频忧汝，生还但寄书。","山深风木苦，师远道颜疏。","应早趋瓢笠，繁心一解予。"]},{"t":"托钵佛山 其一","f":"五言律诗","c":["僧贫思仗钵，歛虑向人间。","窄路人争过，嚣声我独閒。","袖藏曾熟面，门掩尽愁颜。","舍卫城当日，如何便返山。"]},{"t":"托钵佛山 其二","f":"五言律诗","c":["一臂酸成毒，双胫涷欲枯。","市言多戏谑，僧笑讲锱铢。","头碎金鸡爪，鞋沾铁镬镆。","密云偏见雨，众口竟难糊。"]},{"t":"寄凌髭放","f":"五言律诗","c":["雨霁留君住，江深放棹归。","碧云虚野寺，春雾重征衣。","道在经行迹，时危畏钓矶。","衡门来剥喙，营虑及秋微。"]},{"t":"寿张母","f":"五言律诗","c":["欲驭瑶池驾，宁亲有凤毛。","百年双袖舞，万里一官劳。","厚泽穷檐遍，交情野衲叨。","清操有如此，方信白华高。"]},{"t":"顿修自髫水丁家难后掩关匡庐复归雷峰即以是日入侍寮诗以志喜","f":"五言律诗","c":["关掩伤心后，人归芳草前。","祇须长见面，不必问流年。","三佛香能爇，千秋愿未圆。","衰宗期努力，谁是着先鞭。"]},{"t":"闻凌髭放脱白丹霞此寄 其一","f":"五言律诗","c":["旧虑消轩冕，新情戴笠瓢。","水寒长见影，禅罢不过桥。","空谷存孤足，灵根得异苗。","昔时风穴谶，烁烁起云霄。"]},{"t":"闻凌髭放脱白丹霞此寄 其二","f":"五言律诗","c":["眼老烟霞阔，尘轻岱华浮。","几年无国土，今日有松楸。","窗冷山飞叶，心明海息沤。","再冬应得见，高腊笑云头。"]},{"t":"入肇庆峡","f":"五言律诗","c":["西风斜入峡，反侧片帆收。","怒浪先侵石，低沙不泊舟。","云开雷划火，野旷雨迷牛。","独数空江眼，浮沉万点沤。"]},{"t":"第二十三册初发琼州道中恭怀本师","f":"五言律诗","c":["塞雪曾辽左，蛮烟复海南。","风尘双短鬓，去住一征衫。","山向望中阔，书从梦里缄。","道情偏自重，翘首见慈严。"]},{"t":"天堂驿","f":"五言律诗","c":["新颓宫殿北，驿路过天堂。","青霭石争出，红桥花漫香。","车研春草短，鸠唤竹山长。","书册先贤在，予生亦未忙。"]},{"t":"阳春道中","f":"五言律诗","c":["山到阳春好，人传电白奇。","藤花行客采，鸟语土人知。","当面天门出，横桥岚气移。","蛮方如脱木，定胜是秋时。"]},{"t":"阳春县","f":"五言律诗","c":["小邑阳春县，荒冈䀨岭尖。","停轮惜白日，买饭爱青帘。","水米贱于布，山柴只换盐。","欲询明日路，乡语不能兼。"]},{"t":"晓发","f":"五言律诗","c":["晓发向通津，车声聒耳新。","蛮烟千里道，竹笠一閒身。","椰酒山家店，槟榔木客唇。","更逢赤眼叟，疑是泣珠人。"]},{"t":"车上 其一","f":"五言律诗","c":["野饭依山店，驱车向日边。","眼前云到地，身外事由天。","细雨滋油笠，高枝噪夏蝉。","一行森古木，髣髴住山年。"]},{"t":"车上 其二","f":"五言律诗","c":["有时不可耐，得意是无言。","草色尽情绿，莺声取次喧。","低头过石径，高枕憩蓬门。","亦是途中事，年来始自存。"]},{"t":"罗蛋","f":"五言律诗","c":["长途亦一食，饥困日难胜。","暑气万山出，青天一线迎。","沙低车脚软，石滑树头横。","果然行不得，惭愧鹧鸪声。"]},{"t":"电白县","f":"五言律诗","c":["风尘还自笑，岁月此淹留。","地僻逢人少，城荒见客愁。","藤蛇山店卖，海水县前流。","作宦同羁旅，人传此邑侯。"]},{"t":"热泉","f":"五言律诗","c":["车歇泉声热，岩开暑气多。","三春看若此，九夏复如何。","绕浪花根苦，寒流北涧和。","征尘或一洗，令尔想山阿。"]},{"t":"经化城庵见憨大师遗笔","f":"五言律诗","c":["弘法曾婴难，经过此地贤。","文章斯道大，笔墨世人传。","岳色摇还壮，岩花映独鲜。","所悲无后起，移睇欲潸然。"]},{"t":"三桥赠别王太初","f":"五言律诗","c":["相逢俱万里，分手向三桥。","山势背人远，车声入梦消。","砂红勾漏重，发白故乡遥。","日暮孤征酒，愁心尔可浇。"]},{"t":"赠张三","f":"五言律诗","c":["走马蓟门远，酬恩壮士心。","逢僧修白业，赠客辄黄金。","酒脱貂裘得，才因幕府深。","看君无不可，宝剑是知音。"]},{"t":"苦竹驿","f":"五言律诗","c":["已尽崎岖径，投南渐不毛。","雨侵人面黑，山映虎声高。","随身惟笠钵，过眼尽蓬蒿。","又说前途险，行人腰带刀。"]},{"t":"徐闻县","f":"五言律诗","c":["所经皆险僻，州县复凄凉。","旅思一时动，心情半日伤。","草深公府闭，人断禁门荒。","更有明朝役，乘槎泛渺茫。"]},{"t":"谭兑子以槟榔皮制鞋遗余谢之","f":"五言律诗","c":["野物君能致，幽情我不违。","子收南国重，皮拆女红微。","冠箨茅山小，衣莲梅老稀。","双凫虽称意，那向谷中飞。"]},{"t":"白衣庵新居 其一","f":"五言律诗","c":["自来无此畏，出郭愈多欢。","不是风尘苦，焉知水石难。","小床依草稳，片月到襟寒。","尚得馀今日，幽情或未阑。"]},{"t":"白衣庵新居 其二","f":"五言律诗","c":["城内无多事，朝朝怯马蹄。","门依堞影暗，首为主人低。","细语心常动，粗餐意倍迷。","槟榔图一醉，便梦玉渊西。"]},{"t":"白衣庵新居 其三","f":"古风","c":["岂敢求安住，深知厌此身。","一瓢供?轲，两眼足酸辛。","月色真难得，人情岂易论。","秋风莫轻触，发际渐如银。"]},{"t":"白衣庵新居 其四","f":"五言律诗","c":["已穷投食计，又乞买茆钱。","意怫西风苦，情深乡月悬。","竹声喧枕畔，椰叶到庵前。","亦是浮生事，焚香莫论禅。"]},{"t":"白衣庵新居 其五","f":"五言律诗","c":["敢云效古昔，亦负客中春。","贱极似成傲，愁多不为贫。","嗒然堪丧我，竟欲属何人。","所喜门前石，长吟不见嗔。"]},{"t":"游潭口放舟","f":"五言律诗","c":["解缆投何处，寻幽拟石厓。","一生贪笑傲，万里得情怀。","沙角鱼纹细，天边月影佳。","远游多怪事，余欲赠齐谐。"]},{"t":"泊邕阳","f":"五言律诗","c":["野泊邕阳好，晴看江月宜。","棹头天路远，转眼客心悲。","石浪归黎女，椰风聒鹭鹚。","系舟须着力，界外即南夷。"]},{"t":"潭口寻仙洞 其一","f":"五言律诗","c":["亦是翛然地，停舟恰受风。","水源黎母出，地脉扶桑穷。","怪鸟藤花杂，嘉葩椰叶重。","棋枰不可见，伫立上洪濛。"]},{"t":"潭口寻仙洞 其二","f":"五言律诗","c":["苍莽盘纡径，阴幽郁石台。","四山围不紧，一水划争开。","潭曲风声软，岩欹海色回。","一身经万里，难订是重来。"]},{"t":"送人还五羊","f":"五言律诗","c":["相送关予意，蛮烟独未归。","橹摇秋飓静，车展路花稀。","宝货槟榔重，新诗椰叶肥。","故山君处近，书札莫相违。"]},{"t":"别吴特公","f":"五言律诗","c":["语短爱君深，相逢直至今。","不堪形片纸，况复付长吟。","石路悬红日，青山惹素襟。","世名终自得，犹未是予心。"]},{"t":"别洪培自","f":"五言律诗","c":["子亦有馀致，烟霞得性灵。","风流传旧日，才气发新硎。","聚首宜秋月，分襟背落星。","几多言外意，莫损柳条青。"]},{"t":"九日高文斗招同诸公登浮粟","f":"五言律诗","c":["野色秋光满，亭高客望先。","酒香茶盏缓，日煖菊花鲜。","身世存微虑，山河带暮烟。","不因佳节序，难得到名泉。"]},{"t":"别李旸谷","f":"五言律诗","c":["谪宦南溟远，难为送别心。","鬓毛愁自短，乡思感何深。","剑怯龙泉号，声存太古音。","谁犹轻世态，握我泪沾襟。"]},{"t":"别王九如 其一","f":"五言律诗","c":["海势居然远，相看此共深。","世人论交态，惟子许初心。","独日窥行色，疏星散别襟。","无言亦不可，愁绝为知音。"]},{"t":"别王九如 其二","f":"五言律诗","c":["有酒君且醉，醉来语话长。","天性此时见，离情各自伤。","萤微飞易远，霜薄气难当。","不是无期别，山云信渺茫。"]},{"t":"梁孝廉敦五公车北上辱书见辞诗以送之 其一","f":"五言律诗","c":["对月高怀策，开缄念远行。","征裘万里色，岭树九秋声。","綵笔丰城气，虬珠合浦明。","知君鹏举志，原不为时名。"]},{"t":"梁孝廉敦五公车北上辱书见辞诗以送之 其二","f":"五言律诗","c":["君家旧簪笏，似舅岂云虚。","事业旧麟阁，文章新石渠。","芦沟匹马外，御苑惠风纡。","遥忆飞花处，何人念倚闾。"]},{"t":"寿汪水部汉翀 其一","f":"五言律诗","c":["道交君若此，相看岂计年。","薤丛频自绿，桃实静还鲜。","衣舄乘云久，襟期对月悬。","茂陵书著就，潇洒一儒仙。"]},{"t":"寿汪水部汉翀 其二","f":"五言律诗","c":["金盘浮玉液，五日得先沾。","觉性閒犹在，时情老自严。","门容乞士到，迹共野云恬。","万古春光满，殷勤为一拈。"]},{"t":"送余立人归江宁寿其尊人余澹心","f":"五言律诗","c":["塞上书归日，吴门雪落时。","言寻高士宅，远共白云期。","流水逢游子，吟诗得白眉。","柳条兼鹤算，持赠慰庭帏。"]},{"t":"答陈乔生","f":"五言律诗","c":["十年未相见，随处见君诗。","食檗心常苦，看山眼独疲。","片云清竹院，骤雨涨鱼池。","每想同居士，谈禅及此时。"]},{"t":"寿张进若","f":"五言律诗","c":["已饱烟霞气，犹餐日月芒。","骑驴疑制纸，叱石可成羊。","鬓绿春江水，文凌朔漠霜。","痴龙珠一粒，小劫未为长。"]},{"t":"寄贺吕明府宸铭","f":"五言律诗","c":["仙郎异绩成，清操彻玉京。","犊留淮土重，凫坐邺侯轻。","人爵青云蔚，天姿白雪明。","行当入参政，雅量复相惊。"]},{"t":"送郑襄孙归安肃","f":"五言律诗","c":["上客邯郸至，炎天粤峤归。","路长裘马旧，心壮水云肥。","木叶催高树，征帆挂落晖。","相逢几回笑，禅意赠君微。"]},{"t":"寿刘内史奇公","f":"五言律诗","c":["大业千秋在，灵椿八百高。","堂深天外雪，风壮海门涛。","烛为娇歌艳，觞传鹤羽劳。","名香吾欲祝，髣髴听云璈。"]},{"t":"赠李婉若","f":"五言律诗","c":["冰霜骨自健，经史性生成。","每爱临风语，常期过寺行。","暗花绚梦笔，爽气阔秋城。","何必玄晖辈，山僧始有名。"]},{"t":"送陈焦源还山阴","f":"五言律诗","c":["曾领苍梧部，今归庾岭风。","声名人口里，事业鬓丝中。","高论真难得，清操道已穷。","兰亭一盂水，迟我暮年逢。"]},{"t":"寿钱霞蔚","f":"五言律诗","c":["独抱冰霜骨，梅花万树开。","金丹人取去，玉蕊手持来。","问法寻刍叟，吟诗向古台。","胜因从此结，予愧有尘埃。"]},{"t":"梁孝廉画石教授寿康","f":"五言律诗","c":["上书裘尚黑，作宦帐先红。","道德传前辈，文章教巨工。","山寒官路阔，心静玉堂空。","老我相期意，依依在此中。"]},{"t":"吴司李锦雯偕令弟我蕃并陆丽京张宗绪顾祥士过访 其一","f":"五言律诗","c":["霜菊荒三径，冰壶共一船。","綵云看满地，奇蕊落诸天。","道见祥刑合，名先大雅传。","山僧禅悦里，得结此中缘。"]},{"t":"吴司李锦雯偕令弟我蕃并陆丽京张宗绪顾祥士过访 其二","f":"五言律诗","c":["世路劳车马，清言重缙绅。","居心原有地，君虑自无尘。","古佛仪犹在，苍生望又新。","群公兼此意，慧远亦亲人。"]},{"t":"喜潘明府澹庵至","f":"五言律诗","c":["兰堂来上客，琼海意中人。","觅我琴留舫，看君气似春。","风尘消宦兴，诗酒固天真。","莫着羊裘去，烟波泛钓津。"]},{"t":"寿何鸣玉","f":"五言律诗","c":["鳌首三山稳，松枝万叶稠。","閒心原似水，高节竟凌秋。","国计才尤敏，朋情意独优。","碧峰飞白鹤，欢喜进双筹。"]},{"t":"沈融谷从雄州至五羊相见且言归浙送行二章 其一","f":"五言律诗","c":["恳恻欣相见，慇勤复送归。","月寒南粤地，风入富春衣。","千嶂窥人寂，双瞳似尔稀。","无穷兰蕙草，何处借芳菲。"]},{"t":"沈融谷从雄州至五羊相见且言归浙送行二章 其二","f":"五言律诗","c":["作赋文心好，言诗雅道高。","既能惊世眼，尤见恋僧袍。","雁语占星斗，鼍行郁海涛。","倘能修短札，寄我莫辞劳。"]},{"t":"送陈石人归闽","f":"五言律诗","c":["归路潮阳直，逢僧海寺初。","高名空可恋，寒树独教疏。","涷月光先动，狂帆意自如。","纵然无雁到，亦记寄双鱼。"]},{"t":"寿张梦回 其一","f":"五言律诗","c":["小范胸中似，维摩屋里真。","雄心能度日，石磬不生尘。","抖出松枝雪，携来柏叶春。","廿年同学道，君作采芝人。"]},{"t":"寿张梦回 其二","f":"五言律诗","c":["白鹤语高墀，红霞映赤蜺。","山藏安石日，人在霸陵时。","月满篁溪竹，花开古佛池。","原称无量寿，于此更何疑。"]},{"t":"寿彭明府退庵 其一","f":"五言律诗","c":["大智应持世，明珠合走盘。","古棠春气密，厚泽邑人欢。","笔墨南宫壮，云霞北斗寒。","此心无间断，常作万年看。"]},{"t":"寿彭明府退庵 其二","f":"五言律诗","c":["律清欣黍谷，星老爱长庚。","海屋原归鹤，春风自入城。","活人宁有数，护法感常情。","天静琅琅雁，云端有好声。"]},{"t":"彭明府退庵招同江若海诸公茶集","f":"五言律诗","c":["所思隔珠江，一苇法流通。","高盖低银浪，清谈夺綵虹。","水浮荷气密，风落竹声同。","斟酌双兰影，芳馨还令公。"]},{"t":"韶石舟中 其一","f":"五言律诗","c":["夜行将落月，寒看欲曙天。","事抛离岸后，心系放舟前。","暝色攻衫薄，繁霜滴缆圆。","此中辛苦意，专为送流年。"]},{"t":"韶石舟中 其二","f":"五言律诗","c":["于我原无事，因人倍复忙。","雁归燕地雪，客犯岭头霜。","山木何曾脱，江云只是长。","所嗟非气候，别有旅魂伤。"]},{"t":"韶石舟中 其三","f":"五言律诗","c":["偶然为此役，行止笑难期。","入夜依沙际，长吟山峡时。","嶂深猿穴壮，名在水云疑。","我亦从兹悟，寒江酌一卮。"]},{"t":"韶石舟中 其四","f":"五言律诗","c":["已见三秋雁，犹行十月风。","往来无至计，得丧欲将穷。","沙迥寒鸥白，山高夜火红。","空将寥廓意，独宿暮烟中。"]},{"t":"韶石舟中 其五","f":"五言律诗","c":["世岂藏名地，山当骤鹿宜。","偏舟生范蠡，片石死要离。","寂寞惟看月，经营不及时。","此时松柏色，难得是高枝。"]},{"t":"韶石舟中 其六","f":"五言律诗","c":["别俗敦高尚，和光贵大乘。","自来同嚼蜡，今更欲餐冰。","白发徒兼鬓，黄金不作绳。","孤舟迎浪上，此处若为平。"]},{"t":"韶石舟中 其七","f":"五言律诗","c":["蒙叟梦先得，彭篯术未工。","露兼凉月下，影逐大江空。","雨过啼閒鸟，天低落近虹。","玉鞭吾欲把，帝座莫为通。"]},{"t":"韶石舟中 其八","f":"五言律诗","c":["无事孤骞兴，秋江一棹寻。","不因今日役，亦有此时心。","星起猿啼泽，人醒月在林。","更寻何处宿，前路一灯深。"]},{"t":"韶石舟中 其九","f":"五言律诗","c":["才别还相逐，同行落后波。","世难知己少，路远受风多。","谷口云初断，樯阴雁已过。","相看虚岁月，不及一渔蓑。"]},{"t":"韶石舟中 其十","f":"五言律诗","c":["今岁菊花候，舟行未暂停。","枫林秋岸赤，石色峡中青。","身倦重朝梦，鸥寒集晚汀。","微愁无计遣，力不到参苓。"]},{"t":"大士石","f":"五言律诗","c":["圆明一念固，不比望夫山。","云绕乾坤阔，灯悬日月閒。","三边随业见，一夜逐人还。","不尽杨枝水，长流入世间。"]},{"t":"射鼋鱼者","f":"五言律诗","c":["挟矢候江阴，鼋鱼出绿浔。","年华生意苦，天地杀机深。","掬水犹磨雪，侵肌竟是金。","高山不可住，令我独沉吟。"]},{"t":"咏鸬鹚 其一","f":"五言律诗","c":["辛勤始得食，汝亦为谁忙。","水性微生苦，潭深薄暮寒。","宾鸿飞自远，翡翠立应欢。","人欲几曾厌，毛衣何日乾。"]},{"t":"咏鸬鹚 其二","f":"五言律诗","c":["欲大方怜汝，身微亦系人。","常随孤桨去，不与众毛亲。","潮落愁空坦，鱼寒隐夜津。","宁啼杜鹃血，飞过万山春。"]},{"t":"咏鸬鹚 其三","f":"五言律诗","c":["金弹落饥鸟，寒潮变绿芜。","身随閒处贱，力向苦中无。","入水全凭眼，提筐不用呼。","月明归未得，刷羽向江湖。"]},{"t":"旅舟遇人之京","f":"五言律诗","c":["分符南海客，走马蓟门天。","穗石别多日，韶阳同泊船。","旧名遗爱在，新月大荒圆。","更得朝衣著，何年再问禅。"]},{"t":"相江叹 其一","f":"五言律诗","c":["壮岁逢沙汰，髫年饱乱离。","计穷观世日，悲正及秋时。","短发羞人见，长贫有钵知。","我心不可转，鸥鸟莫相疑。"]},{"t":"相江叹 其二","f":"五言律诗","c":["运会丁黄檗，分徒类夹山。","愁多伤肺易，僧老改形难。","夜入疏钟苦，潮归独院寒。","无聊频徙倚，犹把梵书看。"]},{"t":"相江叹 其三","f":"五言律诗","c":["安能关至计，无乃损皇仁。","错念观前世，闲言误后人。","昙花甘委雪，篱槿岂禁春。","谁道琉璃国，笳吹不起尘。"]},{"t":"相江叹 其四","f":"五言律诗","c":["檀林烧豆火，水族失龙鳞。","乘槎难及汉，避俗敢言秦。","碧海徒多梦，青山已少人。","独怜边徼地，不及帝城春。"]},{"t":"相江叹 其五","f":"五言律诗","c":["天地微生薄，风霜岁月赊。","金钩奔醉象，玉盏落长蛇。","草遇千年雪，莺啼二月花。","宝龛尘渐积，珍重拂轻纱。"]},{"t":"相江叹 其六","f":"五言律诗","c":["袈裟犹未白，螺髻镇常青。","有愿酬今日，无言问小乘。","情田心莫莫，玉海泪盈盈。","满山松柏色，不作旧时声。"]},{"t":"相江叹 其七","f":"五言律诗","c":["圣朝应勿阙，斯道与斯文。","清磬凭谁击，名香岂易焚。","寒星人外见，天梵静中闻。","纵得常如此，沙鸥已失群。"]},{"t":"相江叹 其八","f":"五言律诗","c":["万物欣其盛，何能守寂寥。","月沉空有恨，风急自无潮。","一念终难到，三禅岂易烧。","还将金玉带，依旧镇山腰。"]},{"t":"相江叹 其九","f":"五言律诗","c":["庄严欣帝梵，衰落妒波旬。","究竟空怜我，依然不怨人。","灵蛇收鲤眼，宝剑涸龙津。","却怪林逋鹤，生来骨相贫。"]},{"t":"相江叹 其十","f":"五言律诗","c":["海竭珊瑚死，林深虎豹屯。","无人添食钵，教我住荒村。","梦逐梅花去，形愁槁木存。","长廊风寂寂，日落自关门。"]},{"t":"往来胥口不得登岸柬王明府默庵 其一","f":"五言律诗","c":["心知谈笑处，两逐往来程。","此邑山形壮，故人江水清。","署寒琴指冷，天静雁声明。","宰政原辛苦，君兼百代情。"]},{"t":"往来胥口不得登岸柬王明府默庵 其二","f":"五言律诗","c":["城荒秋草遍，天远彩云多。","独树连高峡，斜阳撼夕波。","弓裘传旧业，雨露得新和。","柔橹乘潮去，长吟一望过。"]},{"t":"寿樊犬愿","f":"五言律诗","c":["五十一年前，香花结寿筵。","文心坚大道，微愿薄诸天。","里俗推先辈，丛林即后贤。","如今无枣柏，坚固是金仙。"]},{"t":"送吴伯子归琼海","f":"五言律诗","c":["未必终如此，功名自有时。","海云千里阔，林月五更悲。","爱子能相见，愁予是别离。","古人裘破后，此段竟谁知。"]},{"t":"送陈白禄之京","f":"五言律诗","c":["陶朱不可学，张禄岂堪名。","正值重阳日，言从万里行。","燕台寒雪蚤，庾岭小梅清。","相忆归来候，明年春雁声。"]},{"t":"屈五明秋捷","f":"五言律诗","c":["亲老先能慰，文章始是真。","持心期旧日，梦笔爱新人。","水到天河润，花从北地春。","征衫须自脱，何处有京尘。"]},{"t":"陈表学秋捷","f":"五言律诗","c":["喜看惊座客，战胜向秋天。","芳誉从人著，樨香入耳圆。","路迎金阙日，裘阔玉河烟。","绣佛龛前望，如君本少年。"]},{"t":"寿朱说梅明府","f":"五言律诗","c":["知君心自达，杯酒可为欢。","閒处寻归马，尘中不恨官。","月临沧海阔，花照客庭寒。","上寿琴音见，椿枝欲赠难。"]},{"t":"赠陆仲侯","f":"五言律诗","c":["白眼原难富，丹青岂贷贫。","甑中飞野马，世上待何人。","地僻长无雪，花妍不是春。","少年沽美酒，更莫望乡津。"]},{"t":"题蒋徂来明府八骏图 其一","f":"五言律诗","c":["地厚凝云暗，天高积雪长。","一声过大宛，万里到扶桑。","空旷随青草，驱驰限紫缰。","旅魂劳易倦，托尔在斜阳。"]},{"t":"题蒋徂来明府八骏图 其二","f":"五言律诗","c":["不怨孙阳去，方怜逸足来。","人名高凤阁，雪路困龙媒。","绿水嘶时涷，红云踏处开。","深思长独立，未必胜无才。"]},{"t":"赠汪汉翀水部","f":"五言律诗","c":["交久心逾好，深持长者风。","诗名高往哲，道力破洪濛。","补脑天浆白，留颜大药红。","君犹情未惬，宦迹厌飘蓬。"]},{"t":"送罗学制守阃","f":"五言律诗","c":["三年能读礼，此日复谈军。","甲胄威犹在，蹄轮路自分。","剑光连蚌气，笔阵战山云。","勋业从兹大，高鶱列雁群。"]},{"t":"为刘子两大命名示此","f":"五言律诗","c":["大道原无二，期君两大之。","玉堂云起日，宝地月明时。","随步堪闻桂，趋庭可学诗。","圣贤皆努力，才气正相宜。"]},{"t":"祝词","f":"五言律诗","c":["北岭松犹盛，南山鹤可闻。","堂悬三岛月，杯泛五湖云。","綵凤飞无已，天花落自纷。","与君同浩劫，握手问高旻。"]},{"t":"张全之将归桐城同姚梅长行过宿海幢诗以送之","f":"五言律诗","c":["归路同良友，兼逢野寺僧。","松枝高壮气，海色送孤城。","潮起船头合，江虚棹影清。","莫言不相寄，到处有鸿声。"]},{"t":"送任玉书之秦中","f":"五言律诗","c":["北去走风尘，襟期万里新。","月临官渡阔，花向大江春。","得意惟驱马，挥金好赠人。","珠江江上月，相忆最相亲。"]},{"t":"张穆之买泷水山移家索赠","f":"五言律诗","c":["别寻幽壑胜，壮气此中消。","逸足已云远，閒云祇自招。","易观沧海日，难问古今潮。","暂去还来此，朋侪叹寂寥。"]},{"t":"送刘汉臣归凤城","f":"五言律诗","c":["草室无馀蕴，君归幸念之。","暮云兰叶架，疏雨藕花池。","义寂文心薄，珠明智眼移。","毋为逐卑论，白社订幽期。"]},{"t":"筑堤诗 其一","f":"五言律诗","c":["贳地开精舍，穿渠待竹林。","了无香火念，只有水云心。","锄起惊秋草，虫分隔路吟。","莫言吾自限，用意此中深。"]},{"t":"筑堤诗 其二","f":"五言律诗","c":["略似苏公意，无湖祇有堤。","水来拖素练，日落卧长霓。","辨土寻龙脉，扶筇听鸟啼。","对人挥汗罢，潇洒在鸡栖。"]},{"t":"筑堤诗 其三","f":"五言律诗","c":["大块真劳我，高天亦限人。","溪山千片石，城郭一朝春。","锄过坭痕滑，堆平月色匀。","古人还负担，吾敢厌嚣尘。"]},{"t":"筑堤诗 其四","f":"五言律诗","c":["冬至移花候，春当插柳时。","斫柴徐计颗，得米已堪炊。","海色归新圃，风声聚乱枝。","少年贫贱早，生计苦相思。"]},{"t":"筑堤诗 其五","f":"五言律诗","c":["耕凿真无力，逢迎已入心。","眼徒空处白，地是几时阴。","梅即能飘雪，霞先漫落金。","殷勤多自爱，肯受二毛侵。"]},{"t":"筑堤诗 其六","f":"五言律诗","c":["锹子乾坤阔，阿师气宇低。","无田开大义，有路作卑蹊。","白拂穿林易，黄花照眼迷。","旧时飞动意，寂寞向畬坭。"]},{"t":"筑堤诗 其七","f":"五言律诗","c":["已分僧俗路，难爱浅深田。","石破通山气，风吹入海烟。","乞人移树色，借贷散工钱。","抱膝吾还乐，艰难过六年。"]},{"t":"筑堤诗 其八","f":"五言律诗","c":["蛟龙潜地骨，钟磬任天心。","粥饭有缘聚，云山随处深。","海波吹自昔，人迹在如今。","亦是难由我，馀生听陆沉。"]},{"t":"筑堤诗 其九","f":"五言律诗","c":["平生期浪迹，岂意作开山。","百短同衰鬓，千般只笑颜。","棘林藏月碎，弓地聚云閒。","抖擞辽东衲，何时着过关。"]},{"t":"海幢基趾即予少年卖饼地也","f":"五言律诗","c":["饼卖当年地，禅栖此日心。","长林飞翡翠，短褐接华簪。","螮蝀惊弦落，龙蛇喷雾深。","不须神拔树，吾种亦成阴。"]},{"t":"戊申夏日喜张百庵中秘过访却赠即送还朝 其一","f":"五言律诗","c":["八桂皇华使，仙帆泛五羊。","星光还远近，逸气正苍茫。","琢句江山古，寻幽花雨香。","元来屋里客，麈尾好商量。"]},{"t":"戊申夏日喜张百庵中秘过访却赠即送还朝 其二","f":"五言律诗","c":["绿发剑光寒，青云识俊官。","笔花江梦醒，诗帙陆装宽。","阅世已无语，因君忽破垣。","此中还会得，鹤盖即蒲团。"]},{"t":"戊申夏日喜张百庵中秘过访却赠即送还朝 其三","f":"五言律诗","c":["禅心尤自旷，不在比邻间。","一棹珠江远，三秋蓟雪还。","月篷推自看，云路悟应閒。","劫外能相忆，依稀鹫岭山。"]},{"t":"送沈存西归浙 其一","f":"五言律诗","c":["去住经双眼，风尘足百蛮。","怀高为客易，年老别家难。","水阔孤帆满，天凉夜酒乾。","今朝歌别曲，禅绪太无端。"]},{"t":"送沈存西归浙 其二","f":"五言律诗","c":["亲戚天涯遍，琴书道路迟。","寺边分野衲，岭上见佳儿。","华萼船尤丽，秋风句自奇。","独怜流水意，何处更相期。"]},{"t":"赋得石琴觉幻","f":"五言律诗","c":["绿野芳尘远，珠江敞石琴。","霜归三径菊，月满百年心。","罗绮香风煖，云山觉路深。","谷城多秘笈，还向此中寻。"]},{"t":"送方世五归白下","f":"五言律诗","c":["意阔无归计，言归路更长。","相看疑绝塞，惜别在重阳。","寒水烟迷棹，高天雁带霜。","此中殊洒落，谁得拟行藏。"]},{"t":"寄赠王崇芳","f":"五言律诗","c":["琥珀变松脂，神光照陆离。","昔曾窥至道，今复傲庞眉。","山隐梅村径，身疑洛社期。","自从云树别，忆我在河湄。"]},{"t":"孙鹤林居士为狂人所累赴理五羊今得脱然诗送之归 其一","f":"五言律诗","c":["故里三年别，风波此日归。","天倾身蚤贱，道在怨应希。","秋叶霜飞冷，滩声夜听微。","独惭空有意，无以送寒衣。"]},{"t":"孙鹤林居士为狂人所累赴理五羊今得脱然诗送之归 其二","f":"五言律诗","c":["多君真有子，患难自能将。","儿戏劳三尺，悲酸尽两行。","旅途堪强饭，归路更烧香。","相看一感激，此意岂能忘。"]},{"t":"梁海文初度","f":"五言律诗","c":["世路看如此，期君语意长。","佛心敦大业，人行薄文章。","水石存孤骨，参苓验圣方。","芳晨敷讲罢，馀坐对松篁。"]},{"t":"答吴石林","f":"五言律诗","c":["军容临鳄水，仙韵到孤峰。","墨汁留燕石，文情压大宗。","翱翔疑翥凤，磅礴竟屠龙。","何日来相见，西窗烛影重。"]},{"t":"送光半游山东","f":"五言律诗","c":["孤锡送寒海，风霜意已深。","初移庾岭步，竟有泰山心。","衲破尘窥絮，淮长月堕襟。","念予思共力，归兴挽幽寻。"]},{"t":"敬人六十又一","f":"五言律诗","c":["亦得孤松意，云根瘦削成。","尽心供佛事，百忍见生平。","理衲存清夜，呈材遣墨卿。","高凉当日役，予亦动予情。"]},{"t":"寿池月五十又一","f":"五言律诗","c":["竟是因缘地，同君爱独深。","艰难支佛法，寂寞见予心。","凿井留虹影，栽桐奏凤音。","此中无量劫，消息尚堪寻。"]},{"t":"送依石老僧入丹霞并谢其赠端州石","f":"五言律诗","c":["搜得青山骨，添予白昼心。","勇能离故土，老好入丛林。","一念行应到，千岩坐更深。","寒云交密处，踪迹渺难寻。"]},{"t":"己酉端阳前五日喜汝得侍者归自陵阳吉水因作四十字","f":"五言律诗","c":["添钵过双县，怀人逾半年。","痴成卑佛力，穷更累官钱。","雪影沉湖月，花春散岭烟。","一经人世路，方信有先鞭。"]},{"t":"赠尸林","f":"五言律诗","c":["频死同归后，分携又十年。","死生俱有托，去住尚依然。","风雪千山泪，辛勤一衲烟。","但持吾道在，即是答先贤。"]},{"t":"十一游罗浮诗 其一","f":"五言律诗","c":["十载登临兴，年年自不同。","霞光明挂树，山气暗攻中。","雨骤催溪涨，峰晴被雾笼。","暝心归物外，谁是解谈空。"]},{"t":"十一游罗浮诗 其二","f":"五言律诗","c":["久得归山意，真难说与人。","野烧围岭背，耕犊破山唇。","异草难求号，仙花只耐春。","暂时高处望，又见下方尘。"]},{"t":"十一游罗浮诗 其三","f":"五言律诗","c":["古木围林密，烟村此结茅。","棘门杉叶缚，人面雨痕胶。","箭镞涂生药，花枝挂劲矛。","长将仙洞树，斫尽炙山庖。"]},{"t":"十一游罗浮诗 其四","f":"五言律诗","c":["据树吾忘我，过桥影待人。","突云欺袖入，侧帽闪风频。","高鸟晴啼爽，长藤绿挂春。","气微忻厌念，无力辨谁真。"]},{"t":"予欲复梅花庄已縳茅三间种梅数千本 其一","f":"五言律诗","c":["尚有梅村地，为椽可耦耕。","身閒仙易得，心苦事难成。","大屋悬长铎，低茅縳直绳。","两般生趣味，一笑问溪声。"]},{"t":"予欲复梅花庄已縳茅三间种梅数千本 其二","f":"五言律诗","c":["已近朱明洞，仙炉在此间。","更谁生白羽，只有换红颜。","大药非凡宝，真心本至閒。","徘徊迟语嘿，日影已衔山。"]},{"t":"予欲复梅花庄已縳茅三间种梅数千本 其三","f":"五言律诗","c":["絮薄轻难煖，山重静更寒。","映花松户小，得月夜楼宽。","石咽闻溪响，峰奇徙榻看。","风炉长不断，沸水炙频乾。"]},{"t":"予欲复梅花庄已縳茅三间种梅数千本 其四","f":"五言律诗","c":["洞隐千寻磴，泉飞百道帘。","乱藤愁力尽，急响觉神添。","树曲盘无壤，厓棱洗去尖。","几多青霭色，还向下方潜。"]},{"t":"宝积寺 其一","f":"五言律诗","c":["异锡穿山骨，芳膏迸石流。","药苗香不到，风力冷全收。","足下云生岭，窗间树挂猴。","未能成一宿，五负此林丘。"]},{"t":"宝积寺 其二","f":"五言律诗","c":["易引孤筇去，难名异鸟啼。","晴岚初放岭，曲树已吞溪。","蚁穴藏青霭，蜂房贴紫坭。","且将蝴蝶梦，先寄石楼西。"]},{"t":"宝积寺 其三","f":"五言律诗","c":["薇老还能食，花奇可插瓶。","潭心龙气黑，僧面岳形青。","山大猺居密，鸾多羽族灵。","洞天深寂寂，星月大柴扃。"]},{"t":"宝积寺 其四","f":"五言律诗","c":["才沿峻壁还，寻溪意未閒。","日光先透石，树势欲争山。","花是仙源异，头从玉塞班。","廿年辛苦意，凄折对松关。"]},{"t":"宝积寺 其五","f":"五言律诗","c":["斜阳明谷口，金色忽离披。","病久骨先弱，乍閒意便宜。","窗窥人上岭，枕听鸟呼儿。","更欲探奇去，扪苔读古碑。"]},{"t":"宝积寺 其六","f":"五言律诗","c":["又逐晨鸡去，相将甲马还。","去如愁故国，忙亦累名山。","云势宜长夜，峰皱失旧颜。","溪光兼树影，疑惑不能删。"]},{"t":"朱孔晖澹归俗婿也来自武林时澹归与予度夏海幢孔晖因从予品戒于其归送诗三章 其一","f":"五言律诗","c":["廿年怀骨肉，万里向江湖。","空有金人梦，全成铁佛图。","家园沈定水，眷属隐衣珠。","但立门人后，西风绕碧梧。"]},{"t":"朱孔晖澹归俗婿也来自武林时澹归与予度夏海幢孔晖因从予品戒于其归送诗三章 其二","f":"五言律诗","c":["俗缘忽已断，亲入丈人峰。","话堕疏林月，情消午夜钟。","秋波归路阔，别思客心重。","谁识团圞意，庞家尚觉浓。"]},{"t":"朱孔晖澹归俗婿也来自武林时澹归与予度夏海幢孔晖因从予品戒于其归送诗三章 其三","f":"五言律诗","c":["爱我求摩顶，忻君亦似僧。","流云方有岫，出世岂无能。","散鬓随愁转，秋虫入夜增。","莫将乡井思，数对客船灯。"]},{"t":"送彭飞云归武昌","f":"五言律诗","c":["达者皆频去，谁经海国忧。","烽烟深楚地，风雪冷貂裘。","雅量经纶外，閒情日月浮。","何当相见处，白首话沧洲。"]},{"t":"和采臣吴粮宪道中老翁售琴之作 其一","f":"五言律诗","c":["山路经乡落，篮舆值老翁。","手携古云物，言是旧丝桐。","乱世谁怜苦，閒官可话穷。","南薰无限意，珍重与人同。"]},{"t":"和采臣吴粮宪道中老翁售琴之作 其二","f":"五言律诗","c":["未拂牛衣泪，欣投凤阁仙。","元音归太始，远世重流年。","驳落潜虬老，峥嵘劫火然。","隆中兼栗里，一样泻飞泉。"]},{"t":"送管钟石使君荣赴崇安时值览揆 其一","f":"五言律诗","c":["雨洒无痕地，风吹有色云。","道情偏感我，清望最宜君。","双履如凫转，千松过岭闻。","江皋晴吐月，遐思自纷纷。"]},{"t":"送管钟石使君荣赴崇安时值览揆 其二","f":"五言律诗","c":["闽地劳新命，羊城送旧知。","他宵一夜里，忆此八年时。","玉轸调珠水，仙云拥武夷。","清茶敲石火，眉寿乐天机。"]},{"t":"送沈石友醝使之任三衢郡丞 其一","f":"五言律诗","c":["击节中宵起，劳歌一送君。","凄清蓟北雪，缭乱岭南云。","道直存天意，才难见鹤群。","更谁开口笑，疏磬对斜曛。"]},{"t":"送沈石友醝使之任三衢郡丞 其二","f":"五言律诗","c":["中州尊斧钺，南海事卑栖。","不作贾生赋，空行苏子堤。","鬓毛偏不改，心迹迥难齐。","为问平津阁，何时诏紫坭。"]},{"t":"送沈石友醝使之任三衢郡丞 其三","f":"五言律诗","c":["回天消积害，持地任惊涛。","独识人应忌，孤根节自高。","酒浓沉块垒，诗捷发雄豪。","静得神珠照，原无叱驭劳。"]},{"t":"送沈石友醝使之任三衢郡丞 其四","f":"五言律诗","c":["直怀开济念，那复羡微官。","雪路拥熊轼，风声集马鞍。","眼醒身世薄，心重酒杯寒。","空有珠江月，长留别后看。"]},{"t":"送沈石友醝使之任三衢郡丞 其五","f":"五言律诗","c":["岭云随一鹤，天路透三衢。","悲喜非吾道，驰驱见大儒。","津头迎卤簿，日色闪氍毹。","为访青霞洞，心閒政自殊。"]},{"t":"送冯孔武进士","f":"五言律诗","c":["大树君宜憩，高名人共传。","帝城鞭白马，佛国长青莲。","道术存东鲁，功名属少年。","丈夫不惜别，翻觉此情偏。"]},{"t":"送鲍云从 其一","f":"五言律诗","c":["幕府推雄俊，高名蚤识君。","一逢杜武库，真见鲍参军。","意气金兰丽，风流玉蝶群。","此中谈易尽，衫袖染山云。"]},{"t":"送鲍云从 其二","f":"五言律诗","c":["柳色攀尤好，此心无歇时。","山随征马去，风逐锦帆披。","鼓角天衢阔，星霜地轴移。","閒时衔杯酒，寄我慰相思。"]},{"t":"送鲍云从 其三","f":"五言律诗","c":["王事能将母，蛮烟解袭人。","凯风悲孝子，行役怆孤臣。","柏叶先秋变，龙泉滴泪匀。","图麟勋业在，别矣慎风尘。"]},{"t":"送鲍云从 其四","f":"五言律诗","c":["江路秋声转，云峰雁影斜。","分天窥皓月，把袖记年华。","蟋蟀啼无已，星霜鬓有加。","天涯飘杖笠，为访赤城霞。"]},{"t":"喜姚雪庵出贡","f":"五言律诗","c":["脱却青衫好，欣看愿力成。","万年唯此念，三策动高名。","春水南天满，飞尘北地轻。","莲花经一卷，万里伴君行。"]},{"t":"送李世鼎明府之任福清","f":"五言律诗","c":["送君江上路，真有岁寒情。","好雪过庾岭，春风到福清。","玉弦潘县静，珠水李舟轻。","古道劳相忆，遥遥听颂声。"]},{"t":"赠文源 其一","f":"五言律诗","c":["万里忽相见，回惊话别时。","廿年辽左雪，双鬓岭南丝。","贝叶金陵纸，莲花上国池。","山川来往处，锡影戒光移。"]},{"t":"赠文源 其二","f":"五言律诗","c":["千山怀扫塔，廿载忆烧香。","古塞烟尘满，悲心岁月长。","来秋应走马，与子共淩霜。","且作珠江别，深春杜宇忙。"]},{"t":"寿汪汉翀","f":"五言律诗","c":["十载庆生辰，华堂对水滨。","高低千顷树，新旧几多人。","火燄丹能熟，情深道更贫。","此翁有高致，偏不逐嚣尘。"]},{"t":"林太君节烈诗","f":"五言律诗","c":["贤母何曾死，馨香百代存。","诗书无内外，烈节有儿孙。","举案人何往，旌闾事更尊。","予从青史后，欲吊愧无言。"]},{"t":"寿柴云荐","f":"五言律诗","c":["雪枣如银白，丹砂似血红。","不悬金鼎内，只在玉堂中。","甘露天池满，神工地脉雄。","有谁通秘妙，此道属柴公。"]},{"t":"寄寿秦左星使君 其一","f":"五言律诗","c":["烧丹人未老，对酒兴应豪。","持虑偏无失，为官自觉劳。","玉摇山月静，云起夜声高。","自得中和理，冰盘胜碧桃。"]},{"t":"寄寿秦左星使君 其二","f":"五言律诗","c":["寿阳峰独峻，德泽与千年。","地阔苍梧雨，人看蓟北天。","插松青佛宇，留念及山禅。","欲寄浮丘信，微茫海国烟。"]},{"t":"寿李天御","f":"五言律诗","c":["自得千寻气，诗书见道源。","勋名悬北阙，喉舌重南藩。","好梦琼花观，凉风绿雪轩。","寄言王子晋，何必事高鶱。"]},{"t":"从韶州取道平圃","f":"五言律诗","c":["趋陆持孤锡，依山逐二官。","杉云寒影密，冬岭烧痕宽。","石阁岏巑起，心情委曲难。","几多行役意，都作住山看。"]},{"t":"从平圃入始兴江口","f":"五言律诗","c":["雄州百馀里，平圃候鸡鸣。","月照野云落，篮随官马行。","舟胶初涷水，人过落滩声。","两鬓看如此，行藏计未成。"]},{"t":"山东道中","f":"五言律诗","c":["鸡鸣天未曙，各自理征鞭。","路滑畏行石，喉乾望打尖。","密云依小屋，荒井发虚烟。","记得庐山麓，松高看鹿眠。"]},{"t":"官桥","f":"五言律诗","c":["又投何处宿，百里到官桥。","饭惟烧大麦，路似上青霄。","沙起云缠马，风吹面过箫。","三更初睡熟，犹觉梦魂摇。"]},{"t":"过黄河 其一","f":"五言律诗","c":["已尽江南路，黄河带月过。","客心愁地阔，风力入霜多。","日色依山澹，鸿声怯冻和。","从来辛苦意，孤负好岩阿。"]},{"t":"过黄河 其二","f":"五言律诗","c":["初气战洪濛，寒霜凛冽中。","渡河方数里，此岸不同风。","草短蹄痕绉，空长眼力穷。","一轮残月影，一半是山东。"]},{"t":"岁尽出恩县","f":"五言律诗","c":["二月魂俱倦，途穷岁亦穷。","日低难破雪，袖大苦藏风。","面店分钱食，茅庵乞火烘。","寄言清坐客，珍重好帘栊。"]},{"t":"王淑莘文学以感遇诗一首见贻即步元韵奉和三章志赠 其一","f":"五言律诗","c":["久曾吾丧我，羁旅幸依人。","饮酒何妨畅，论交可入神。","闭门风雪急，阅世水云屯。","一卷南华乐，翛然得共亲。"]},{"t":"王淑莘文学以感遇诗一首见贻即步元韵奉和三章志赠 其二","f":"五言律诗","c":["相逢俱未易，乞食对何人。","绝意忘牛马，中宵近鬼神。","事销吾道泰，世乱客途屯。","珍重王居士，诗篇许独亲。"]},{"t":"王淑莘文学以感遇诗一首见贻即步元韵奉和三章志赠 其三","f":"五言律诗","c":["雪意寒侵烛，窗光欲照人。","翻书存古雅，自诵每伤神。","事业材宜隽，经纶道用屯。","知君原落落，努力可娱亲。"]},{"t":"赠王中翰","f":"五言律诗","c":["中翰青云士，文章白玉姿。","交从天外阔，兴到岭头奇。","雪影高鸿翼，花砖见凤仪。","青莲池畔话，总向帝城期。"]},{"t":"送关甫田","f":"五言律诗","c":["惜我南归日，怜君北渡时。","乱离家渐远，辛苦路多岐。","味道全探古，论文可设帷。","八方驰羽檄，努力佐相知。"]},{"t":"予二次入金陵礼塔俱从燕台南归心力折于风尘行踪挠于鼎沸不叹缘悭乃讼福薄偶为口占此不觉难吞之声","f":"五言律诗","c":["廿载重过此，香花礼塔前。","风尘孤影倦，星月瑞光悬。","衣染琉璃滑，人多梵呗圆。","撑持无胜福，暗泪愧诸天。"]},{"t":"甲寅春二月与蜜在慧均四藏自显超汉铁关洞开瓶出法敌不息漪文始十靖一挂云诸子从燕台南归取道泰安登岱岳所经胜槩矢口咏歌共得五言近体十二章以志一时 其一 上横冈","f":"五言律诗","c":["百灵开岱岳，万里到孤心。","玉蝶藏青霭，金函閟碧岑。","纡回秦径古，想像翠华深。","谁道升平日，封禅不可寻。"]},{"t":"甲寅春二月与蜜在慧均四藏自显超汉铁关洞开瓶出法敌不息漪文始十靖一挂云诸子从燕台南归取道泰安登岱岳所经胜槩矢口咏歌共得五言近体十二章以志一时 其二 上红门","f":"五言律诗","c":["绿影云俱远，红门路始通。","精神难透石，衣袂易呼风。","峡月疑流雪，山霞似坠虹。","廿年登岱意，却值乱离中。"]},{"t":"甲寅春二月与蜜在慧均四藏自显超汉铁关洞开瓶出法敌不息漪文始十靖一挂云诸子从燕台南归取道泰安登岱岳所经胜槩矢口咏歌共得五言近体十二章以志一时 其三 万仙楼","f":"五言律诗","c":["众岭群争削，巍楼插独高。","自然留鹤驭，从此有松涛。","海色浮星汉，天心损羽毛。","往来一万里，金骨为谁劳。"]},{"t":"甲寅春二月与蜜在慧均四藏自显超汉铁关洞开瓶出法敌不息漪文始十靖一挂云诸子从燕台南归取道泰安登岱岳所经胜槩矢口咏歌共得五言近体十二章以志一时 其四 晒红石","f":"五言律诗","c":["地拔云中磴，螺旋屋里湾。","登临情未易，归客路方难。","残雪犹吞岳，寒风只在山。","低头见梁父，应接未能閒。"]},{"t":"甲寅春二月与蜜在慧均四藏自显超汉铁关洞开瓶出法敌不息漪文始十靖一挂云诸子从燕台南归取道泰安登岱岳所经胜槩矢口咏歌共得五言近体十二章以志一时 其五 大夫松松下为御帐崖其色碧绿","f":"五言律诗","c":["松径开秦代，崖名踰汉时。","风声红日急，石骨绿云滋。","未破洪濛气，谁知天地私。","烽烟惊大陆，悽折到京畿。"]},{"t":"甲寅春二月与蜜在慧均四藏自显超汉铁关洞开瓶出法敌不息漪文始十靖一挂云诸子从燕台南归取道泰安登岱岳所经胜槩矢口咏歌共得五言近体十二章以志一时 其六 七十二君封禅辇路","f":"五言律诗","c":["电划青徐小，烟浮洙泗低。","虞巡标石纪，秦树听猿啼。","辇路埋金匣，新情鍊木鸡。","几多兴慨意，不敢漫留题。"]},{"t":"甲寅春二月与蜜在慧均四藏自显超汉铁关洞开瓶出法敌不息漪文始十靖一挂云诸子从燕台南归取道泰安登岱岳所经胜槩矢口咏歌共得五言近体十二章以志一时 其七 二虎庙望南天门","f":"五言律诗","c":["天门真万丈，城郭已千重。","别界开灵府，高居见岱宗。","日光低午照，云影乱诸峰。","努力排修翮，琅琅玉阙钟。"]},{"t":"甲寅春二月与蜜在慧均四藏自显超汉铁关洞开瓶出法敌不息漪文始十靖一挂云诸子从燕台南归取道泰安登岱岳所经胜槩矢口咏歌共得五言近体十二章以志一时 其八 孔子小天下处","f":"五言律诗","c":["夫子原尊鲁，登兹意转深。","野龙偏斗血，炉火自销金。","日色旁虹珥，松根满枳林。","凭谁通帝座，洞达万方心。"]},{"t":"甲寅春二月与蜜在慧均四藏自显超汉铁关洞开瓶出法敌不息漪文始十靖一挂云诸子从燕台南归取道泰安登岱岳所经胜槩矢口咏歌共得五言近体十二章以志一时 其九 登封台绝顶","f":"五言律诗","c":["王者不贵力，秦皇御辇来。","未观东海日，先上登封台。","琢石难留字，祈天未遏灾。","万年私大业，无计堕奸回。"]},{"t":"甲寅春二月与蜜在慧均四藏自显超汉铁关洞开瓶出法敌不息漪文始十靖一挂云诸子从燕台南归取道泰安登岱岳所经胜槩矢口咏歌共得五言近体十二章以志一时 其十 回马崖","f":"五言律诗","c":["无地堪容马，朝天只御风。","石形千处险，肉质几人工。","鸟道明如线，篮舆曲作弓。","从兹分上下，荒忽入洪濛。"]},{"t":"甲寅春二月与蜜在慧均四藏自显超汉铁关洞开瓶出法敌不息漪文始十靖一挂云诸子从燕台南归取道泰安登岱岳所经胜槩矢口咏歌共得五言近体十二章以志一时 其十一 玉皇阁","f":"五言律诗","c":["阁道双龙口，箱空俯泬寥。","路斜千虑失，山正百灵朝。","鱼贯联鸠杖，星躔合斗杓。","金台辛苦意，全向此中消。"]},{"t":"甲寅春二月与蜜在慧均四藏自显超汉铁关洞开瓶出法敌不息漪文始十靖一挂云诸子从燕台南归取道泰安登岱岳所经胜槩矢口咏歌共得五言近体十二章以志一时 其十二 顶庙","f":"五言律诗","c":["沙过灵旗闪，风行铁瓦飞。","鬼神司石窦，星月泊僧衣。","五色炫凡界，孤光洞帝畿。","龙鳞筛沆瀣，香雾十重围。"]},{"t":"送黄迂父明府之任故城","f":"五言律诗","c":["艰虞行万里，叱驭过王遵。","正值烽烟日，能敷冰雪春。","仙云依树色，暑气动征尘。","供役虽旁午，君才却胜人。"]},{"t":"甲寅秋予以乞经从燕台南归留滞白门顿弟在吴门专侍至之住数日去陵阳订其复至白首天涯易散难聚不已之情未欲遽远且天老人住山无力世乱难安相与共依座下此什送之并似六康居士念予亦一编户民也 其一","f":"五言律诗","c":["暂问陵阳路，冬初复待君。","青山同学道，白首惜离群。","将母心先拙，扶师力欲分。","干戈看鼎沸，俱是异乡人。"]},{"t":"甲寅秋予以乞经从燕台南归留滞白门顿弟在吴门专侍至之住数日去陵阳订其复至白首天涯易散难聚不已之情未欲遽远且天老人住山无力世乱难安相与共依座下此什送之并似六康居士念予亦一编户民也 其二","f":"五言律诗","c":["江影摇孤锡，峰阴载一船。","贫穷悲孝子，流落见烽烟。","路向鸰原合，情还雁翅连。","花城询长者，相望欲潸然。"]},{"t":"在江宁送姚德超归韩江","f":"五言律诗","c":["风雪与干戈，天涯可奈何。","能归真壮勇，留滞悔蹉跎。","乡梦愁偏起，山程僻易讹。","从来相送意，不及此时多。"]},{"t":"乙卯五月素敷谒选赴都相晤于九成台畔四十字赠行相喜相勉之私非四十字能尽然素敷随事躬省栽培德行虽得时向荣以慰北堂之欢又能端悫克慎不堕青云之志只在回光返照中耳","f":"五言律诗","c":["道结莲花社，情连中表亲。","有才堪入世，期汝岂同人。","捧檄原高志，求官莫为贫。","诗书敦至德，努力扇清芬。"]},{"t":"送熊嘉会别驾还毗陵","f":"五言律诗","c":["转输三十万，湖海满干戈。","大略如君少，危涂此日多。","捲帘开净户，扫榻倚藤萝。","玉友相期意，临风惜去波。"]},{"t":"挂榜山 其一","f":"五言律诗","c":["久薄功名世，频过挂榜山。","谋身千虑少，息念一生閒。","草木居原好，荣华事可删。","纵摅王佐略，岂救鬓毛斑。"]},{"t":"挂榜山 其二","f":"五言律诗","c":["未须誇小草，谷口有真人。","月照三台丽，花明五岳春。","台莱诗可诵，龙虎气犹新。","谁共芒鞋上，低看万汇尘。"]},{"t":"泊始兴城下 其一","f":"五言律诗","c":["维舟当古渡，依荫卧清流。","伐木无佳友，抡材结石楼。","几年挥汗倦，三伏岂知愁。","病骨炎蒸里，乾坤信自浮。"]},{"t":"泊始兴城下 其二","f":"五言律诗","c":["却别金陵寺，兰桡亦未停。","钵添韶石米，月照始兴城。","水过民居折，山围粤国清。","夜凉无一事，沙上散閒情。"]},{"t":"泊始兴城下 其三","f":"五言律诗","c":["忽与山俱寂，方知役未宁。","敷疮消热血，读史敌炎蒸。","沙上盟寻鸟，人间乞遇兵。","从来湖海志，衰病已无成。"]},{"t":"泊始兴城下 其四","f":"五言律诗","c":["事事心皆倦，时时意自伤。","有人艰乞食，何客足谋王。","蛙井窥天小，鸿云附翼长。","吟诗惊草莱，世外任疏狂。"]},{"t":"泊始兴城下 其五","f":"五言律诗","c":["岁去浑无似，时閒亦自歌。","林间原寂寞，世上有风波。","溪浅云归树，星沉月满河。","平生胜人处，疏拙掩藤萝。"]},{"t":"泊始兴城下 其六","f":"五言律诗","c":["城角传更至，江波送月来。","天寒山戴帽，鹤宿脚生苔。","澹宕含哺性，蹁跹鼓腹材。","谋生冰雪里，依约似寒梅。"]},{"t":"泊始兴城下 其七","f":"五言律诗","c":["似类沙鸥迹，偏寻木客言。","金盘秤石马，玉斧印杉孙。","买竹供编筏，维舟且听猿。","半生营一寺，甘苦向谁论。"]},{"t":"泊始兴城下 其八","f":"五言律诗","c":["一住芙蓉驿，辛勤越二旬。","时过丹荔候，衫渍路头尘。","顾我原无似，求人只用真。","渔蓑往来处，一路拥丝纶。"]},{"t":"泊始兴城下 其九","f":"五言律诗","c":["欲雨江云暗，乘风树影凉。","心枯千种事，发变十年霜。","短梦无襟蕈，长贫愧稻粱。","去年此时节，摇落在他乡。"]},{"t":"泊始兴城下 其十","f":"五言律诗","c":["倦来恋枕簟，不觉午时过。","力是频年减，心原歇处多。","摇帆分日色，微月澹天河。","已有诛茅计，秋深定若何。"]},{"t":"泊始兴城下 其十一","f":"五言律诗","c":["木岭仍韶石，星途转乐昌。","笑看一日事，嬴得廿年忙。","山挂茶藤白，溪流杉叶黄。","云盘七里墺，剑阁斗羊肠。"]},{"t":"泊始兴城下 其十二","f":"五言律诗","c":["雨过村茅湿，更收宿雾流。","迎人当水鹤，失脚幸田畴。","山税输油子，方言杂楚讴。","疑兵兼畏盗，日午未开楼。"]},{"t":"寓净慧林","f":"五言律诗","c":["山径盘盘曲，山城叠叠深。","言开杉木岭，极费宰官心。","旅食分兵米，煎茶吸石灊。","禅栖聊挂锡，门外古榕阴。"]},{"t":"以松叶支棚纳凉 其一","f":"五言律诗","c":["未听松涛响，先邀松叶阴。","引风疑作树，助竹亦成林。","隐几能忘世，挥毫不用心。","目前粗遣去，此外岂追寻。"]},{"t":"以松叶支棚纳凉 其二","f":"五言律诗","c":["事歇心还歇，孤云自在流。","清风收白汗，红日避高楼。","聚叶喧檐鸟，投閒学水鸥。","不须生羽翰，随地有沧洲。"]},{"t":"以松叶支棚纳凉 其三","f":"五言律诗","c":["一木猿应喜，三秋暑未徂。","片时收逝魄，终岁倦艰虞。","月到阴还碎，云过气更殊。","石能供卧枕，天地足蘧庐。"]},{"t":"遇盗 其一","f":"五言律诗","c":["烽火消乡落，僧粮断月中。","有魂依草绿，无泪溅花红。","大难身经惯，浮生意久空。","坐深霖雨夜，潇洒入洪濛。"]},{"t":"遇盗 其二","f":"五言律诗","c":["白刃惊禅窟，清风扫晚烟。","长贫原至计，不死荷皇天。","冢响鸺鹠夜，魂消海蛋船。","从今更无物，即是未生前。"]},{"t":"遇盗 其三","f":"五言律诗","c":["钟鼓分明歇，香烟亦断烧。","南塘忽有兴，萧寺遂无聊。","竹径因时塞，腰支减食消。","安禅难制毒，豺虎下青霄。"]},{"t":"丁巳春喜汤惕庵道兄两贤郎贯人硕人至自闽中即别之楚","f":"五言律诗","c":["长年怀好友，不意见双珠。","离乱移乡井，辛勤结草闾。","琴书供少壮，丘壑老吾徒。","别去苍茫际，家声起大儒。"]},{"t":"怀刘焕之总戎","f":"五言律诗","c":["闻道连阳戍，重围战未休。","故人能眺啸，应得展戈矛。","义在皇天近，时危四海浮。","不知天下士，何处问金瓯。"]},{"t":"和王宪长入海幢原韵 其一","f":"五言律诗","c":["弄云过野寺，遣兴放轻舟。","坐此林间影，全窥水上沤。","身疑苏玉局，字即晋风流。","万古龙蛇势，时时舞石头。"]},{"t":"和王宪长入海幢原韵 其二","f":"五言律诗","c":["风暖沉香浦，人乘范蠡舟。","林光堪待月，心浪已无沤。","天与閒官福，江随妙墨流。","金山留带处，不及碧云头。"]},{"t":"送浔州郡司马刘康侯归中州 其一","f":"五言律诗","c":["一官真鸡筋，万里极飘蓬。","慈母故园内，妻孥异地中。","触籓心自苦，维谷路皆穷。","收拾长途泪，还高舞袖风。"]},{"t":"送浔州郡司马刘康侯归中州 其二","f":"五言律诗","c":["世乱惜相送，惊心已及微。","浔州无雁至，嵩岳有云飞。","客梦醒如醉，官符是竟非。","交情无可赠，聊为典春衣。"]},{"t":"寿汪汉翀","f":"五言律诗","c":["愿君长壮健，共阅世情非。","兵火延珠海，饥寒到翠微。","脚虽沉滞气，丹已逐云肥。","赖有蓬莱鹤，年年自在飞。"]},{"t":"送朱廉斋","f":"五言律诗","c":["世事只如此，干戈总未平。","人烟供我少，宦况爱君轻。","信步云林阔，由天祸福明。","但能忘宠辱，随处有閒情。"]},{"t":"春晴郊行 其一","f":"五言律诗","c":["暝烟初破日，宿涨未归河。","花积重岩重，人閒春事多。","鸠呼声尚湿，市远路应讹。","浩叹催双鬓，临流照逝波。"]},{"t":"春晴郊行 其二","f":"五言律诗","c":["久雨晴初好，行吟野望宽。","已知珠海阔，尚觉石门寒。","苍翠春中变，巑岏濯后看。","兴来无杖履，随意共盘桓。"]},{"t":"送李直侯","f":"五言律诗","c":["未是淹留日，应为汗漫游。","秋风过楚水，客路引吴钩。","曙色趋晨见，江声入夜流。","送君饶壮气，翘首望罗浮。"]},{"t":"送宋祥发","f":"五言律诗","c":["旧政槎江在，新情海国遥。","庆云初捧日，剑气合干霄。","行道推儒术，交情恋久要。","春风得意处，应为寄山樵。"]},{"t":"送李谦庵","f":"五言律诗","c":["坐看熊轼去，江涌月轮孤。","何事酬知己，清风望大夫。","峡雷春雨诵，台乐九成图。","穗石攀辚处，还令六邑苏。"]},{"t":"寿王凤羽大兄","f":"五言律诗","c":["松柏日以茂，趋庭意自温。","道情添肺腑，语笑重朝昏。","玉润昆冈厚，珠明合浦存。","圣贤真实义，斯世向谁言。"]},{"t":"送严鼎臣之京","f":"五言律诗","c":["海国春风早，君行及上京。","材当求圣主，学本为苍生。","写月名尤俊，闻经意更诚。","吾师归隐处，来往仗前程。"]},{"t":"唁知即","f":"五言律诗","c":["嗟汝竟长没，心肝奉至公。","魂残知水冷，兵乱忍途穷。","皮瘦蚊虻血，山围魍魉风。","空知孤志在，节烈古人同。"]},{"t":"雷峰山寮口占 其一","f":"五言律诗","c":["渐老知身累，心情日日阑。","事妨孤坐少，梦觉五更寒。","鹤语荒岗白，风鸣木叶丹。","最嫌潮与汐，不许几人看。"]},{"t":"雷峰山寮口占 其二","f":"五言律诗","c":["黄金那可铸，握手泪涟洏。","共作他生别，如看花落时。","草虫悲更切，灯影梦还痴。","静理萧萧鬓，吾行恐未迟。"]},{"t":"雷峰山寮口占 其三","f":"五言律诗","c":["大陆鸺鹠响，孤魂逐瞑烟。","百忧攻五尺，寸土陷双拳。","夜雨侵人泪，天心夺世缘。","斯人安可得，古道在林泉。"]},{"t":"雷峰山寮口占 其四","f":"五言律诗","c":["骨冷岩花好，空还旧器除。","半尘金菡萏，一镜玉蟾蜍。","地脉无风火，松声有卷舒。","瞥然孤念起，随意借吾庐。"]},{"t":"雷峰山寮口占 其五","f":"五言律诗","c":["夜壑藏舟急，天风鼓箨轻。","有刀分肺腑，无传写平生。","旧榻眠吾病，新秋送汝行。","两年伤悼意，衰飒旅魂惊。"]},{"t":"雷峰山寮口占 其六","f":"五言律诗","c":["待死心还热，原空事未消。","艰难菩萨行，辛苦病魔娇。","冷意营新塔，孤灯照药瓢。","交情那可已，哭汝向溪桥。"]},{"t":"江夜 其一","f":"五言律诗","c":["精魄融消月，重冥习夜风。","岸林千叶暗，船火五更红。","老事思量遍，閒心着意攻。","再休言建立，吾亦笑吾空。"]},{"t":"江夜 其二","f":"五言律诗","c":["总是无家客，家居亦野航。","江边知月阔，水底见星长。","林动疑豺虎，时危问稻粱。","岩能孤坐好，贫只百般忙。"]},{"t":"将米从蛋户换得鲤鱼一尾重二十斤鲇鱼一尾重三十六斤放生","f":"五言律诗","c":["方乞桃花米，先将换活鱼。","红云生锦浪，绿背拔青蕖。","万事浮生似，孤舟且慰予。","龙门他日起，风雨慎村庐。"]},{"t":"舟至胥口有鲇鱼一尾重十四斤复买放生","f":"五言律诗","c":["复解鲇鱼索，全倾乞食囊。","原无开济力，只检养心方。","水更微生得，天从覆物长。","年来衰白意，不可问沧浪。"]},{"t":"泊鸭凫水","f":"五言律诗","c":["胡为于此泊，孤舟满戒心。","艰危已如此，寇盗岂相侵。","自信疏星朗，他求浊世深。","野猿相共警，清啸有馀音。"]},{"t":"清远东林寺","f":"五言律诗","c":["清远东林寺，颓荒有岁年。","琉璃高照郭，锦绣忽铺天。","廊接飞来磴，门迎估客船。","僧徒钟磬稳，追忆太王贤。"]},{"t":"朝入清远峡","f":"五言律诗","c":["翻江朝日丽，迎水峡船摇。","草露茸茸滴，飞云淰淰飘。","事閒人意好，春急鸟声娇。","中岁从兹过，年年换寂寥。"]},{"t":"上飞来寺 其一","f":"五言律诗","c":["数日逃人外，欣无礼法拘。","披衫登古寺，赤脚看江鱼。","亭记归猿迹，门仍拒盗馀。","既看风境异，鬓际亦难如。"]},{"t":"上飞来寺 其二","f":"五言律诗","c":["石响山泉沸，台擎野果铺。","峡风刚自起，舟子急相呼。","眼挂杨朱泪，身依晋鄙符。","自由何日得，对境倍踌蹰。"]},{"t":"口占","f":"五言律诗","c":["天与孤僧便，萧萧一叶舟。","月无通夕照，人有百般求。","水鹤思量步，惊鱼造次游。","自磨吾宝镜，高挂凤麟洲。"]},{"t":"沸水方热锅为宽黔所堕行人泡足戏成","f":"五言律诗","c":["我饿方思饭，黔宽忽堕锅。","脚能供炮烙，腹极怨蹉跎。","国手调金酱，神仙爱玉禾。","两般俱未得，失意事原多。"]},{"t":"至连州江口","f":"五言律诗","c":["江口今朝至，寒风昨夜多。","宿云含石磴，断碣拜曹娥。","庙古茆茨换，时危估客和。","湟川当五岭，一路好岩阿。"]},{"t":"舟行","f":"五言律诗","c":["曲路嶙峋上，孤舟寂寞行。","峰阴存石气，篙力尽滩声。","世事为无益，生涯岂有程。","黑貂穿破处，只醉未曾醒。"]},{"t":"至麻步","f":"五言律诗","c":["石匠遗馀荫，云根拥独牢。","戒心惊虎兕，麻步见旌旄。","水急青天破，松长白鹤高。","物情徒顺适，人外复波涛。"]},{"t":"岸上摘枸杞","f":"五言律诗","c":["枸杞因吾有，舟行似少陵。","盘餐供早晚，眼力得轻清。","味觉甘辛厚，肠缘湿热鸣。","此生粗粝过，那复有馀情。"]},{"t":"宿雷公滩","f":"五言律诗","c":["深到无何有，闲心总懒提。","窗开山石入，滩宿水鸡啼。","湿气重岩断，春花夹岸齐。","山阴分接急，此路亦千蹊。"]},{"t":"阳山守阃拨夫相送念无德以当纵之自去","f":"五言律诗","c":["何忍劳人力，予生且自艰。","天风吹短鬓，山月照衰颜。","路入羊肠径，人行马面滩。","追呼到穷谷，木客几曾閒。"]},{"t":"舟行","f":"五言律诗","c":["浮久身难定，春深木尽平。","风吹岩弄笛，云到石簪缨。","水际无飞鹤，船舱足乱蝇。","谁尤雄杰气，垂老笑沧溟。"]},{"t":"望野","f":"五言律诗","c":["未可询行役，言寻好翠微。","水添江路直，帆侧峡风归。","残月波翻碎，閒鸥春浴肥。","时时惭物外，何日坐忘机。"]},{"t":"口占","f":"五言律诗","c":["草色甘衰白，天涯兴正赊。","马蹄出塞健，燕翼过江斜。","舟忆秦淮水，杯思庙后茶。","乱来成一笑，期我总无瓜。"]},{"t":"辽阳怀足两师","f":"七言律诗","c":["骨贫高卧亦添愁，噭噭啼猿长泪流。","子建文章堪载笔，仲安身世委沉浮。","云霾塞雪燕支黑，风冷江梅师子幽。","知己感恩愁欲死，吾兄曾为一筹谋。"]},{"t":"除夕和本师辛卯韵","f":"七言律诗","c":["怀师又在大关东，朔气山光一夜中。","残梦不离三峡寺，閒情偏逐五更风。","年来善病心如死，日抱寒愁道未穷。","幸喜烧冰依佛眼，灯花还与几人同。"]},{"t":"登谪仙楼有怀千山","f":"七言律诗","c":["欸乃听残客思愁，来登江上谪仙楼。","寒风直扇金陵雨，怒浪长连白鹭洲。","万里中原腾杀气，三边朔漠怨貂裘。","分明掩泣凫归日，回首茫茫又两秋。"]},{"t":"留别郑季生","f":"七言律诗","c":["城头吹角肃初寒，边客何人泪欲乾。","久历冰霜忘道远，又从离别觉情难。","传经自是诗书志，击筑须怜屠狗欢。","细想与君交匪薄，回头不是望长安。"]},{"t":"用徐秀才游百花园韵","f":"七言律诗","c":["百丈苍崖路几层，何人清啸学孙登。","松杉地阔风声急，牛斗星寒剑气腾。","冷处看山高士眼，岩前扶病野人藤。","明朝披薜凌霄去，珍重桥头护石冰。"]},{"t":"周长孺过谈灯下口占贻之","f":"七言律诗","c":["湖海飘残意转深，归来未肯息长林。","青衫拭尽新亭泪，白水难忘旧日心。","云过草堂时倚剑，鸿鸣秋浦罢弹琴。","分明不羡无生理，相对惭予乏好音。"]},{"t":"赠顾与治","f":"七言律诗","c":["唾壶敲罢已龙钟，潇洒文园一病翁。","百二河山双眼老，三生魂梦十年空。","泼残墨汁疑张旭，鍊尽丹砂想葛洪。","雪底故人相忆甚，石头先遣问秋风。"]},{"t":"陈柱江应策不第以诗慰之且言别","f":"七言律诗","c":["风流名已帝京闻，惊座陈家复见君。","自有富钩归贾客，更无贫铗向田文。","他年自展图南翮，此日谁空冀北群。","出处穷通非所慰，独怜万里恨凫分。"]},{"t":"留别即兄","f":"七言律诗","c":["哭罢穷途笑步兵，秋山病叶一身轻。","木瓢潦倒人烟饭，竹笠萧条塞雪声。","去住每怜予有恨，别离愈爱汝无情。","感公古亦怀冰者，大法依然属老成。"]},{"t":"游金粟泉","f":"七言律诗","c":["天荒谁与问柴扉，胜地寻幽又着衣。","开阁不因生客至，探泉何必主人归。","水当澄彻方消暑，心得清凉是息机。","千古从来多好事，苏公祠有缕烟微。"]},{"t":"赠魏和公","f":"七言律诗","c":["天涯倾盖乐何如，况复神交三载馀。","说剑崆峒跨斗气，摛文禹穴得新诗。","风流久托寰中赏，磊落曾寻物外庐。","击筑高歌弹铗好，王门原可曳长裾。"]},{"t":"子夜诗 其一","f":"七言律诗","c":["皑皑孤城月照人，角吹一夜起烟尘。","廿年将帅恩非薄，百队貔貅气欲伸。","马踏官街惊睡犬，刀临屋角泣灵神。","黄金死士君闻否，方信冯驩用处真。"]},{"t":"子夜诗 其二","f":"七言律诗","c":["街南街北尽喧声，黑纛城头绕月行。","炮火惊心先入耳，犀纹坚甲耀新兵。","明明大将星辰坠，寂寂银河杀气升。","谁念客游当此际，此情惟有道能胜。"]},{"t":"子夜诗 其三","f":"七言律诗","c":["闻道量沙是阿瞒，令人特地忆芳魂。","枭雄窃国虽无取，庙算成功亦足论。","珠玉卫生非在朴，生灵有泪直须吞。","可怜踏尽青青草，愁杀王孙望海门。"]},{"t":"子夜诗 其四","f":"七言律诗","c":["斗印黄金掌上悬，将军自有出机先。","九头猬结终成暴，三略环才实仗贤。","旆转星边光欲没，风临泽上德应全。","忘怀我可随时劫，只为生民一怆然。"]},{"t":"子夜诗 其五","f":"七言律诗","c":["已成垂蹇到琼南，况复刀兵劫正酣。","酸鼻霜戈公豕突，愁人壮岁失鸡谈。","折冲不用追风马，弭祸无过白玉簪。","若是王明今广烛，天威咫尺或能严。"]},{"t":"子夜诗 其六","f":"七言律诗","c":["戒旦鸡声动远空，企予东望海云红。","惊魂稍定三更后，芳饵争传十月中。","螺角正停皆秣马，炮声才动尽弯弓。","入云帅府辕门壮，鱼烂愁看一霎风。"]},{"t":"举稚鸡","f":"七言律诗","c":["坠羽虚弯怯未伸，相怜此际觉情真。","回看六日悲同汝，幸得馀生复仗人。","日料且分檀越米，年光难逐老僧春。","处宗未必长为吏，禅几吟窗可话频。"]},{"t":"宿冯孝廉载赓敏来斋斋中植鸡冠花数本一茎径可尺馀诸公同赋限红字","f":"七言律诗","c":["曾祀梁州色未工，移为窗下接谈丛。","司晨既已惭嘉号，斗月犹能散舞氃。","幸比灵芝于我小，竟誇梅瓣不能红。","人间拟物当其似，堪笑人间尽拟中。"]},{"t":"伏波祠","f":"七言律诗","c":["名祠衰草引颓垣，禹贡河山绝此峦。","忆别楼船悲海气，看来铜柱泣王孙。","朝廷版籍黎村渺，天地浮生马革存。","千载英魂余欲奠，蘋蘩无力荐平原。"]},{"t":"钟秀才秉三以奇楠香坠赠别诗以谢","f":"七言律诗","c":["珊瑚风急岛门秋，握手论交笑便投。","玄理共君看鸭脚，名香赠我过牛头。","蛮中土物南方贵，海国朋情世外留。","每到溪桥三伏际，素纨摇曳想风流。"]},{"t":"喻耕三夜访宿茅亭","f":"七言律诗","c":["海门游宦足高才，觞饮沧溟气壮哉。","说剑盛传扪虱久，谈玄终喜带星来。","青莲有法那堪比，白眼无心各自开。","世事欲冷身欲老，竹床期尔到千回。"]},{"t":"寿谭兑子且言别","f":"七言律诗","c":["一杯秋露为君寿，寿君十日便辞君。","笑谈胜结东林社，笔札堪传北地云。","綵服好将供白发，青衫莫更负鸿文。","论交最是初相识，握别桥头畏夕曛。"]},{"t":"别赵庭宜","f":"七言律诗","c":["赋残穷鸟泪如麻，胜事回看日欲斜。","岛上青山非赵土，津前桃叶少秦家。","难将远恨频窥鬓，已是无园好种瓜。","握别赠言原我事，愿君努力向烟霞。"]},{"t":"琼州留别巳虚","f":"七言律诗","c":["非君爱我不能来，此日分襟尽日哀。","两地秋风悲旅雁，百年身世付高台。","波声寂寞摇孤舫，野寺萧条罢茗杯。","骨肉渐深兄弟谊，度人几载便应回。"]},{"t":"次韵答周鹤田 其一","f":"七言律诗","c":["珠海霜飘叶未红，柴门揖客得高风。","早传封事神州内，竟接鸿词白雪中。","笑语性应归上乘，须眉气自可凌空。","他年九带台边月，千载香花愿与同。"]},{"t":"次韵答周鹤田 其二","f":"七言律诗","c":["书归金马道仍西，弃却银鱼世罕齐。","镇海珠谁徒手得，摩天鹤不共鸡栖。","摧残智勇留盘谷，开拓心胸选钓溪。","莫遣秋霜攻玉质，莲华相待踏琉璃。"]},{"t":"送吴百子归琼海","f":"七言律诗","c":["相见先嗟失意殊，文章原自胜隋珠。","三年辛苦二千里，万虑消归一字无。","桂魄有心圆不彻，秋风何意冷还孤。","忙忙未尽寒山话，寂寞琴书上客途。"]},{"t":"送诸子下第还琼海","f":"七言律诗","c":["摇落先悲秋气凄，谁怜剑锷擅铜溪。","溟南有翼羞羊角，冀北无群笑马蹄。","苦竹渡头椰酒冷，阳春山下黑猿啼。","重逢讲彻无生话，客里清歌试一提。"]},{"t":"梁赓人秋捷","f":"七言律诗","c":["秋风羽翰识南图，独化沧溟道未孤。","一代文能凌白雪，三州人羡得骊珠。","笑拈綵笔飞金屑，静指冰轮对玉壶。","况是少年多逸兴，明春花影满皇都。"]},{"t":"文人赓人卿人三昆玉赴秋闱赓人先捷二公南归此赠","f":"七言律诗","c":["白眉已见号贤良，兄弟双难孰可当。","先喜家声高建水，旋嗟逸足失孙阳。","极明霜月悬愁乐，如许归途有短长。","好悟木樨真实义，重来赠汝一枝香。"]},{"t":"寿杨天衢","f":"七言律诗","c":["盖州城下涌千峰，猿臂今看受气雄。","红旆惯驱龙虎阵，白星长耀斗牛宫。","閒持旧竹量觞酒，静对深堂捲画筒。","道意百年还是少，祝君声已彻鸿濛。"]},{"t":"送陆康侯还琼山","f":"七言律诗","c":["邻庵尚忆夜谈时，已识豪华气自奇。","为吏不须哀漂母，轻身原许学要离。","寒山有梦劳千日，客舍无愁畅万卮。","别去倘思吾道好，灯光还照碧琉璃。"]},{"t":"壬寅春扫先师翁塔 其一","f":"七言律诗","c":["江门觅路拜高岑，瞻仰嵯峨春暮阴。","溪雨欲来山气歛，泉台长掩法源深。","烟开孤白啼归鹤，土酿新红出远林。","旧日绕床孙渐老，一盘荼味荐微忱。"]},{"t":"壬寅春扫先师翁塔 其二","f":"七言律诗","c":["去年浮海上辞书，回首风烟几日馀。","芳草无情空满地，浮云有泪独沾裾。","山光十里银盛雪，泉影千年井觑驴。","便拟种松三万本，青青长荫祖庭迂。"]},{"t":"谢柱波招游厓门","f":"七言律诗","c":["欲吊沧茫一问津，楼船何必起征尘。","乌衣旧姓能招客，白社新寻得故人。","细草绿初厓尚冷，洪波碧尽海难春。","灯前莫欣兴亡事，更有何源可避秦。"]},{"t":"厓门感赋 其一","f":"七言律诗","c":["孤舟又向海门过，旧事厓山感慨多。","三十已怜添白发，千秋谁与泣铜驼。","云埋断碣迂黄土，树掩离宫长绿罗。","自古兴亡终若此，不须弹泪落沧波。"]},{"t":"厓门感赋 其二","f":"七言律诗","c":["当时十万尽沉尸，幼主孤臣异代悲。","身世到今都是幻，江山终古不曾移。","双厓浪打高陵草，万木风摇失古祠。","忠义果能移国祚，夕阳斜照有残碑。"]},{"t":"宿厓门","f":"七言律诗","c":["又随鹢首下云端，柔橹轻风破急湍。","月色每因浮海得，松声依旧故宫寒。","五年尚忆长陵役，万里还当大宋看。","此意莫教今夜梦，慈元原不是长安。"]},{"t":"拜三忠祠","f":"七言律诗","c":["穷厓极海拜名祠，万古山河又一时。","波浪独深臣子泪，死生惟有老僧知。","鱼龙国冷人如梦，乌鹊枝危月亦悲。","最是不堪投吊草，乾坤若个哭男儿。"]},{"t":"寿大云监院睹者五十一","f":"七言律诗","c":["大云谁复振颓纲，赖有杨岐为播扬。","入社里人欣后起，翻经山日爱初长。","廊迂影过菩提绿，殿古光回画栋黄。","已是护明今降此，看君岁岁礼慈光。"]},{"t":"贺雷峰新监院见公","f":"七言律诗","c":["斑髻怡怡笑口开，无边功德鼻收来。","牛头八百堪担米，云盖千年亦拨灰。","且把金针藏绣带，好敲银盌闹香台。","六衢赤脚同辛苦，梦到江城是几回。"]},{"t":"刘昆玉从关中来觅其伯祖同庵客生遗榇因得皈予座下别归诗以送之","f":"七言律诗","c":["梦蝶幽人骨久寒，流离谁复哭云端。","能来海角真痴绝，复典春衫识路难。","佛种有缘终莫断，世间如幻好平观。","送行赠汝真三昧，百八轮珠万里安。"]},{"t":"寄答足两","f":"七言律诗","c":["车声才歇接离缄，旧绪新愁两不堪。","添钵三秋怜海外，驮经万里忆江南。","芳菲药碗闻初覆，妙密鸿词且莫参。","匡阜易深漂麦僻，好开怀抱笑高杉。"]},{"t":"送程大匡归庐陵","f":"七言律诗","c":["故园松竹经年别，两粤风烟此日归。","幸不遇人知己在，竟无好梦与心违。","云开庾岭梅花小，风落章江朔雪微。","喂犊负薪无不可，牢骚一滴莫沾衣。"]},{"t":"寿丘太史曙戒","f":"七言律诗","c":["玉斗频斟琥珀浓，青峰常在白云中。","仙人此日三山集，寿域他年万国同。","五凤楼前文似锦，千金亭下气如虹。","钵池自洗黄乔鼎，不作留侯望赤松。"]},{"t":"答陈蕉源见赠","f":"七言律诗","c":["舌底谈锋欲吐莲，陈遵真在五云边。","苍梧已见劳轺驾，祇树今思借法船。","扪虱自高湖海气，寻僧日结竹林缘。","愧将下里酬居士，打地元来错会禅。"]},{"t":"寿彭明府退庵","f":"七言律诗","c":["清波百道蜀江来，仙气浮丘瘴疠开。","载酒黎元歌九穗，专城星象入三台。","行当下凤应褒德，未见全牛可试才。","我愧袈裟叨大护，流霞愿祝万年杯。"]},{"t":"甲辰春日赠雄州太守孝山","f":"七言律诗","c":["搴帷百里颂贤明，锁钥雄关德泽馨。","纶綍恩光三殿下，梅花閒梦十年清。","青门望在朝端重，白社论心世虑轻。","早晚借君临十部，江威先拥玉麟行。"]},{"t":"寿李参戎衷纯","f":"七言律诗","c":["海屋添筹动地声，金风瑟瑟满仙城。","堂悬宝剑霜威闪，座拥文章墨气清。","已见鬓毛追尚父，更看燕颔是星精。","山林也感将军谊，为祝寒松百代荣。"]},{"t":"丘太史曙戒同汪汉翀周鹤田见过王伯子亦忽至自琼州喜赋","f":"七言律诗","c":["春波明媚捧仙舠，猎猎摩空鹤盖摇。","圭组情深怜物外，鹿麋步懒愧高霄。","座中惊散阳春调，钵底盛多白玉瑶。","更喜琼南王大令，双凫如鹤到偏遥。"]},{"t":"王伯子渡海相见有赠用韵却酬","f":"七言律诗","c":["花事春风两未阑，交情如子许相关。","音书计日来深岛，车马何期到此间。","客路看来欣已半，吏情归去不须删。","他时考绩封褒德，笑我浮云在好山。"]},{"t":"次韵答沈融谷 其一","f":"七言律诗","c":["一见欣君慧业深，蛩然慰我在长林。","百年天地春风老，几日韶华雪鬓侵。","蝴蝶梦来看逝水，莲花悟后识秋阴。","分明宝髻云中近，遮莫腾腾自古今。"]},{"t":"次韵答沈融谷 其二","f":"七言律诗","c":["语罢如经雪里行，相期先有道人情。","圆伊自可成三点，烟水无劳越百城。","圭组不忻身外重，嵩华自入眼尘轻。","郊居已是君能赋，犹恨前人有此名。"]},{"t":"次韵答沈融谷 其三","f":"七言律诗","c":["花气阴阴午磬传，拖鞋结得虎溪缘。","弟兄爱我遗良友，水石怀人对晚烟。","此去岭头成往事，望来雁足在何年。","殷勤写得无生偈，宝鉴为君日夜悬。"]},{"t":"诃衍弟以甲辰浴佛日受老人付授志喜","f":"七言律诗","c":["三十年前早诞生，指天今又属罗云。","击开寺竹原龙种，呼起神鹞突洞云。","内绍步移非干蛊，再参智过始超群。","船头愧杀秕糠我，东去西之暂任君。"]},{"t":"送黎太守天锡归皖山","f":"七言律诗","c":["薰风吹浪锦帆高，柳色青青意独劳。","十载风猷思阖郡，一江云影揖千袍。","丰碑自可磨铜柱，宦况还当爱凤毛。","我欲托君栖隐地，匡庐深壑卧烟涛。"]},{"t":"送陈扶上之任靖安","f":"七言律诗","c":["绣佛龛前语话勤，天涯宦况此离群。","河阳树色堪为政，单父琴声又属君。","雪满秋屏驯雉下，月高南海夜鸿闻。","端明不次承前箸，为把名香着意焚。"]},{"t":"送徐进士元定归南昌","f":"七言律诗","c":["南州声价喜相投，几日旋惊送早秋。","岂为明珠游海上，终宜大道在峰头。","旌弓行见招金马，星斗频看照玉楼。","我挹粤云思共语，綵笺何处寄风流。"]},{"t":"送潘星北参戎之高凉因怀高文斗喻耕三","f":"七言律诗","c":["世雄廉正擢应频，三十登坛识冠军。","铜柱弯弓无杀气，东瓯横海有功勋。","心存仁术悬神剑，道慕金仙爱白云。","杯酒玉堂多友兴，磬声忆我独离群。"]},{"t":"寿徐允吉","f":"七言律诗","c":["种莲先许入高岑，天上麒麟复见今。","起草参军多茂句，谈经仆射有清音。","玉堂未散云成色，宝地长看月满林。","况是金吾霜鬓好，称觞真慰百年心。"]},{"t":"乙巳三月石弟病愈入栖贤诗再送之","f":"七言律诗","c":["又买江头上水船，春风逐日岸花鲜。","才抛药盌身誇健，为爱名山力便全。","荒草久嗟迷古砌，镰刀新刃让先鞭。","岭南首刹成何用，岂及山中橹断泉。"]},{"t":"戏成寄记汝","f":"七言律诗","c":["玉兰花落满溪桥，已住高峰见雪消。","破院自忙供补葺，好诗未暇静歌谣。","田因入夏烧灰种，人为思乡说理调。","莫上芙蓉峰上望，岭南端的是迢迢。"]},{"t":"宿半息轩酬半息主人","f":"七言律诗","c":["绳床携得挂高斋，却喜幽情对妙才。","水石忽疑城内有，笑谈如入镜中来。","风侵碧树枝频出，雨暗银缸影或开。","才一渡江心便忆，如波千顷正徘徊。"]},{"t":"寄寿罗母","f":"七言律诗","c":["横斜星斗灿长天，髣髴瑶池宴列仙。","汉苑鸾曾邀紫辇，罗家鹤又降青田。","催觞频奏军中乐，舞綵还连海上船。","碧玉花开香未散，月光如昼日如年。"]},{"t":"寿杨太守肃如","f":"七言律诗","c":["应身大士福人间，建隼专城布政閒。","芳誉独多蘅杜气，清操还过雪霜颜。","已看瑞色临铜柱，会见祥云捧玉班。","文藻长河吾欲赠，不胜幽思对南山。"]},{"t":"送管使君钟石赴任泷水","f":"七言律诗","c":["崇兰喜见别嫌频，洒落仙姿独羡君。","万里粤云供薄宦，几年雷泽著清芬。","鬓毛易比潘安色，心地还超许掾群。","泷水政成当内召，便从今日卜高旻。"]},{"t":"寿苏盐宪商卿","f":"七言律诗","c":["云开五色下霓裳，地近三山载鹤觞。","北斗独垂新雨露，眉山重见昔文章。","冰壶易贮丹砂气，玉尺应传琥珀香。","更觉风流忘草野，欲留腰带镇茅堂。"]},{"t":"沈醝使石友过访","f":"七言律诗","c":["不曾叩齿接文公，已透清言宝镜中。","玉佩久悬台鼎望，金貂偏惬芰荷风。","佛分别业禅尤好，道叹王门瑟未工。","卧理淮南人诵屈，他年宣室古今同。"]},{"t":"王方之出家喜赠","f":"七言律诗","c":["镆铘又作一筹添，玉海雷轰待雨沾。","閦老凤头高自插，侍郎鸡舌夜还拈。","风生静见头陀月，世冷深垂大布帘。","莫学衢头痴架屋，千峰期尽脱廉纤。"]},{"t":"卧月 其一","f":"七言律诗","c":["齁齁深入海天宽，露暗霜滋一衲单。","树底烟生浮卫瓘，门前雪满见袁安。","驼经马老鞭无力，弹鹊珠圆拾亦难。","玉版牙床吾自有，祇愁钟动日初还。"]},{"t":"卧月 其二","f":"七言律诗","c":["华山我亦羡希夷，却笑山公带接篱。","鹤背霜添寒自惯，吴门练过梦先知。","艰难普化摇铃日，潦倒神光断臂时。","一色边中如放去，钝根犹觉九峰迟。"]},{"t":"寿杨明府汝邻","f":"七言律诗","c":["羊角神鲲化独隆，弹琴天上奏尧风。","八方眼见祥云起，百里人歌寿域中。","清水沅湘流自远，灵椿日月对无穷。","大年本是云间侣，便拟寻君上客艟。"]},{"t":"寿吕明府宸铭","f":"七言律诗","c":["东山遥望起烟涛，斗气泷声一并高。","黄菊偏宜今日酒，紫云先兆昔年刀。","栽成桐树栖鸾翼，煮老丹砂变鹤毛。","更省俸钱供布地，绀宫长此祝僧袍。"]},{"t":"送张游戎明甫之任镇平","f":"七言律诗","c":["十年琼海声名旧，此日潮阳甲胄新。","聚米岂须饶胜算，慈心到处有深春。","江云拥日唯驱水，山路行时不起尘。","五载别来燕颔改，故人情意感君真。"]},{"t":"寿刘太守瑞堂","f":"七言律诗","c":["爱人冬日影离披，两见搴帷慰去思。","芳颂喜逢长至候，祥光先结早春时。","星辰南极推高步，佳气蓬莱入酒卮。","更有閒僧云际祝，此心无尽寿无期。"]},{"t":"黄扶升陶昭美苏式容何玉琪过访次韵奉答","f":"七言律诗","c":["不厌拖鞋礼数疏，江干长得接高车。","经多乱世应探道，阅尽时人莫读书。","白发可堪频过雁，黄尘何事苦乘驴。","山中无限清凉地，岂独田田几叶蕖。"]},{"t":"罗学制镇守凤城","f":"七言律诗","c":["旌旗移镇插云霄，百道长虹起赤标。","探胜日登飞凤岭，按营时过伏波桥。","文心尚忆金坛月，将气行簪汉代貂。","独有老僧閒自寂，思君难把磬声招。"]},{"t":"寿涂司李万年","f":"七言律诗","c":["寿昌曾见礼王臣，此日祥刑有瑞人。","鹤语喜逢椒酒熟，棠高又长海门春。","云深粤甸宜霜露，道寄难时识圣神。","咫尺祇园叨庇护，琅琅金磬彻江津。"]},{"t":"寿高图麟郡司马","f":"七言律诗","c":["又从浮磬识祥光，政绩如今五岭长。","海上蜃楼消幻气，天边玉简记循良。","平刑声彻梅花洞，刺割风行锦石乡。","最好常邀司马步，白莲池畔话幽香。"]},{"t":"尹乔岳入泮宫","f":"七言律诗","c":["翩翩五色应弘词，初入圜桥雀已驰。","藜火夜分天禄阁，彩毛朝起凤凰池。","奏笺预向趋庭日，华选方逢盛世知。","更有寒山樨一树，秋风遥欲与君期。"]},{"t":"有送黑白鹇予号之日黑忙","f":"七言律诗","c":["金毛孔雀锦毛狮，总不如他岂是奇。","十上衣裳看已敝，一腔心事倩谁知。","餐沙尚省香台米，入树嫌伤映月枝。","好待十年无事际，花间看尔日斜时。"]},{"t":"红叶 其一","f":"七言律诗","c":["一夜秋风涷碧岑，凭栏寂寂怯寒襟。","儿啼欲止非同色，霜落犹看费独吟。","横字楞严曾剌股，食砂蝙蝠自归林。","高廊莫扫烧寒灶，恐有閒僧后夜寻。"]},{"t":"红叶 其二","f":"七言律诗","c":["春花百种斗幽奇，彼此丰姿又一时。","雪底怀人堪写句，月中对我忽辞枝。","竹斑自滴双娥泪，舌在还教六国知。","莫使随风投赤水，神珠原自护蛟螭。"]},{"t":"次韵酬刘侍御峡石","f":"七言律诗","c":["香花重结若为凭，一笑西江万派澄。","玉带可能留学士，瑶篇先已起閒僧。","迎风宝铎高三步，照字摩尼透一层。","尘刹悲欢君自得，长沙宣室果何曾。"]},{"t":"赠杨澹公","f":"七言律诗","c":["泷水僧归感叹多，几回风雨想经过。","双凫尚识神明宰，一策难逢春梦婆。","旅次有才堪笑傲，官街无路入藤萝。","分明隔水同君语，招手何年始会他。"]},{"t":"夏日刘峡石侍御杨肃如太守高图麟郡丞郑锡之别驾朱说梅明府相过刘侍御有作奉和原韵","f":"七言律诗","c":["阑干萧寺倩谁凭，喜见沧溟入眼澄。","夏里开襟先傍水，竹间留客亦宜僧。","风侵梵磬成三奏，雨着新潮涨一层。","为问群公行乐意，从来退食似还曾。"]},{"t":"和黎似仲灼霞亭 其一","f":"七言律诗","c":["因心千古在名亭，此道何人共倚棂。","芳树绿深疑洒血，长天白尽感寒星。","香绡易剥蒸龙脑，冷露难禁怯鹤形。","最喜健儿归手泽，依然夕膳荐馀馨。"]},{"t":"和黎似仲灼霞亭 其二","f":"七言律诗","c":["久从绿水想朱亭，月挂枝头树挂棂。","风静几人闻过雁，光寒惟尔见飞星。","能消笋味先冬日，自舞衫尘慰旧形。","我亦依依云影下，感君纯德爱芳馨。"]},{"t":"唐世永秋捷","f":"七言律诗","c":["相期真觉似能成，动地朱弦发妙声。","向去尚多云外意，从今难避世间名。","昆崙觅路天河近，象阙抡才禁月清。","我着袈裟浑欲老，伫君麟阁护文星。"]},{"t":"黎似仲秋捷","f":"七言律诗","c":["南溟奋翼是冲霄，上苑春红历乱飘。","几世书声添巨笔，千秋文字副当朝。","白华诗向霞亭熟，紫色云从玉阙饶。","最是罗浮高见日，喜君衣履御仙飙。"]},{"t":"寿诗","f":"七言律诗","c":["双旌曾冠水犀雄，久向琅琊识巨工。","宝剑暗笼关塞雪，玉堂高捲海天风。","珊瑚鞭马趋铜柱，锦绣成云映綵虹。","千古声光钱尚父，又疑花下与君逢。"]},{"t":"送赵雨三太守","f":"七言律诗","c":["又携琴鹤返中州，德泽曹溪水并流。","烟起相江思父老，花寒庾岭照仙裘。","高飞神雀名偏好，独悟泥牛道更优。","他日重繁君卧理，孤筇随处访沙鸥。"]},{"t":"寄怀杨汝邻明府","f":"七言律诗","c":["相见何须识姓名，居然到处水云清。","竹间风起僧犹语，池上莲开月正明。","银印栽花心自寂，玉壶作宦眼原轻。","此心一向怀君好，塞雁寒烟隔一城。"]},{"t":"寿万肃庵宪使","f":"七言律诗","c":["椒酒长斟此日新，楚江云起粤城春。","气吞旸谷能窥日，手握阳和解袭人。","雾散海门无鳄渚，星寒瑞色有龙津。","三山老鹤群飞处，同向浮丘作诵民。"]},{"t":"本师天老人入丹霞寄示一律依韵恭答二章 其一","f":"七言律诗","c":["未得随师集雁班，喜闻安乐住青山。","白云万里归平陆，紫气千层护上关。","匹练且扶悬磴直，一身敢爱避人间。","明年一幅镰刀颂，持献峰头慰道颜。"]},{"t":"本师天老人入丹霞寄示一律依韵恭答二章 其二","f":"七言律诗","c":["登临旷见御仙班，亲到方知大好山。","枚乘笔头劳七发，南公脚下起三关。","吟诗僧听泉岩响，阅世人谁几日閒。","顽子尘劳师莫念，自将白发护颓颜。"]},{"t":"送江若海北归","f":"七言律诗","c":["百粤风烟陆贾游，风流那似此归舟。","高名万里燕台月，客路三春白下楼。","解事鲁连还负气，重言季布自堪俦。","知君无限沧洲兴，目送仙帆意独留。"]},{"t":"双寿","f":"七言律诗","c":["银海沧波剩几寻，蓬莱云气足萧森。","穿衫已爱群鸾翼，举案还同百岁心。","松柏并高春色密，雪霜齐照月华深。","只今谁献中和颂，连理枝生在碧岑。"]},{"t":"答陈羽王郡丞","f":"七言律诗","c":["邂逅相投日未收，风尘宦海见林丘。","十年佩印存青眼，一夕逢僧话白头。","听冷江波难入梦，搜穷诗句是真游。","自然尚有披襟处，珍重琴书入帝州。"]},{"t":"赠李定夫","f":"七言律诗","c":["三年草草别离中，两地茫茫别绪同。","城角暮云堪着地，天涯高兴忽凌空。","多情老友能相向，阅世新诗自易工。","此别车尘飘十丈，磬声又隔海门东。"]},{"t":"送高文斗景侯昆仲随尊人总戎归籍汉阳","f":"七言律诗","c":["汉阳此去匪专城，戴得皇恩带砺荣。","庾岭月圆秋扇冷，洞庭风急舞衣轻。","人间何处寻双璧，今日分明见弟兄。","无数旌旗珠水上，与君同有别离情。"]},{"t":"送陈子厚子文昆玉扶其尊人姜亦先生灵榇归海昌","f":"七言律诗","c":["伤心君已泪无乾，况复天涯雨雪残。","万里灵輀归雁暗，千秋遗稿蠹鱼寒。","风流叹惜无先达，辛苦今看有二难。","却望珠江江上水，居然愁色送眉端。"]},{"t":"陈牧芷孝廉游白岳归后掩关读藏经弥年欲有下询先以折柬并赠丁南羽佛相一轴佳韵一首率笔奉答","f":"七言律诗","c":["名山归后掩幽窗，贝叶闻翻百虑降。","可有义能融宝镜，更堪谁共对银缸。","多时栽藕为高社，且自吟诗答大江。","顶相持来须着耳，裴休过后更无双。"]},{"t":"送萧柔以参戎归溽城柔以求去官而两台不可","f":"七言律诗","c":["此身真觉如山重，大略忻君有达观。","六翮欲飞何处好，一官求去不能难。","海螺有气吹千里，玉手无心弄二丸。","别后只悬高韵在，相思明月对松坛。"]},{"t":"祝词 其一","f":"七言律诗","c":["闻君七十捉鸠时，两眼青青鬓未丝。","噩梦已从今日破，嵩山应长万年枝。","行看红叶当秋下，坐悟浮云入酒卮。","最是萧王书十卷，却教人易起深思。"]},{"t":"祝词 其二","f":"七言律诗","c":["西湖十亩满秋声，白鹤峰前见月明。","桂树喜看霜叶老，玉麟尤爱舞衣轻。","笔花洒处江天丽，閒梦醒时水石平。","我自披云寄长啸，因风先为说无生。"]},{"t":"谢伯子过宿以诗见投时伯子年已八十一四壁已穷友生难仗予欲以一老僧期之不可为布其意而和之","f":"七言律诗","c":["往时噩梦已西东，八十年来一霎风。","愧我有言如水石，岂君无意任痴聋。","丹砂驻老难求世，野火当秋易及蓬。","珍重此情无可说，一天风雨画堂中。"]},{"t":"解虎监院六十一","f":"七言律诗","c":["慈氏初成祝愿回，十年辛苦共城隈。","事师似此方言德，及物其如只有才。","玉镜天高侵短鬓，金风人健乐春台。","担头狼狈还牵引，且对芳辰意暂开。"]},{"t":"慈被禅人八十又一","f":"七言律诗","c":["熊罴无梦到人间，口熟灵文心更閒。","旧殿朝昏常自住，陈村风雨不时还。","眼看种树俱成荫，兴至题诗且莫删。","向比赵州参我法，南泉翻愧鬓毛斑。"]},{"t":"欲为海幢化四金刚 其一","f":"七言律诗","c":["愿乞金刚四座高，长年一册压方袍。","问人每爽朱提约，在我殊怜白首劳。","念佛有时行玉兔，抡材真欲踞金鳌。","神宗旧事偏能忆，閒共诸僧说海涛。"]},{"t":"欲为海幢化四金刚 其二","f":"七言律诗","c":["名蓝日日见芳晨，嘉树同君岁岁春。","云水此时方减劫，江山何处觅斯人。","不知参术神尤壮，别却儿孙道自亲。","因惜衰宗无力振，吾年四十困风尘。"]},{"t":"诸子作病僧诗予以为非有道之病僧光半因请予赋一律","f":"七言律诗","c":["蒲团添絮月添寒，窗外花枝不耐看。","识断浮沤难觅剑，珠然风火不留盘。","鸡鸣潮上蓬头湿，人寂更阑夜语乾。","宝镜果曾偷听得，木蛇空挂碧云端。"]},{"t":"枯吟慈修两公从丹霞奉老人命至海幢强予开法却赠","f":"七言律诗","c":["丹霞禅客即双星，微雨春帆岸草青。","推毂可知恩似海，扪心无那冷成冰。","晴鸠唤树云犹墨，寒月惊弦魄未盈。","向说此宗无语句，不教钟鼓动长汀。"]},{"t":"天老人以予开法海幢见命澹归随投贺章次韵答之 其一","f":"七言律诗","c":["穷愁无计对春江，肘后谁传不死方。","欲尽半腔牛马血，未成千尺水云幢。","但存佳句吟清夜，依旧孤行向路旁。","若把瓣香烧出去，门庭从此恐无光。"]},{"t":"天老人以予开法海幢见命澹归随投贺章次韵答之 其二","f":"七言律诗","c":["元朝佳耗到相江，又喜杨岐有大方。","八面俱来支铁管，十虚全落拥云幢。","鹡鸰久共春原里，鸿雁空留大海旁。","谁识此情如帝网，宝珠尤解摄寒光。"]},{"t":"答丹霞诸兄四章时天老人以海幢主者之席见命遣侍僧走辞作此却寄 其一","f":"七言律诗","c":["黄昏清昼愿空违，此事那堪再辱之。","忍住法中当法坏，久知人患是人师。","狮王舌上狐涎溅，虎步蹄惊驽足移。","这座不容轻觊觎，执鞭惟有效驱驰。"]},{"t":"答丹霞诸兄四章时天老人以海幢主者之席见命遣侍僧走辞作此却寄 其二","f":"七言律诗","c":["南溟雷雨动蛟龙，时节天心有至公。","祇见出头凌佛祖，更无退席让英雄。","微生究过毛难擢，宝镜羞人态未工。","此意廿年消不尽，依依双眼白云中。"]},{"t":"答丹霞诸兄四章时天老人以海幢主者之席见命遣侍僧走辞作此却寄 其三","f":"七言律诗","c":["金鎞触处眼光差，若个人堪赖克家。","遍地已无椎拂久，匝天空有水云赊。","轻烟漾柳丝难驻，滑雨封坭路觉遐。","珍重黄鹂深树里，逼人心事乱如麻。"]},{"t":"答丹霞诸兄四章时天老人以海幢主者之席见命遣侍僧走辞作此却寄 其四","f":"七言律诗","c":["当头正位绝跻攀，奴隶那能入此间。","却似过鸿难寄树，恰如啸虎已忘山。","多时拚定无容说，彻底承当只等閒。","般若有锋司杀活，寒光先已夺痴顽。"]},{"t":"枯吟以百韵见投答此短章","f":"七言律诗","c":["跋涉春山不易行，慈严咫尺碧云声。","韵投百字天孙锦，气落千峰雁翅城。","通札未曾三易席，无禅真愧此时名。","肝肠君亦焚如火，话彻寒更见此情。"]},{"t":"寿旋庵都寺六十","f":"七言律诗","c":["百岁是人皆草草，惟君六十事堪称。","尽将私橐成丛席，结束孤心礼上乘。","月照夜涛秋叶静，潮归杰阁海门平。","铺成白玉黄金地，不与燕然共勒铭。"]},{"t":"华首台","f":"七言律诗","c":["花宫原自逼层霄，气压群峰见海潮。","两道水龙争涧出，千年华首入云遥。","松巅宿鹤鸣金磬，夜午过鸾响玉箫。","伏腊敢忘珠浦月，寒香勤向影堂烧。"]},{"t":"黄龙洞閒居","f":"七言律诗","c":["千尺寒流洗石颜，平分绣岭即仙斑。","衣尘有迹云能澹，秋思难明意未閒。","骤鹿食花斜踏涧，残虹行雨晚归山。","只须料理藏衰鬓，此外原来尽可删。"]},{"t":"鹰爪兰","f":"七言律诗","c":["石上寒松未易邻，寄根犹得傲江滨。","不因幽谷留浓叶，更有馀香佩远人。","半亩驻深莲社月，百年占尽岭南春。","名园已是无寻处，飞过苍鹰爪独新。"]},{"t":"天中有树名胜音","f":"七言律诗","c":["胜音无地长花枝，楼阁舒光在此时。","驾海云涛归自急，弥天风露濯嫌迟。","对人岸帻宜挥麈，阅世投林欲共谁。","打得上方钟磬好，莫教苔藓苦相欺。"]},{"t":"罗浮隐者","f":"七言律诗","c":["身逢盛世便抽簪，泌水衡门十亩阴。","疏氏但知今日意，贺家那识此时心。","碧天洗尽难寻玉，绿地耕残不见金。","閒与儿孙说桑柘，壶浆竟日自浮沉。"]},{"t":"国公诸世子邀登镇海楼次韵","f":"七言律诗","c":["层楼高峙镇南天，此会如逢阆苑仙。","海国乐闻閒暇日，山僧登记太平年。","关河带砺皇图壮，冰雪文章世子贤。","呼吸自应通帝座，彩云飞到碧窗前。"]},{"t":"送张舍人青雕复命还朝","f":"七言律诗","c":["凤池衣履带如丝，还赴炉香载笔期。","异地始传浮海咏，同寮高唱早朝诗。","云开岭树飞旌杳，潮涨江沙引缆迟。","望到天涯烟水处，鸟啼霜竹是相思。"]},{"t":"送丘太史曙戒还都改除用周鹤田韵 其一","f":"七言律诗","c":["粤海燕云万里遥，知君閒夜隔星桥。","桄榔庵冷频书叶，望阙亭高自逼霄。","凤草人间那得见，丹书天上近还招。","东风御苑承恩去，红药从看次第烧。"]},{"t":"送丘太史曙戒还都改除用周鹤田韵 其二","f":"七言律诗","c":["一曲骊歌去惘然，珊瑚洲畔惜离筵。","浑无宝玉归清橐，祇有琴书拥画船。","民朴也知生爱戴，僧閒犹自感周旋。","他时不禁遐思处，花弄晴春月满天。"]},{"t":"送丘太史曙戒还都改除用周鹤田韵 其三","f":"七言律诗","c":["海寺仙城对岸分，轻舟常破两涯云。","到来不厌蔬盘简，坐久还拈柏子焚。","脱俗总无金马色，忘机偏狎水鸥群。","临岐即怅云霄别，莲社依然重少文。"]},{"t":"送丘太史曙戒还都改除用周鹤田韵 其四","f":"七言律诗","c":["除书重召入鹓班，一夕春风黄木湾。","不羡荔枝消宦况，爱看杨柳傍溪攀。","忙催舟子开青舫，笑听人言买碧山。","自是恩深閒未得，又随阿扈凤凰还。"]},{"t":"送赵粮宪霞湄终养归山东","f":"七言律诗","c":["道赡天府计无虚，诗诵南陔思有馀。","清献又携千岁鹤，都门重见二疏书。","白云影覆沧洲近，丹叶枫留召荫迂。","几度挹君今送别，闲僧心亦羡高车。"]},{"t":"送琼州司李姚繸庵晋江宁郡丞","f":"七言律诗","c":["送君方慰识君时，宦政天涯客路知。","不独持平深雨露，还将大略息疮痍。","气临溟渤青云壮，道满乾坤白昼疑。","上国搴帷方属望，莫愁三径草离离。"]},{"t":"送孙鲁山大司马归桐城 其一","f":"七言律诗","c":["陆贾城边驻玉虬，紫髯如见采真游。","五云久识尊司马，万里偏从狎海鸥。","越井秋风吹旅舫，天涯雁影入高楼。","閒僧尚有无穷思，握麈何由对十洲。"]},{"t":"送孙鲁山大司马归桐城 其二","f":"七言律诗","c":["五色霞衣金粟身，曹源今日见通津。","草标玉手天王拥，名在瑶池锦凤驯。","镇海珠光随路远，过山梅影近人春。","帝师何必赤松去，三世因缘属老臣。"]},{"t":"送罗澹峰进士入都改除 其一","f":"七言律诗","c":["北入燕台雪未乾，天风吹雁此时寒。","几年潇洒淹词客，万里驱驰到理官。","禁苑钟声催晓梦，王程宿雾袭征鞍。","庾关且莫频回首，千古犹称叱驭难。"]},{"t":"送罗澹峰进士入都改除 其二","f":"七言律诗","c":["白社相过意倍投，青门此别路悠悠。","明霞出海云成锦，碧树于人气独秋。","雁塔高情常得见，凤楼宦况自堪求。","知君得遂匡时略，喜见梅花照客裘。"]},{"t":"彭退庵明府汪汉翀水部招同杨司李莲峰黄都阃君甫李副戎禹门张茂才雏隐王孝廉震生及澹归探梅篁村","f":"七言律诗","c":["东郊寻得最高枝，车骑宾朋盛此时。","雪岭烟深迷玉蝶，海门涛壮入金卮。","寒香到地平川阔，霁色光回大壑移。","赏洽袁公阑我入，十年心事对幽期。"]},{"t":"篁村探梅后月夜泊舟龙溪江口同澹归乐说觉薰乘消汝得纯铸分赋得天字","f":"七言律诗","c":["尚有馀香袭晚天，大江明月泊归船。","望穷空际疑霜隐，坐起寒潮见鹤眠。","星斗到襟浮不稳，云山老我未孤骞。","陆沉无限情难遣，只在相看两鬓边。"]},{"t":"探梅夏园 其一","f":"七言律诗","c":["殷勤觅得此林中，玉蕊粘人落不穷。","树底漫行窥晓日，山头独坐爱微风。","孤烟直起前村火，群鹤斜飞极浦空。","何日谢人无一事，尽将身世付洪濛。"]},{"t":"探梅夏园 其二","f":"七言律诗","c":["晴光十里照平原，铁干冰姿盛此村。","高士着衫归雪屋，老僧乞食到蓬门。","难将盛事追吴越，但了閒情见鹤猿。","谷口有人窥得我，此心如水已无言。"]},{"t":"凤城归舟次石壁逢罗守阃学制野泊苶话","f":"七言律诗","c":["春波明媚客途宽，忽得相逢野泊难。","看鬓有谁怜老衲，问年无计惜穷官。","閒云远远侵茶绿，春草茸茸着雾寒。","吟尽奚囊好诗句，黄昏长薄散金盘。"]},{"t":"梅花 其一","f":"七言律诗","c":["横斜雪里映蓬门，独立微吟不是村。","月照高枝云有影，风吹香瓣地无痕。","更深寒剧人先瘦，群卉摧残此独尊。","最好莫从芳树觅，眼前红紫见犹存。"]},{"t":"梅花 其二","f":"七言律诗","c":["碧叶辞枝月满梢，十分寒色在西郊。","目穷寥廓无人到，影隔空濛有鹤巢。","懒向丹峰消白日，閒随雪路踏黄茅。","此情尚未消磨尽，千古尘埃足解嘲。"]},{"t":"送姚梅长游江左兼寄令弟六康明府 其一","f":"七言律诗","c":["万里云涛起大关，柳条折得送人间。","法门昆仲吾尤拙，宦海埙篪尔独閒。","一剑自然寒绿水，七言真可咏青山。","举头若见苏堤月，可着貂裘醉里还。"]},{"t":"送姚梅长游江左兼寄令弟六康明府 其二","f":"七言律诗","c":["壮游那复问王程，是处江城有笛声。","五岳尚为婚嫁累，千金已觉水云轻。","孤帆斜挂滩头日，细雨寒生旅夜情。","千古江湖谁着眼，高鶱真欲羡鸿冥。"]},{"t":"送姚梅长游江左兼寄令弟六康明府 其三","f":"七言律诗","c":["三载怀人客梦劳，皖公山下碧桃高。","名园负瓮虚良月，大邑弹琴起夜涛。","官酒可浇行路色，家书亲拆阿兄袍。","丹砂纵有知何用，乐事应看变二毛。"]},{"t":"送张葵轩总戎北行","f":"七言律诗","c":["二十年来许国身，腰间玉剑少烟尘。","一官乍罢无新业，万里秋行有故人。","共我同堂参佛祖，怀君一路及冬春。","圣朝颇牧今尤重，会见纶音下紫宸。"]},{"t":"送刘峡石侍御终养归寿春","f":"七言律诗","c":["官舟归去粤江浔，北阙陈情见此心。","旅食久愁清橐少，高吟长忆旷怀深。","岭头黄叶当秋下，天上青云过眼阴。","却较二疏尤洒落，宗人那得散黄金。"]},{"t":"寄怀管钟石使君","f":"七言律诗","c":["几年海寺起泷云，泷水清清忆使君。","秋菊正开官酒熟，霜鸿才下郡齐闻。","乡心易对青山薄，诗兴閒从碧树分。","閒把好香烧夜月，此中无限在高旻。"]},{"t":"赠侯筠庵文宗","f":"七言律诗","c":["文衡校就玉壶高，千顷寒梅覆绿涛。","鲁国自无骀兀者，冀群真有九方皋。","心平碧树齐松柏，道契莲峰起谢陶。","一粒火齐光照我，欣君先已得神毫。"]},{"t":"送王允调侍御还京","f":"七言律诗","c":["骢马星行领部时，又随纶綍返京畿。","飞霜官路闻猿语，晴日江船曝豸衣。","道力自深能蕴藉，高名常在有光辉。","又怀大泽施何处，目对离情意尽违。"]},{"t":"送董天因总宪出使南海还朝","f":"七言律诗","c":["八座台星入望高，輶轩暂得驻云涛。","南溟气色传三殿，北极恩光戴六鳌。","岭路江花迎绣斧，王程春泽湿征袍。","下帷旧有群儒望，万里今瞻天使劳。"]},{"t":"寿吴锦雯司李尊人静腑八十一初度","f":"七言律诗","c":["能承仁爱起春霖，作宦天南白发心。","姓字月中高阚泽，文章社里得东林。","丰神听我传孤韵，杖履因人寄好音。","最健风轮堪住劫，扶桑云气涌盘金。"]},{"t":"赠高澹庵明府","f":"七言律诗","c":["家声麟阁五云堆，万里番阳简命来。","玉管有花应匝县，讼庭无事辄登台。","易将大业苏民瘼，静觉醇风入酒杯。","任水不须寻处士，竹林精舍待君开。"]},{"t":"送陈园公明府归韩江","f":"七言律诗","c":["暂宰河阳兴复空，一生青眼仕途中。","文章到老添强健，世态凭谁说异同。","此日归帆秋水绿，他时掩室夕阳红。","送君我亦劳挥麈，共念江亭有朔风。"]},{"t":"送郑野臣移家桂林","f":"七言律诗","c":["阳羡难求负郭田，移家西入九嶷天。","寒江自发孤帆雨，壮气全收大漠烟。","灌水桔槔机独转，谙时文字法堪传。","送君无限劳人意，极目飞鸿何处边。"]},{"t":"南海神祠","f":"七言律诗","c":["功齐玄默拥高幡，海色沧茫敞祀门。","金殿气藏千族雨，玉舆神数百灵尊。","怀柔代见存芳碣，崇秩今传出禁垣。","禋类六宗蕃万姓，更谁憔悴走乾坤。"]},{"t":"浴日亭次苏东坡韵","f":"七言律诗","c":["平望沧茫远接天，风吹高影落前湾。","红潮直射三更眼，白练深围十月山。","清切猿声喧夜气，漂零鹤羽对寒颜。","神州连石无寻处，只在扶桑未跃间。"]},{"t":"西台","f":"七言律诗","c":["西台髣髴旧时心，十载还同入故林。","晚炊人烟连寺火，当门树色接潮音。","磴悬海月犹堪上，路近梅花辄易寻。","却把秃头横戴帽，莫教惊觉二毛侵。"]},{"t":"波罗庙达奚司空","f":"七言律诗","c":["幸非化石犹存骨，忍见连天水没船。","去国情怀饶未死，他乡云树已堪怜。","越人章甫焉知贵，尘世虚名祇自传。","欲语精灵方语隔，海光如昼夜如年。"]},{"t":"海珠寺 其一","f":"七言律诗","c":["三山漂却此山存，南渤横流足巨吞。","宝角寒星飞水国，玉鞍神马堕云根。","磬沉响跃扶桑日，龙过身遮古寺门。","我似漆胶移未得，上方钟鼓对黄昏。"]},{"t":"海珠寺 其二","f":"七言律诗","c":["虚无一蜃结楼台，碧瓦高连粤秀开。","八水尽朝珠气入，二丸还照佛光来。","寒窗僧去难巢鹤，夜角秋深自落梅。","咫尺尘寰人莫到，不堪今昔动馀哀。"]},{"t":"过飞来寺 其一","f":"七言律诗","c":["何代飞来壮此山，却令兵燹委尘寰。","一回又见成今古，百岁那堪几往还。","观水亦知禅定好，闻钟未许客愁删。","金函探意原无着，惭愧秋空镇日閒。"]},{"t":"过飞来寺 其二","f":"七言律诗","c":["旧迹犹来可暂登，高栖我意别崚嶒。","人情阅遍伤流水，鹤梦难寻愧老僧。","绝巘猿声深佛宇，半江鼍雾逗渔灯。","关情最是幽悽景，却被身忙总未曾。"]},{"t":"过飞来寺 其三","f":"七言律诗","c":["碧波深绕树丛青，画栋朱甍出化城。","千古竟谁知静理，一时行客动閒情。","玉环归洞虚持捉，锦缆盘江讶重轻。","举世劳劳何事好，吟残微雨月微明。"]},{"t":"登问归亭 其一","f":"七言律诗","c":["两年闻搆问归亭，却讶今秋得径登。","新目恰飘今日雨，古榕犹度旧时声。","绀宫气壮江流疾，谢豹啼深木叶平。","我愿人寰犹未满，可堪惆怅此时情。"]},{"t":"登问归亭 其二","f":"七言律诗","c":["天风吹落到炎州，今日登临匪昔游。","文士有怀应载笔，閒僧无事独孤舟。","深根古柏通莲座，嫩叶新松荫石头。","破衲岂宜罨画里，又栘竹节上层楼。"]},{"t":"宿琵江口","f":"七言律诗","c":["半叶萧萧夜雨侵，又将残梦寄浮沉。","更阑始觉原为客，岁去难酬未了心。","敝絮两重支暗漏，寒风十里到孤吟。","华亭渔父吾尤尚，芳迹何年得并寻。"]},{"t":"再题飞来寺壁","f":"七言律诗","c":["十世为僧遍住山，个中宾主未容删。","折芦碧海人犹去，负笈黄梅夜自还。","隔岭暮猿无静泪，近江秋草有愁颜。","他年若遂携瓢志，依旧题诗过此间。"]},{"t":"江上孤桨同汝得","f":"七言律诗","c":["碧天孤桨暮烟浮，箬帽閒心数浴鸥。","仰卧江云疑隔世，独依估客作邻舟。","沙堆平起黄金岸，月上斜拖白玉钩。","爱似北风吹雨去，万山同汝弄溪流。"]},{"t":"独树","f":"七言律诗","c":["三年涷雨夜江过，独树犹疑塔影多。","客路自忙难觅荫，霜威虽烈不成柯。","如虬直起能争日，似石横当竟压河。","最是不堪频属目，几多人事暗消磨。"]},{"t":"送轮洁融办二子归省霅川时在相江道中 其一","f":"七言律诗","c":["北风送汝此心难，况值新梅照岭乾。","巢破幸馀双钵在，雪深空有一庭寒。","往时噩梦凭谁醒，向后微言只独看。","若忆三生缘未断，香花重扫旧蒲团。"]},{"t":"送轮洁融办二子归省霅川时在相江道中 其二","f":"七言律诗","c":["双雁南飞却欲回，朔风吹过望乡台。","浅予道力怜儿女，深尔江云任去来。","岭路辛勤逢月暗，离颜整顿为亲开。","撑持已见衰无力，早晚相寻认死灰。"]},{"t":"与诸子登飞来寺至半山怯风而返","f":"七言律诗","c":["三年重此驻扁舟，一样登临两样愁。","力尽已无高峡气，情深空对大江秋。","丝丝短鬓朝霜薄，黯黯寒云下界浮。","因向此中思半响，人间那得几淹留。"]},{"t":"江中山影与诸子分赋","f":"七言律诗","c":["日落轻帆对岸收，空山到插入寒流。","人无冷眼看难见，水有微风影更浮。","终古鸿濛忘远近，一般青翠历春秋。","蛟龙乘月吹珠起，髣髴身疑在上头。"]},{"t":"宿峡口","f":"七言律诗","c":["今夜又依高峡宿，一年心眼且新鲜。","风声入树猿应语，鹤影横江人未眠。","怪石看多追太古，微波寒渐起虚烟。","吾生亦是无涯者，老去凭谁负此肩。"]},{"t":"浈阳峡","f":"七言律诗","c":["不信江流有路通，双岩忽裂见虚空。","石屏生觉霜筠细，云窦斜开鸟道穷。","夜静爱当船上月，心閒受得峡中风。","随时歇处吾归处，辛苦都来怯塞鸿。"]},{"t":"峡水与诸子饮","f":"七言律诗","c":["香冽真难得此杯，碧波如日去无回。","已矜入口轻风起，更爱同人客况开。","露暗草根寒自栗，月高篷背兴难裁。","临流不遣从何遣，也胜林逋独赏梅。"]},{"t":"缆路","f":"七言律诗","c":["千寻云栈与天齐，衰草残阳鸟正啼。","仄岭有风难续命，断桥逢水未鸣鸡。","清波怒噬欺人迹，紫陌长平愧马蹄。","作客累人心更苦，木瓢何日定高栖。"]},{"t":"滩梦","f":"七言律诗","c":["高梦虚听未可名，疏篷寒气透衫轻。","村无夜杵荒城隔，树有残阳落叶声。","喧咽教人迷上下，纵横何日得深平。","长边勒马如逢此，不怨晨鸡逐晓程。"]},{"t":"观音岩","f":"七言律诗","c":["大士岩龛擘玉莲，杨枝数点走江烟。","明垂石乳奔空下，暗引云梯入户连。","夜半鸟归双翮壮，六时龙护一珠悬。","每逢过此霜频重，绿鬓虚侵又一年。"]},{"t":"舟中分栗与诸子","f":"七言律诗","c":["一筐山栗因人惠，数十禅僧论腊归。","剥后更疑滩石嫩，炊来方及暮云肥。","吞津香过云门饼，笑月携过弹子矶。","数载辛勤插桐叶，疏钟鸾影尚依微。"]},{"t":"滩声","f":"七言律诗","c":["阁阁遥知舟欲停，几多人上岸先行。","水经沸过波尤白，路渐高时石乱横。","翡翠啄鱼能独立，琉璃挂火不成明。","浮生称意真难得，不是嚣声即此声。"]},{"t":"予欲登飞来寺顶至半山亭怯风不能行不挂超汉自显三子掖之而下","f":"七言律诗","c":["空山高望石磷磷，短杖支离已怆神。","衰去久知非一日，病来犹仗汝三人。","猿声空落枫枝冷，草阁斜悬霜气新。","假我廿年完底事，莫教辜负翠屏春。"]},{"t":"滩梦","f":"七言律诗","c":["江湖无计百情疏，灯暗更阑掩梵书。","不似钟声归海寺，分明秋色满华胥。","罗浮蛱蝶魂偏冷，庾岭宾鸿雪正初。","乍觉只嫌衫絮薄，始知药盌强扶予。"]},{"t":"寿见一","f":"七言律诗","c":["廿载心情此日看，世人同谱我同坛。","小楼烟雨卑栖极，峻岭薯芋供食难。","凝公寮里汤仍沸，南老船头力又单。","鼻大耳长原有种，不须人说大还丹。"]},{"t":"送彭退庵考功赴都","f":"七言律诗","c":["数载相依樾荫浓，政閒话彻隔江钟。","分情独恋峰头侣，望远空瞻日下踪。","天上新秋催紫陌，山门古色映青松。","五云瑞气知多少，为洒菩提叶影重。"]},{"t":"喜沈存西至自端州","f":"七言律诗","c":["西风一棹到仙城，话彻端州共此情。","洒落自然天下士，高閒犹近水云声。","材华令子知名重，老大如君觉世轻。","我病喜逢重九日，此中无地可同凭。"]},{"t":"寄寿龚西樵六十又一","f":"七言律诗","c":["有子能教夺大魁，优昙花好此时开。","梦中佛语鸣金玉，眼底云情悟去来。","珠海独深莲社月，鹅湖同庆老人杯。","锦堂银烛明如昼，一路箫声下吹台。"]},{"t":"莫炯心走都门三载谒诠部考选得官归琼海过别诗以送之且讯诸社好 其一","f":"七言律诗","c":["别去常常恋此情，明开道眼博浮名。","几年便可悬金印，万里真难走玉京。","御苑柳阴随地绿，琼山海色照人清。","丹黄烂熟循良传，岂谓匡时计未成。"]},{"t":"莫炯心走都门三载谒诠部考选得官归琼海过别诗以送之且讯诸社好 其二","f":"七言律诗","c":["曾开白社向琼台，好友如林共茗杯。","永岁独悬沧海月，多时空折岭头梅。","閒敲玉磬催晨梵，静数金风动律灰。","渐去流光头渐白，送君心事独徘徊。"]},{"t":"送胡绢庵郡丞赴秦中 其一","f":"七言律诗","c":["黄河策马到潼关，却似梅花岭外还。","一县政成留姓字，千秋交谊重人间。","临岐道路迎红叶，济世风云起白山。","西岳芙蓉多秘迹，好从方士授金丹。"]},{"t":"送胡绢庵郡丞赴秦中 其二","f":"七言律诗","c":["来暮歌声此际欢，王程深雪拥征鞍。","搴帷坐见青山入，布政行看紫气团。","月影秋河光更动，鸡鸣荒戍树尤寒。","分明记得斯时节，他日还寻共倚阑。"]},{"t":"秋夜莫易心过宿此赠","f":"七言律诗","c":["君家兄弟雪霜清，万里尤深世外情。","香载宝车归宝地，文高时调古时名。","远帆挂日欺鲸浪，短札捎云忆雁声。","且向柴门谈夜月，功名究竟是浮生。"]},{"t":"程周量擢民部 其一","f":"七言律诗","c":["当秋几度望京云，落叶江头影自分。","乞食少因惭此道，阅人多更转怀君。","玉河夜雪宜官酒，秘苑奇书领异闻。","静把此心供献替，词坛谁与论鸿文。"]},{"t":"程周量擢民部 其二","f":"七言律诗","c":["地官晋擢佐贤劳，杳霭鹓鸿翼并高。","元凯度支关国计，茂先博物副民曹。","俸钱未可谋新甑，朝服依稀只旧袍。","独有花田莲叶社，月明虚听渡江舠。"]},{"t":"送李蠖庵司李改除归鄗上","f":"七言律诗","c":["锦袍玉管进贤冠，琰琬文坛格外看。","尅意已多平反狱，爱人尤羡古刑官。","江头雨气催帆急，寺里钟声续话难。","料理乌藤挑箬帽，访君定向五云端。"]},{"t":"答杨髯公","f":"七言律诗","c":["砻得龙文不种瓜，耳根偏解听寒笳。","文章青史传孤管，天地浮生任客槎。","走马始知秦地月，逢人方羡武陵花。","解空更欲同君语，却爱刘协学出家。"]},{"t":"送刘木生明府归吉水","f":"七言律诗","c":["官舟归去即虚舟，一帙新诗尽是秋。","对老罗浮频有梦，弹成单父长微愁。","镜中短鬓霜犹黑，衫袖仙云冷欲流。","他日出山君记取，银河终古月如钩。"]},{"t":"赠赵虎山","f":"七言律诗","c":["知己真堪一剑酬，果然血战势无休。","膏肓三洞声犹壮，箭镞频穿水并流。","霜冷官舟烟似雾，气争寒海月如钩。","更谁猿臂蓬边立，只有宁馨在上头。"]},{"t":"张威如副戎刚毅之性过人每欲小忍而不得索予作诗戒之因书五十六字奉勖","f":"七言律诗","c":["将军烈气凛如霜，玉弩横开破大荒。","拾履昔曾趋圯石，封侯今欲嗣张良。","面乾蕴藉存风度，仁术英雄起庙廊。","我有杨枝甘露水，为君三献即霞觞。"]},{"t":"送竹淇园大参","f":"七言律诗","c":["八座风云拥去旌，丰碑千载石羊城。","岭南紫气迎秋色，天上黄河过客情。","绛节易高金阙梦，瑶台暂拾玉芝行。","旧时琴鹤仍留别，典向人间为远程。"]},{"t":"和澹归韵九首 其一","f":"七言律诗","c":["鸡鸣又逐下山风，星落云重路尚蒙。","未出朝暾烟在水，既归华表鹤离空。","人间寒热一身里，大地悲凉百岁中。","世去时移看若此，力穷心拙道还穷。"]},{"t":"和澹归韵九首 其二","f":"七言律诗","c":["即使重裘也觉寒，推蓬枕畔见层峦。","去憎乱石堆高岸，归爱轻帆吼夜湍。","无数云霞迂笑傲，几多鸥鸟自蹒跚。","近怀不是重重恶，一月那伤行路难。"]},{"t":"和澹归韵九首 其三","f":"七言律诗","c":["十载龙堆泣大霜，至今无计避行藏。","鲸归碧海事还有，僧老青山信又荒。","对我崎岖看怪石，愁人曲折是鸣螀。","吟魂搅彻浑难寐，百梦无如此梦长。"]},{"t":"和澹归韵九首 其四","f":"七言律诗","c":["一处心肝几处悬，常啼纵死却关天。","欲明是玉难为脚，不去挑柴也负肩。","火入巨溟终竭海，丝连危石莫沉渊。","洪濛万古无人判，骨似轻埃不用怜。"]},{"t":"和澹归韵九首 其五","f":"七言律诗","c":["世机倾动似轻梭，何处堪容赞与诃。","掘地若能寻上古，补天方信有神娲。","猿啼暮岭魂难醒，浪打高岩石易磨。","且系孤舟依峡宿，静看寒月照悬萝。"]},{"t":"和澹归韵九首 其六","f":"七言律诗","c":["摩醯品字一齐开，失路原因得路埋。","长见秋风吹鹢首，管收和泪泣驴胎。","金轮负铁终成塔，玉露侵人不上台。","君已白头吾渐老，三夫市虎谤还来。"]},{"t":"和澹归韵九首 其七","f":"七言律诗","c":["乞食难逢宇宙清，菊花无计觅残英。","正当好境有猿啸，未必愁人尽水声。","雨暗忆过三老坳，夜深还下五婆城。","独持此意知多少，千尺云峰插石屏。"]},{"t":"和澹归韵九首 其八","f":"七言律诗","c":["长吟曲岸送归舟，片叶投江影自浮。","水落新痕依独鹤，日斜枯木过鸣鸠。","心田有路寻难见，鬓雪无声独暗流。","纵使云擎石狮子，错令人笑强抬头。"]},{"t":"和澹归韵九首 其九","f":"七言律诗","c":["远沙常白树常蓝，细碎平生有独惭。","且尽悲欢成钝鸟，先欣师友得名岩。","木蛇宛转无长短，宝镜明蒙隔圣凡。","食蔗流年宜渐好，肯呵涷手擘霜柑。"]},{"t":"姚梅长陵阳江左游三年戊申除夕始还海幢度岁后乃归丰湖喜从望外因赋五十六字","f":"七言律诗","c":["喜见征尘拂草庐，三年无计觅双鱼。","消残旧梦看春入，读罢新诗便岁除。","九子云烟吟兴阔，五陵霜雪世情疏。","鹅湖夜月能明否，归去还当重寄予。"]},{"t":"寄祝黎母兼送传人孝廉公车","f":"七言律诗","c":["弥天笙乐奏金璈，重望瑶池鹤驭高。","五福锦堂留岁月，千寻玉树奏云涛。","凤文天阙探龙虎，马足春坭带杏桃。","养志自然超上寿，蓬山真有六头鳌。"]},{"t":"姚玉郎秋捷","f":"七言律诗","c":["桂枝折得应培树，云路将锄好照心。","只是平常贤圣理，也须仔细学人寻。","月光午夜天河满，花气三春地脉深。","从此金门一献赋，喜看声誉动词林。"]},{"t":"海紫三秋捷","f":"七言律诗","c":["风节名臣世系长，乾坤元气此时昌。","十年先许操文笔，九日真能折桂香。","影入斗牛沧海动，赋归金马紫薇光。","几多道侣相期甚，总被青云出岫忙。"]},{"t":"寄寿海南李言兑","f":"七言律诗","c":["文坛久已擅仪型，七十年来风月清。","世不识材甘阁笔，天能赋物枉聪明。","西窗我每牵孤梦，南极君为老客星。","海市蜃楼互遮映，相思终古隔深情。"]},{"t":"吴伯子候榜五羊过宿此赠","f":"七言律诗","c":["秋水文心自售时，却欣相见慰离思。","十年谑语悬高座，半世交情许独知。","割肉无心齐宰社，冲天有翼寄修篱。","可能老去探玄理，此外风尘何所期。"]},{"t":"答黄存庵","f":"七言律诗","c":["独许知君即姓庞，可能一口竭西江。","波侵学海千层起，气压文峰万派降。","喜见清风生宝地，应留幽梦挂虚容。","梅花岭外如相忆，短策高吟意已将。"]},{"t":"己酉夏五月本师天老人二诗送澹西堂下海幢兼寄示无次韵恭和 其一","f":"七言律诗","c":["石尤风只逆归船，日日残春送晓天。","近角自吹寒月外，閒心空照夜灯前。","且欣好友同三夏，不觉离师又八年。","老去踉跄无善计，当时错许杖头边。"]},{"t":"己酉夏五月本师天老人二诗送澹西堂下海幢兼寄示无次韵恭和 其二","f":"七言律诗","c":["楚璞无因惹刖愁，眼穿层縠笑神州。","能言此道霜消鬓，不见閒时月满楼。","泥絮岂堪支古调，云林何用梦沧洲。","三岩松柏年年绿，一任流澌滑石头。"]},{"t":"己酉夏五月海幢抽并头兰两枝适澹归西堂至自丹霞有诗亦引其意作二律即以志喜 其一","f":"七言律诗","c":["君子宜花引类清，始知吾道未孤行。","双轮独现高空影，一蒂先传妙叶情。","已爱紫荆敦往事，休将白水插閒瓶。","寻常亦有伤怀意，无著虚传弟与兄。"]},{"t":"己酉夏五月海幢抽并头兰两枝适澹归西堂至自丹霞有诗亦引其意作二律即以志喜 其二","f":"七言律诗","c":["金针双锁意尤高，风叶潇疏引兴豪。","古佛不藏尊贵顶，贫儿齐着到家袍。","分香远蝶惭孤至，带露新蕤结两遭。","利断倘能支晚暮，微蝇终托马蹄毛。"]},{"t":"萧柔以参戎力辞专阃告入曰可遂得挂冠道归仙羊过叙适值览揆赋赠","f":"七言律诗","c":["何当竟事赤松游，勇退真能在急流。","自挂雕弓称达士，不教燕颔更封侯。","霸陵有酒空消日，大树无声岂计秋。","归去山东参妙道，半天钟磬起红楼。"]},{"t":"赠梁华生","f":"七言律诗","c":["刻漏批来楮叶轻，多材原自属天成。","文康有后书声远，佛地无尘宝月清。","意入明珠生九曲，刀迎坭鼻见双平。","因君悟得无传理，始觉天孙锦未精。"]},{"t":"杨翰馨秋捷","f":"七言律诗","c":["而兄新说闽中法，季弟能探己酉秋。","选佛选官双足举，好头好尾一齐收。","云从地上乘风起，月在天衢作势流。","珍重境缘深道力，莫教心水有浮沤。"]}]};